INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('975','announcement','<html>\r\n<head>\r\n<title>{$lang->announcements[\'forum_announcement\']}</title>\r\n\r\n<script type=\"text/javascript\">\r\nvar announcement_quickdelete_confirm = \"{$lang->announcements[\'announcement_quickdelete_confirm\']}\";\r\n</script>\r\n</head>\r\n<body>\r\n\r\n	<div class=\"container-md\">\r\n		\r\n		<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n		{$forum_announcement}\r\n	</div>\r\n		</div>\r\n\r\n\r\n	{$announcement}\r\n			\r\n	</div>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('976','announcement_edit','<a href=\"modcp.php?action=edit_announcement&amp;aid={$post[\'aid\']}\" title=\"{$lang->announcements[\'announcement_edit\']}\" class=\"postbit_edit postlinks\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;{$lang->global[\'postbit_button_edit\']}</a>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('977','announcement_quickdelete','<a href=\"modcp.php?action=delete_announcement&amp;aid={$post[\'aid\']}&amp;my_post_key={$mybb->post_code}\" class=\"postbit_qdelete dropdown-item p-2\">\r\n<i class=\"fa-solid fa-trash\"></i> &nbsp;{$lang->global[\'postbit_button_qdelete\']}</a>','2','1837','','1720609281');
