INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1037','forumbit_depth1_cat','<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/forum.js\"></script>\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/include/templates/default/style/forum.css\">\r\n<div class=\"category-card mb-4\">\r\n    <!-- Header с эффектом при наведении -->\r\n    <div class=\"card-header-custom rounded-top\" \r\n         style=\"background: linear-gradient(135deg, var(--thead-bg, #f8f9fa) 0%, color-mix(in srgb, var(--thead-bg, #f8f9fa) 80%, white 20%) 100%); \r\n                border-bottom: 3px solid rgba(var(--theme-rgb, 13, 110, 253), 0.1);\">\r\n        \r\n        <!-- Иконка раскрытия/скрытия -->\r\n        <div class=\"expand-toggle float-end\" onclick=\"toggleCategory({$forum[\'fid\']})\">\r\n            <i class=\"bi bi-chevron-down expand-icon\" id=\"cat_{$forum[\'fid\']}_icon\"></i>\r\n        </div>\r\n        \r\n        <!-- Основной контент заголовка -->\r\n        <div class=\"header-content\">\r\n            <!-- Название форума с эффектом -->\r\n            <h5 class=\"category-title mb-1\">\r\n                <a href=\"{$forum_url}\" class=\"category-link\">\r\n                    <i class=\"bi bi-folder2-open me-2\" style=\"color: rgba(var(--theme-rgb, 13, 110, 253), 0.7);\"></i>\r\n                    {$forum[\'name\']}\r\n                </a>\r\n                \r\n\r\n\r\n            </h5>\r\n            \r\n            <!-- Описание с плавным появлением -->\r\n            <div class=\"category-description mt-2\">\r\n                <p class=\"text-muted mb-0 small\">\r\n                    <i class=\"bi bi-info-circle me-1\"></i>\r\n                    {$forum[\'description\']}\r\n                </p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <!-- Тело карточки с плавной анимацией -->\r\n    <div class=\"card-body-custom rounded-bottom\" \r\n         id=\"cat_{$forum[\'fid\']}_e\" \r\n         style=\"display: {$expdisplay}; \r\n                background: linear-gradient(to bottom, white 0%, #fafbfc 100%);\">\r\n        \r\n        <!-- Анимация загрузки подфорумов -->\r\n        <div class=\"subforums-container\" id=\"subforums_{$forum[\'fid\']}\">\r\n            {$sub_forums}\r\n        </div>\r\n    </div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1038','forumbit_depth1_forum_lastpost','<avatarep_uid_[{$lastpost_data[\'lastposteruid\']}]><div class=\"d-none d-md-block d-lg-block gridh\">\r\n	<p style=\"margin-bottom: 0px\"><a href=\"{$lastpost_link}\"><span class=\"fw-bold\">{$lastpost_subject}</span></a><br /><svg class=\"bi bi-reply-all-fill text-muted\" xmlns=\"http://www.w3.org/2000/svg\" width=\"1em\" height=\"1em\" fill=\"currentColor\" viewBox=\"0 0 16 16\">\r\n            <path d=\"M8.021 11.9 3.453 8.62a.719.719 0 0 1 0-1.238L8.021 4.1a.716.716 0 0 1 1.079.619V6c1.5 0 6 0 7 8-2.5-4.5-7-4-7-4v1.281c0 .56-.606.898-1.079.62z\"></path>\r\n            <path d=\"M5.232 4.293a.5.5 0 0 1-.106.7L1.114 7.945a.5.5 0 0 1-.042.028.147.147 0 0 0 0 .252.503.503 0 0 1 .042.028l4.012 2.954a.5.5 0 1 1-.593.805L.539 9.073a1.147 1.147 0 0 1 0-1.946l3.994-2.94a.5.5 0 0 1 .699.106z\"></path>\r\n		</svg> {$lastpost_profilelink} <span class=\"text-muted\">{$lastpost_date}</span></p>\r\n	\r\n	<div class=\"text-end\">\r\n	<a href=\"{$forum_url}\"><p class=\"text-end badge badge-warning catmod p-2 mb-0\">\r\n		 {$forum[\'name\']} &nbsp; \r\n		</p></a>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1039','forumbit_depth2_cat','<div class=\"row p-0\">\r\n		<div class=\"col-1 align-self-center d-none d-md-block d-lg-block\" style=\"width:50px\">\r\n        <div id=\"mark_read_{$forum[\'fid\']}\" class=\"forum_status forum_{$lightbulb[\'folder\']} ajax_mark_read\" title=\"{$lightbulb[\'altonoff\']}\"><i class=\"bi bi-chat-fill\"></i></div>\r\n    </div>\r\n    <div class=\"col-3 align-self-center p-2\" style=\"width:500px\">\r\n         <div><strong><a href=\"{$forum_url}\">{$forum[\'name\']}</a></strong>{$forum_viewers_text}<div class=\"smalltext\" style=\"font-size: 16px;\">{$forum[\'description\']}{$modlist}{$subforums}</div>\r\n        </div>\r\n    </div>\r\n    <div class=\"col align-self-center text-center d-none d-lg-block\"  style=\"width:auto\">\r\n        <div>{$threads}{$unapproved[\'unapproved_threads\']}<br />\r\n            <p class=\"text-muted\" style=\"font-size: 13px;margin-top: 0px;\">threads</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"col align-self-center text-center d-none d-lg-block\"  style=\"width:auto\">\r\n        <div>{$posts}{$unapproved[\'unapproved_posts\']}<p class=\"text-muted\" style=\"font-size: 13px;margin-top: 0px;\">posts hi</p>\r\n        </div>\r\n    </div>\r\n    <div class=\"col-1 align-self-center d-none d-lg-block\"  style=\"width:auto\">\r\n        <div class=\"bg-light justify-content-center align-items-center align-content-center align-self-center border rounded border-1\" style=\"padding: 6px;width: 50px;height: 50px;float: right;margin-right: 20px;\"><svg class=\"bi bi-person-fill text-black-50\" width=\"1em\" height=\"1em\" viewBox=\"0 0 16 16\" style=\"font-family: Quicksand, sans-serif;font-size: 30px;\">\r\n                <path d=\"M3 14s-1 0-1-1 1-4 6-4 6 3 6 4-1 1-1 1H3zm5-6a3 3 0 1 0 0-6 3 3 0 0 0 0 6z\"></path>\r\n            </svg></div>\r\n    </div>\r\n    <div class=\"col-2 align-self-center text-right p-2\" style=\"width:250px\">\r\n        <div>{$lastpost}</div>\r\n		</div></div>\r\n\r\n<br />','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1040','forumbit_depth2_forum','<div class=\"forum-item\" data-fid=\"{$forum[\'fid\']}\">\r\n    <div class=\"forum-card p-4 rounded-4 shadow-sm mb-3 border-0\">\r\n        <div class=\"row g-4 align-items-center\">\r\n            <!-- Иконка статуса - ИСПРАВЛЕННАЯ -->\r\n<!-- Иконка статуса - с popover вместо title -->\r\n<div class=\"col-auto\">\r\n    <div id=\"mark_read_{$forum[\'fid\']}\" \r\n         class=\"forum-status-indicator forum_status forum_{$lightbulb[\'folder\']} ajax_mark_read\"\r\n         onclick=\"toggleForumRead({$forum[\'fid\']})\"\r\n         data-bs-toggle=\"popover\" \r\n         data-bs-trigger=\"hover focus\"\r\n         data-bs-html=\"true\"\r\n         data-bs-placement=\"top\"\r\n         data-bs-title=\"<i class=\'fa-solid fa-info-circle me-2\'></i>Forum Status\"\r\n         data-bs-content=\"<div class=\'popover-content\'>\r\n             <div class=\'mb-2\'><strong>{$lightbulb[\'altonoff\']}</strong></div>\r\n             <div class=\'small text-muted\'>Click to mark as read</div>\r\n         </div>\">\r\n        \r\n        <div class=\"status-circle pulse-hover\">\r\n            <i class=\"status-icon fa-solid fa-circle\"></i>\r\n            \r\n            <!-- Бейдж показываем только для новых сообщений -->\r\n            <span class=\"new-badge\">\r\n                <i class=\"fa-solid fa-bolt\"></i>\r\n            </span>\r\n        </div>\r\n    </div>\r\n</div>\r\n            \r\n\r\n            <!-- Основное содержимое -->\r\n            <div class=\"col\">\r\n                <div class=\"forum-content\">\r\n                    <!-- Заголовок и мета-информация -->\r\n                    <div class=\"d-flex flex-wrap align-items-center gap-2 mb-3\">\r\n                        <h4 class=\"forum-title mb-0\">\r\n                            <a href=\"{$forum_url}\" class=\"forum-link\" data-forum=\"{$forum[\'fid\']}\"\r\n                               data-bs-toggle=\"popover\"\r\n                               data-bs-trigger=\"hover\"\r\n                               data-bs-html=\"true\"\r\n                               data-bs-placement=\"top\"\r\n                               data-bs-title=\"<i class=\'fa-solid fa-folder-open me-2\'></i>{$forum[\'name\']}\"\r\n                               data-bs-content=\"<div class=\'popover-content\'>\r\n                                   <div class=\'mb-2\'><strong>Description:</strong> {$forum[\'description\']}</div>\r\n                                   <div class=\'small text-muted\'>Click to open Forum</div>\r\n                               </div>\">\r\n                                <i class=\"forum-icon fa-solid fa-folder-open me-2\"></i>\r\n                                <span class=\"forum-name\">{$forum[\'name\']}</span>\r\n                            </a>\r\n                        </h4>\r\n                        \r\n                        <!-- Бейджи статусов -->\r\n                        <div class=\"forum-badges d-flex gap-2\">\r\n                           \r\n                            <span class=\"badge bg-primary bg-opacity-10 text-primary\"\r\n                                  data-bs-toggle=\"popover\"\r\n                                  data-bs-trigger=\"hover\"\r\n                                  data-bs-placement=\"top\"\r\n                                  data-bs-title=\"<i class=\'fa-solid fa-users me-2\'></i>Online Users\">\r\n                                <i class=\"fa-solid fa-users me-1\"></i>\r\n                                {$forum_viewers_text}\r\n                            </span>\r\n                           \r\n                            \r\n                            <span class=\"badge bg-warning bg-opacity-20 text-warning\"\r\n                                  data-bs-toggle=\"popover\"\r\n                                  data-bs-trigger=\"hover\"\r\n                                  data-bs-placement=\"top\"\r\n                                  data-bs-title=\"<i class=\'fa-solid fa-clock me-2\'></i>Awaiting Moderation\">\r\n                                <i class=\"fa-solid fa-clock me-1\"></i>\r\n                                {$unapproved[\'unapproved_threads\']}\r\n                            </span>\r\n                            \r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Description -->\r\n                    <div class=\"forum-description mb-3\">\r\n                        <p class=\"text-muted mb-2\">\r\n                            <i class=\"fa-solid fa-info-circle me-2 opacity-75\"></i>\r\n                            {$forum[\'description\']}\r\n                        </p>\r\n                       \r\n                        <div class=\"moderators mt-2\">\r\n                            <span class=\"text-muted small\">\r\n                                <i class=\"fa-solid fa-user-shield me-1\"></i>\r\n                                Moderators: {$modlist}\r\n                            </span>\r\n                        </div>\r\n                        \r\n                    </div>\r\n\r\n                    <!-- Подфорумы -->\r\n                   \r\n                    <div class=\"subforums-section mt-3\">\r\n                        <div class=\"d-flex align-items-center mb-2\">\r\n                            <i class=\"fa-solid fa-sitemap me-2 text-muted\"></i>\r\n                            <span class=\"small text-muted\">Sub Forums:</span>\r\n                        </div>\r\n                        <div class=\"subforums-grid\">\r\n                            {$subforums}\r\n                        </div>\r\n                    </div>\r\n                   \r\n                </div>\r\n            </div>\r\n\r\n            <!-- Статистика (десктоп) -->\r\n            <div class=\"col-lg-auto d-none d-lg-block\">\r\n                <div class=\"forum-stats\">\r\n                    <div class=\"stats-grid\">\r\n                        <!-- Темы -->\r\n                        <div class=\"stat-item\" \r\n                             data-bs-toggle=\"popover\"\r\n                             data-bs-trigger=\"hover\"\r\n                             data-bs-placement=\"top\"\r\n                             data-bs-title=\"<i class=\'fa-solid fa-comments me-2\'></i>Threads Statistics\">\r\n                            <div class=\"stat-value\">\r\n                                <span class=\"count\">{$threads}</span>\r\n                               \r\n                                <span class=\"unapproved-count\">+{$unapproved[\'unapproved_threads\']}</span>\r\n                                \r\n                            </div>\r\n                            <div class=\"stat-label\">\r\n                                <i class=\"fa-solid fa-comments me-1\"></i>\r\n                                <span class=\"small\">Threads</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Сообщения -->\r\n                        <div class=\"stat-item\"\r\n                             data-bs-toggle=\"popover\"\r\n                             data-bs-trigger=\"hover\"\r\n                             data-bs-placement=\"top\"\r\n                             data-bs-title=\"<i class=\'fa-solid fa-comment-dots me-2\'></i>Posts Statistics\">\r\n                            <div class=\"stat-value\">\r\n                                <span class=\"count\">{$posts}</span>\r\n                              \r\n                                <span class=\"unapproved-count\">+{$unapproved[\'unapproved_posts\']}</span>\r\n                                \r\n                            </div>\r\n                            <div class=\"stat-label\">\r\n                                <i class=\"fa-solid fa-comment-dots me-1\"></i>\r\n                                <span class=\"small\">Posts</span>\r\n                            </div>\r\n                        </div>\r\n\r\n                        <!-- Последнее сообщение -->\r\n                        <div class=\"stat-item last-post\" \r\n                             data-bs-toggle=\"popover\"\r\n                             data-bs-trigger=\"hover\"\r\n                             data-bs-placement=\"top\"\r\n                             data-bs-html=\"true\"\r\n                             data-bs-title=\"<i class=\'fa-solid fa-clock me-2\'></i>Last Post\">\r\n                            <div class=\"last-post-content\">\r\n                                {$lastpost}\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Мобильная статистика -->\r\n        <div class=\"row d-lg-none mt-4\">\r\n            <div class=\"col-12\">\r\n                <div class=\"forum-mobile-stats\">\r\n                    <div class=\"row g-3\">\r\n                        <div class=\"col-6\">\r\n                            <div class=\"mobile-stat\"\r\n                                 data-bs-toggle=\"popover\"\r\n                                 data-bs-trigger=\"hover\"\r\n                                 data-bs-placement=\"top\"\r\n                                 data-bs-title=\"Threads\">\r\n                                <div class=\"mobile-stat-value\">{$threads}</div>\r\n                                <div class=\"mobile-stat-label small text-muted\">\r\n                                    <i class=\"fa-solid fa-comments me-1\"></i> Threads\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-6\">\r\n                            <div class=\"mobile-stat\"\r\n                                 data-bs-toggle=\"popover\"\r\n                                 data-bs-trigger=\"hover\"\r\n                                 data-bs-placement=\"top\"\r\n                                 data-bs-title=\"Posts\">\r\n                                <div class=\"mobile-stat-value\">{$posts}</div>\r\n                                <div class=\"mobile-stat-label small text-muted\">\r\n                                    <i class=\"fa-solid fa-comment-dots me-1\"></i> Posts\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-12\">\r\n                            <div class=\"mobile-lastpost mt-2 pt-3 border-top\">\r\n                                <div class=\"small text-muted mb-1\">\r\n                                    <i class=\"fa-solid fa-clock me-1\"></i> Last Post\r\n                                </div>\r\n                                <div class=\"last-post-content\">{$lastpost}</div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Фоновая декорация -->\r\n        <div class=\"forum-decoration\">\r\n            <div class=\"decoration-line\"></div>\r\n            <div class=\"decoration-dots\">\r\n                <span></span><span></span><span></span>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1041','forumbit_depth2_forum_lastpost','<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n\r\n<div class=\"row\">\r\n	<div class=\"col-auto align-self-center\">\r\n		<avatarep_uid_[{$lastpost_data[\'lastposteruid\']}]>\r\n			</div>\r\n		<div class=\"col align-self-center\">\r\n\r\n\r\n<p class=\"fs-7 mb-0\"><a href=\"{$lastpost_link}\">{$lastpost_subject}</a></p>\r\n			<p class=\"small text-muted mb-0 text-uppercase\">{$lastpost_date}</p>\r\n			<p class=\"small text-muted mb-0\">{$lang->global[\'by\']} <span class=\"links\">{$lastpost_profilelink}</span></p>\r\n			\r\n		</div>\r\n	</div>\r\n	\r\n	</div>\r\n	\r\n	<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n\r\n<div class=\"row py-3 bg-light mt-2 rounded\">\r\n	\r\n		<div class=\"col align-self-center\">\r\n\r\n\r\n<p class=\"fs-7 mb-0\"><a href=\"{$lastpost_link}\">{$lastpost_subject}</a></p>\r\n			<p class=\"small text-muted mb-0 text-uppercase\">{$lastpost_date}</p>\r\n			<p class=\"small text-muted mb-0\">{$lang->global[\'by\']} <span class=\"links\">{$lastpost_profilelink}</span></p>\r\n			\r\n		</div>\r\n		<div class=\"col-auto align-self-center\">\r\n		<avatarep_uid_[{$lastpost_data[\'lastposteruid\']}]>\r\n			</div>\r\n	</div>\r\n	\r\n	</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1042','forumbit_depth2_forum_lastpost_hidden','<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n\r\n<div class=\"row\">\r\n	<div class=\"col-auto align-self-center\">\r\n		<i class=\"fa-solid fa-lock icon\"></i>\r\n			</div>\r\n		<div class=\"col align-self-center\">\r\n\r\n\r\n<p class=\"fs-6 mb-0\">{$lang->global[\'lastvisit_hidden\']}</p>\r\n			\r\n		</div>\r\n	</div>\r\n	\r\n	</div>\r\n	\r\n	<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n\r\n<div class=\"row py-3 bg-light mt-2 rounded\">\r\n	\r\n		<div class=\"col align-self-center\">\r\n\r\n\r\n<p class=\"fs-6 mb-0\">{$lang->global[\'lastvisit_hidden\']}</p>\r\n			\r\n		</div>\r\n		<div class=\"col-auto align-self-center\">\r\n		<i class=\"fa-solid fa-lock icon\"></i>\r\n			</div>\r\n	</div>\r\n	\r\n	</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1043','forumbit_depth2_forum_lastpost_never','<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n\r\n<div class=\"row\">\r\n	<div class=\"col-auto align-self-center\">\r\n		<i class=\"fa-solid fa-user icon\"></i>\r\n			</div>\r\n		<div class=\"col align-self-center\">\r\n\r\n\r\n<p class=\"fs-6 mb-0\">Never</p>\r\n			\r\n		</div>\r\n	</div>\r\n	\r\n	</div>\r\n	\r\n	<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n\r\n<div class=\"row py-3 bg-light mt-2 rounded\">\r\n	\r\n		<div class=\"col align-self-center\">\r\n\r\n\r\n<p class=\"fs-6 mb-0\">Never</p>\r\n			\r\n		</div>\r\n		<div class=\"col-auto align-self-center\">\r\n		<i class=\"fa-solid fa-user icon\"></i>\r\n			</div>\r\n	</div>\r\n	\r\n	</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1044','forumbit_depth2_forum_viewers','<span class=\"smalltext text-muted\" style=\"font-size: 12px\">{$forum_viewers_text}</span>','2','1837','','1720609281');
