INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1046','forumbit_depth3_statusicon','<div class=\"subforumicon subforum_{$lightbulb[\'folder\']} ajax_mark_read ficons_{$forum[\'fid\']}\" title=\"{$lightbulb[\'altonoff\']}\" id=\"mark_read_{$forum[\'fid\']}\"><i class=\"fa-solid fa-circle\"></i></div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1047','forumbit_moderators','<div class=\"small mt-1\">moderated_by {$moderators}</div>','2','1837','','1720609281');
