INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1059','forumdisplay_password','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->global[\'password_required\']} </title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	\r\n	<div class=\"container-md\">\r\n		\r\n		<div class=\"card\">\r\n<div class=\"card-body\">\r\n<form action=\"{$_SERVER[\'REQUEST_URI\']}\" method=\"post\">\r\n\r\n<label for=\"pwverify\">{$lang->global[\'enter_password_below\']}</label><br />\r\n	<span class=\"text-desc\">{$lang->global[\'forum_password_note\']}</span>\r\n  <input class=\"form-control form-control-sm border\" name=\"pwverify\" type=\"password\" id=\"username\" value=\"\" />\r\n		<span class=\"text-danger fw-normal\" style=\"font-weight: 400!important\">{$pwnote}</span>\r\n	</div>\r\n	\r\n	<div class=\"card-footer text-center\">\r\n	<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->global[\'verify_forum_password\']}\"><i class=\"fa-solid fa-key\"></i> &nbsp;{$lang->global[\'verify_forum_password\']}</button>\r\n	</div>\r\n</form>\r\n		\r\n		</div>\r\n	</div>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
