n		\r\n		\r\n		\r\n		<li class=\"nav-item dropdown\">\r\n          <a class=\"nav-link dropdown-toggle\" href=\"#\" role=\"button\" data-bs-toggle=\"dropdown\">{$lang->global[\'staff\']}</a>\r\n          <ul class=\"dropdown-menu\">\r\n            <li><a class=\"dropdown-item\" href=\"{$BASEURL}/staff.php\">Staff Team</a></li>\r\n			<li><a class=\"dropdown-item\" href=\"{$BASEURL}/contactstaff.php\">Contact Staff</a></li>\r\n			\r\n			\r\n			 \r\n          </ul>\r\n        </li>\r\n		\r\n		\r\n        \r\n      </ul>\r\n      \r\n	  <form class=\"d-flex\" role=\"search\" method=\"post\" action=\"\"{$BASEURL}/browse.php?do=search&amp;search_type=t_both\">\r\n	  <input type=\"hidden\" name=\"search_type\" value=\"t_both\" />\r\n	  <input type=\"hidden\" name=\"do\" value=\"search\" />\r\n	 \r\n        <input class=\"form-control me-2\" type=\"text\" value=\"\" name=\"keywords\" placeholder=\"Search\" aria-label=\"Search\">\r\n        <button class=\"btn btn-light\" type=\"submit\">{$lang->global[\'storrent22\']}</button>\r\n	  \r\n      </form>\r\n	\r\n    </div>\r\n  </div>\r\n</nav>	\r\n\r\n</br>\r\n</br>\r\n\r\n\r\n<!-- /new navbar -->','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1088','headerinclude','\r\n<link rel=\"alternate\" type=\"application/atom+xml\" title=\"{$lang->latest_threads} (Atom 1.0)\" href=\"{$mybb->settings[\'bburl\']}/syndication.php?type=atom1.0\" />\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset={$charset}\" />\r\n<meta http-equiv=\"Content-Script-Type\" content=\"text/javascript\" />\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\r\n\r\n\r\n<meta name=\"generator\" content=\"{$title}\" />\r\n<meta name=\"revisit-after\" content=\"3 days\" />\r\n<meta name=\"robots\" content=\"index, follow\" />\r\n<meta name=\"description\" content=\"{$metadesc}\" />\r\n<meta name=\"keywords\" content=\"{$metakeywords}\" />\r\n\r\n\r\n\r\n\r\n\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/jquery.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/bootstrap.bundle.min.js\"></script>\r\n\r\n\r\n<!-- Bootstrap -->\r\n\r\n\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/include/templates/default/style/bootstrap.min.css\" type=\"text/css\" media=\"screen\" />\r\n\r\n<!-- /Bootstrap -->\r\n\r\n<!-- FontAwesome -->\r\n\r\n\r\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css\" integrity=\"sha512-SnH5WK+bZxgPHs44uWIX+LLJAJ9/2PkPKZ5QiAj6Ta86w+fsb2TkcmfRyVX3pBnMFcV7oQPJkl9QevSCWr3W6A==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\" />\r\n\r\n\r\n<!-- /FontAwesome -->\r\n\r\n\r\n\r\n{$avatarep_script}{$stylesheets}\r\n\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n	lang.unknown_error = \"{$lang->global[\'unknown_error\']}\";\r\n	lang.confirm_title = \"{$lang->global[\'confirm_title\']}\";\r\n	lang.expcol_collapse = \"{$lang->global[\'expcol_collapse\']}\";\r\n	lang.expcol_expand = \"{$lang->global[\'expcol_expand\']}\";\r\n	lang.select2_match = \"{$lang->global[\'select2_match\']}\";\r\n	lang.select2_matches = \"{$lang->global[\'select2_matches\']}\";\r\n	lang.select2_nomatches = \"{$lang->global[\'select2_nomatches\']}\";\r\n	lang.select2_inputtooshort_single = \"{$lang->global[\'select2_inputtooshort_single\']}\";\r\n	lang.select2_inputtooshort_plural = \"{$lang->global[\'select2_inputtooshort_plural\']}\";\r\n	lang.select2_inputtoolong_single = \"{$lang->global[\'select2_inputtoolong_single\']}\";\r\n	lang.select2_inputtoolong_plural = \"{$lang->global[\'select2_inputtoolong_plural\']}\";\r\n	lang.select2_selectiontoobig_single = \"{$lang->global[\'select2_selectiontoobig_single\']}\";\r\n	lang.select2_selectiontoobig_plural = \"{$lang->global[\'select2_selectiontoobig_plural\']}\";\r\n	lang.select2_loadmore = \"{$lang->global[\'select2_loadmore\']}\";\r\n	lang.select2_searching = \"{$lang->global[\'select2_searching\']}\";\r\n	\r\n	var templates = {\r\n		modal: \'{$jsTemplates[\'modal\']}\',\r\n		modal_button: \'{$jsTemplates[\'modal_button\']}\'\r\n	};\r\n\r\n	var cookieDomain = \"{$cookiedomain}\";\r\n	var cookiePath = \"{$cookiepath}\";\r\n	var cookiePrefix = \"{$cookieprefix}\";\r\n	var cookieSecureFlag = \"{$cookiesecureflag}\";\r\n	var deleteevent_confirm = \"{$lang->global[\'deleteevent_confirm\']}\";\r\n	var removeattach_confirm = \"{$lang->global[\'removeattach_confirm\']}\";\r\n	var loading_text = \'{$lang->global[\'ajax_loading\']}\';\r\n	var saving_changes = \'{$lang->global[\'saving_changes\']}\';\r\n	var use_xmlhttprequest = \"{$use_xmlhttprequest}\";\r\n	var my_post_key = \"{$mybb->post_code}\";\r\n	var rootpath = \"{$BASEURL}\";\r\n	var imagepath = \"{$theme[\'imgdir\']}\";\r\n  	var yes_confirm = \"{$lang->global[\'yes\']}\";\r\n	var no_confirm = \"{$lang->global[\'no\']}\";\r\n	var MyBBEditor = null;\r\n	var spinner_image = \"{$BASEURL}/pic/spinner.gif\";\r\n	var spinner = \"<img src=\'\" + spinner_image +\"\' alt=\'\' />\";\r\n	var modal_zindex = 9999;\r\n// -->\r\n</script>\r\n\r\n\r\n<script type=\"text/javascript\">\r\nwindow.onscroll = () => {\r\n  toggleTopButton();\r\n}\r\nfunction scrollToTop(){\r\n  window.scrollTo({top: 0, behavior: \'smooth\'});\r\n}\r\n\r\nfunction toggleTopButton() {\r\n  if (document.body.scrollTop > 20 ||\r\n      document.documentElement.scrollTop > 20) {\r\n    document.getElementById(\'back-to-up\').classList.remove(\'d-none\');\r\n  } else {\r\n    document.getElementById(\'back-to-up\').classList.add(\'d-none\');\r\n  }\r\n}\r\n</script>\r\n\r\n\r\n\r\n\r\n<button class=\"btn btn-primary position-fixed bottom-0 end-0 translate-middle d-none\" onclick=\"scrollToTop()\" id=\"back-to-up\">\r\n  <i class=\"fa fa-arrow-up\" aria-hidden=\"true\"></i>\r\n</button>\r\n','2','1837','','1720609281');
