INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1169','member_register','<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <title>{$SITENAME} - {$lang->member[\'welcome_register\']}</title>\r\n    \r\n</head>\r\n<body>\r\n\r\n\r\n<div class=\"container mt-3\">\r\n    {$inline_errors}\r\n    {$member_loggedin_notice}\r\n    \r\n    <div class=\"row justify-content-center\">\r\n        <div class=\"col-lg-10\">\r\n            <div class=\"card\">\r\n                <div class=\"card-header bg-primary text-white py-3\">\r\n                    <h4 class=\"mb-0\"><i class=\"fas fa-user-plus me-2\"></i> {$lang->member[\'welcome_register\']}</h4>\r\n                </div>\r\n                \r\n                <div class=\"card-body\">\r\n                    {$regerrors}\r\n                    \r\n                    <form action=\"member.php\" method=\"post\" id=\"registration_form\">\r\n                        <input type=\"text\" style=\"display: none;\" value=\"\" name=\"regcheck1\" />\r\n                        <input type=\"text\" style=\"display: none;\" value=\"true\" name=\"regcheck2\" />\r\n                        \r\n                        <!-- Секция данных аккаунта -->\r\n                        <div class=\"card-section\">\r\n                            <h5 class=\"section-title mb-4\">\r\n                                <i class=\"fas fa-user-circle me-2\"></i> {$lang->member[\'account_details\']}\r\n                            </h5>\r\n                            \r\n                            <div class=\"row\">\r\n                                <!-- Имя пользователя -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    <label for=\"username\" class=\"form-label\">{$lang->member[\'username\']}</label>\r\n                                    <div class=\"position-relative\">\r\n                                        <i class=\"fas fa-user form-icon\"></i>\r\n                                        <input type=\"text\" class=\"form-control input-with-icon\" name=\"username\" id=\"username\" value=\"{$username}\" placeholder=\"Enter username\" />\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <!-- Поля пароля -->\r\n                                {$passboxes}\r\n                                \r\n                                <!-- Email -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    <label for=\"email\" class=\"form-label\">{$lang->member[\'email\']}</label>\r\n                                    <div class=\"position-relative\">\r\n                                        <i class=\"fas fa-envelope form-icon\"></i>\r\n                                        <input type=\"email\" class=\"form-control input-with-icon\" name=\"email\" id=\"email\" maxlength=\"50\" value=\"{$email}\" placeholder=\"Your email\" />\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <!-- Подтверждение email -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    <label for=\"email2\" class=\"form-label\">{$lang->member[\'confirm_email\']}</label>\r\n                                    <div class=\"position-relative\">\r\n                                        <i class=\"fas fa-envelope-circle-check form-icon\"></i>\r\n                                        <input type=\"email\" class=\"form-control input-with-icon\" name=\"email2\" id=\"email2\" maxlength=\"50\" value=\"{$email2}\" placeholder=\"Confirm email\" />\r\n                                    </div>\r\n                                    <div style=\"display: none;\" id=\"email_status\">&nbsp;</div>\r\n                                </div>\r\n                                \r\n                                <!-- Секретный вопрос -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    {$showsecretquestion}\r\n                                </div>\r\n                                \r\n                                <!-- Код приглашения -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    {$showinvitecode}\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        \r\n                        <!-- Секция настроек аккаунта -->\r\n                        <div class=\"card-section\">\r\n                            <h5 class=\"section-title mb-4\">\r\n                                <i class=\"fas fa-sliders-h me-2\"></i> {$lang->member[\'account_prefs\']}\r\n                            </h5>\r\n                            \r\n                            <div class=\"row\">\r\n                                <!-- Часовой пояс -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    <label for=\"timezone\" class=\"form-label\">{$lang->member[\'time_offset\']}</label>\r\n                                    <div class=\"position-relative\">\r\n                                        <i class=\"fas fa-globe form-icon\"></i>\r\n                                        {$tzselect}\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <!-- Коррекция летнего времени -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    <label for=\"dstcorrection\" class=\"form-label\">{$lang->member[\'dst_correction\']}</label>\r\n                                    <div class=\"position-relative\">\r\n                                        <i class=\"fas fa-clock form-icon\"></i>\r\n                                        <select name=\"dstcorrection\" class=\"form-select input-with-icon\">\r\n                                            <option value=\"2\" {$dst_auto_selected}>{$lang->member[\'dst_correction_auto\']}</option>\r\n                                            <option value=\"1\" {$dst_enabled_selected}>{$lang->member[\'dst_correction_enabled\']}</option>\r\n                                            <option value=\"0\" {$dst_disabled_selected}>{$lang->member[\'dst_correction_disabled\']}</option>\r\n                                        </select>\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <!-- Настройки уведомлений -->\r\n                                <div class=\"col-12 mb-3\">\r\n                                    <label class=\"form-label\">Настройки уведомлений</label>\r\n                                    <div class=\"border rounded p-3\">\r\n                                        <div class=\"form-check form-switch mb-2\">\r\n                                            <input class=\"form-check-input\" type=\"checkbox\" name=\"allownotices\" id=\"allownotices\" value=\"1\" {$allownoticescheck}>\r\n                                            <label class=\"form-check-label\" for=\"allownotices\">\r\n                                                <i class=\"fas fa-bell me-1\"></i> {$lang->member[\'allow_notices\']}\r\n                                            </label>\r\n                                        </div>\r\n                                        <div class=\"form-check form-switch mb-2\">\r\n                                            <input class=\"form-check-input\" type=\"checkbox\" name=\"hideemail\" id=\"hideemail\" value=\"1\" {$hideemailcheck}>\r\n                                            <label class=\"form-check-label\" for=\"hideemail\">\r\n                                                <i class=\"fas fa-eye-slash me-1\"></i> {$lang->member[\'hide_email\']}\r\n                                            </label>\r\n                                        </div>\r\n                                        <div class=\"form-check form-switch mb-2\">\r\n                                            <input class=\"form-check-input\" type=\"checkbox\" name=\"receivepms\" id=\"receivepms\" value=\"1\" {$receivepmscheck}>\r\n                                            <label class=\"form-check-label\" for=\"receivepms\">\r\n                                                <i class=\"fas fa-comments me-1\"></i> {$lang->member[\'receive_pms\']}\r\n                                            </label>\r\n                                        </div>\r\n                                        <div class=\"form-check form-switch mb-2\">\r\n                                            <input class=\"form-check-input\" type=\"checkbox\" name=\"pmnotice\" id=\"pmnotice\" value=\"1\" {$pmnoticecheck}>\r\n                                            <label class=\"form-check-label\" for=\"pmnotice\">\r\n                                                <i class=\"fas fa-desktop me-1\"></i> {$lang->member[\'pm_notice\']}\r\n                                            </label>\r\n                                        </div>\r\n                                        <div class=\"form-check form-switch mb-2\">\r\n                                            <input class=\"form-check-input\" type=\"checkbox\" name=\"pmnotify\" id=\"pmnotify\" value=\"1\" {$pmnotifycheck}>\r\n                                            <label class=\"form-check-label\" for=\"pmnotify\">\r\n                                                <i class=\"fas fa-envelope me-1\"></i> {$lang->member[\'email_notify_newpm\']}\r\n                                            </label>\r\n                                        </div>\r\n                                        <div class=\"form-check form-switch\">\r\n                                            <input class=\"form-check-input\" type=\"checkbox\" name=\"invisible\" id=\"invisible\" value=\"1\" {$invisiblecheck}>\r\n                                            <label class=\"form-check-label\" for=\"invisible\">\r\n                                                <i class=\"fas fa-user-secret me-1\"></i> {$lang->member[\'invisible_mode\']}\r\n                                            </label>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <!-- Метод подписки -->\r\n                                <div class=\"col-md-6 mb-3\">\r\n                                    <label for=\"subscriptionmethod\" class=\"form-label\">{$lang->member[\'subscription_method\']}</label>\r\n                                    <div class=\"position-relative\">\r\n                                        <i class=\"fas fa-rss form-icon\"></i>\r\n                                        <select name=\"subscriptionmethod\" id=\"subscriptionmethod\" class=\"form-select input-with-icon\">\r\n                                            <option value=\"0\" {$no_auto_subscribe_selected}>{$lang->member[\'no_auto_subscribe\']}</option>\r\n                                            <option value=\"1\" {$no_subscribe_selected}>{$lang->member[\'no_subscribe\']}</option>\r\n                                            <option value=\"2\" {$instant_email_subscribe_selected}>{$lang->member[\'instant_email_subscribe\']}</option>\r\n                                            <option value=\"3\" {$instant_pm_subscribe_selected}>{$lang->member[\'instant_pm_subscribe\']}</option>\r\n                                        </select>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        \r\n                        <!-- Дополнительные поля -->\r\n                        {$hiddencaptcha}\r\n                        {$requiredfields}\r\n                        {$customfields}\r\n                        {$referrer}\r\n                        {$regimage}\r\n                        {$boardlanguage}\r\n                        {$questionbox}\r\n                        \r\n                        <!-- Кнопка отправки -->\r\n                        <div class=\"d-grid gap-2 mt-4\">\r\n                            <input type=\"hidden\" name=\"regtime\" value=\"{$time}\" />\r\n                            <input type=\"hidden\" name=\"step\" value=\"registration\" />\r\n                            <input type=\"hidden\" name=\"action\" value=\"do_register\" />\r\n                            <button type=\"submit\" class=\"btn btn-primary btn-lg\" name=\"regsubmit\" value=\"{$lang->member[\'submit_registration\']}\">\r\n                                <i class=\"fas fa-user-plus me-2\"></i> {$lang->member[\'submit_registration\']}\r\n                            </button>\r\n                        </div>\r\n                    </form>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n{$validator_javascript}\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/regvalidator.js?ver=1823\"></script>\r\n    \r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1170','member_register_additionalfields','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->member[\'additional_info\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->member[\'additional_info\']}\r\n</div>\r\n<div class=\"col\">\r\n{$customfields}\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1171','member_register_agreement','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->member[\'agreement\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<div class=\"container-md\">\r\n<form action=\"member.php\" method=\"post\">\r\n<div class=\"card\">\r\n<div class=\"card-body text-forum\">\r\n\r\n{$coppa_agreement}\r\n\r\n  <p>{$lang->member[\'agreement_1\']}<br /><br />{$lang->member[\'agreement_2\']}<br /><br />{$lang->member[\'agreement_3\']}<br /><br />{$lang->member[\'agreement_4\']}<br /><br /><span style=\"font-weight: 600;\">{$lang->member[\'agreement_5\']}</span></p>\r\n\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n<input type=\"hidden\" name=\"step\" value=\"agreement\" />\r\n<input type=\"hidden\" name=\"action\" value=\"register\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"agree\" value=\"{$lang->member[\'i_agree\']}\"><i class=\"fa-solid fa-check\"></i> &nbsp;{$lang->member[\'i_agree\']}</button>\r\n	</div></div></div>\r\n</form>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1172','member_register_coppa','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->member[\'coppa_compliance\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"member.php\" method=\"post\">	\r\n<div class=\"container-md\">\r\n<div class=\"card mb\">\r\n	<div class=\"card-body\">\r\n		<span class=\"text-desc\">{$coppa_desc}</span>\r\n				<div class=\"row g-1 mt-3\">\r\n					<div class=\"col-auto\">\r\n						<span class=\"small text-desc\">{$lang->day}</span>\r\n<select name=\"bday1\" id=\"day\" class=\"form-select form-select-sm border pe-5\">\r\n<option value=\"\">&nbsp;</option>\r\n								{$bdaysel}\r\n</select>\r\n					</div>\r\n					<div class=\"col-auto\">\r\n						<span class=\"small text-desc\">{$lang->month}</span>\r\n<select name=\"bday2\" id=\"month\" class=\"form-select form-select-sm border pe-5\">\r\n<option value=\"\">&nbsp;</option>\r\n								<option value=\"1\" {$bdaymonthsel[\'1\']}>{$lang->member[\'month_1\']}</option>\r\n								<option value=\"2\" {$bdaymonthsel[\'2\']}>{$lang->member[\'month_2\']}</option>\r\n								<option value=\"3\" {$bdaymonthsel[\'3\']}>{$lang->member[\'month_3\']}</option>\r\n								<option value=\"4\" {$bdaymonthsel[\'4\']}>{$lang->member[\'month_4\']}</option>\r\n								<option value=\"5\" {$bdaymonthsel[\'5\']}>{$lang->member[\'month_5\']}</option>\r\n								<option value=\"6\" {$bdaymonthsel[\'6\']}>{$lang->member[\'month_6\']}</option>\r\n								<option value=\"7\" {$bdaymonthsel[\'7\']}>{$lang->member[\'month_7\']}</option>\r\n								<option value=\"8\" {$bdaymonthsel[\'8\']}>{$lang->member[\'month_8\']}</option>\r\n								<option value=\"9\" {$bdaymonthsel[\'9\']}>{$lang->member[\'month_9\']}</option>\r\n								<option value=\"10\" {$bdaymonthsel[\'10\']}>{$lang->member[\'month_10\']}</option>\r\n								<option value=\"11\" {$bdaymonthsel[\'11\']}>{$lang->member[\'month_11\']}</option>\r\n								<option value=\"12\" {$bdaymonthsel[\'12\']}>{$lang->member[\'month_12\']}</option>\r\n							</select>\r\n					</div>\r\n					<div class=\"col-auto\">\r\n						<span class=\"small text-desc\">{$lang->year}</span>\r\n						<input type=\"text\" class=\"form-control form-control-sm border w-auto\" size=\"5\" maxlength=\"4\" name=\"bday3\" id=\"year\" value=\"{$birthday_year}\" />\r\n					</div>\r\n				</div>\r\n		\r\n		<div class=\"text-desc mt-3\">{$lang->member[\'hide_dob\']}</div>\r\n	</div>\r\n	\r\n	<div class=\"card-footer text-center\">\r\n		<input type=\"hidden\" name=\"action\" value=\"register\" />\r\n<input type=\"submit\" class=\"btn btn-primary\" name=\"agree\" value=\"{$lang->member[\'continue_registration\']}\" />\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1173','member_register_customfield','<label>{$profilefield[\'name\']}</label><br />\r\n<span class=\"text-desc small\">{$profilefield[\'description\']}</span>\r\n<br />\r\n{$code}','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1174','member_register_hiddencaptcha','<div style=\"display: none;\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->required_info}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->required_info}\r\n</div>\r\n<div class=\"col\" id=\"{$captcha_field}_status\">\r\n	<label>{$lang->leave_this_field_empty}</label><br />\r\n	<input type=\"text\" class=\"form-control form-control-sm border\" name=\"{$captcha_field}\" id=\"{$captcha_field}\" maxlength=\"50\" value=\"\" />\r\n</div>\r\n</div>	\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1175','member_register_language','<div class=\"mt-4 mb-4\">\r\n	<label>{$lang->lang_select_desc}</label>\r\n<select name=\"language\" id=\"language\" class=\"form-select border form-select-sm\">\r\n<option value=\"\">{$lang->lang_select_default}</option>\r\n<option value=\"\">-----------</option>\r\n{$langoptions}\r\n</select>\r\n</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1176','member_register_password','<div class=\"py-3 border-bottom\">\r\n	<div class=\"row g-3\">\r\n		<div class=\"col-lg-6\">\r\n<label for=\"password\">{$lang->member[\'password\']}</label>\r\n		<input type=\"password\" class=\"form-control form-control-sm border\" name=\"password\" id=\"password\" />\r\n		</div>\r\n		<div class=\"col-lg-6\">\r\n		<label for=\"password2\">{$lang->member[\'confirm_password\']}</label>\r\n		<input type=\"password\" class=\"form-control form-control-sm border\" name=\"password2\" id=\"password2\" style=\"width: 100%\" />			\r\n		</div>\r\n		<div class=\"col\" style=\"display: none\" id=\"password_status\">&nbsp;</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1179','member_register_referrer','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->member[\'referrer\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->member[\'referrer\']}\r\n</div>\r\n<div class=\"col\">\r\n{$lang->member[\'referrer_desc\']}\r\n\r\n<input type=\"text\" class=\"form-control border form-control-sm border\" name=\"referrername\" id=\"referrer\" value=\"{$referrername}\" style=\"width: 100%;\" />\r\n\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/scripts/select2/select2-2.css?ver=1807\">\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/select2/select2.min.js?ver=1806\"></script>\r\n<script type=\"text/javascript\">\r\n<!--\r\n\r\n	MyBB.select2();\r\n	$(\"#referrer\").select2({\r\n		placeholder: \"{$lang->search_user}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		},\r\n	});\r\n\r\n// -->\r\n</script>\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1180','member_register_regimage','<script type=\"text/javascript\">\r\n<!--\r\n	lang.captcha_fetch_failure = \"{$lang->captcha_fetch_failure}\";\r\n// -->\r\n</script>\r\n<script type=\"text/javascript\" src=\"{$mybb->asset_url}/jscripts/captcha.js?ver=1821\"></script>\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->image_verification}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->image_verification}\r\n</div>\r\n<div class=\"col\">\r\n{$lang->verification_note}\r\n	<br />\r\n<img src=\"captcha.php?action=regimage&amp;imagehash={$imagehash}\" alt=\"{$lang->image_verification}\" title=\"{$lang->image_verification}\" id=\"captcha_img\" /><br />\r\n<script type=\"text/javascript\">\r\n<!--\r\n	if(use_xmlhttprequest == \"1\")\r\n	{\r\n		document.write(\'<input type=\"button\" class=\"btn btn-primary float-end mb-1\" tabindex=\"10000\" name=\"refresh\" value=\"{$lang->refresh}\" onclick=\"return captcha.refresh();\" \\/>\');\r\n	}\r\n// -->\r\n</script>	\r\n\r\n	<span class=\"text-desc small\">{$lang->verification_subnote}</span>\r\n<input type=\"text\" class=\"form-control border form-control-sm mt-1\" name=\"imagestring\" value=\"\" id=\"imagestring\" /><input type=\"hidden\" name=\"imagehash\" value=\"{$imagehash}\" id=\"imagehash\" />\r\n	<div class=\"col\" id=\"imagestring_status\"  style=\"display: none;\" >&nbsp;\r\n			</div>\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1181','member_register_regimage_hcaptcha','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->human_verification}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->human_verification}\r\n</div>\r\n<div class=\"col\">\r\n{$lang->verification_note_hcaptcha}<br />\r\n<script type=\"text/javascript\" src=\"{$server}\"></script><div class=\"h-captcha\" data-sitekey=\"{$public_key}\" data-theme=\"{$captcha_theme}\" data-size=\"{$captcha_size}\"></div>	\r\n</div>\r\n</div>','2','1837','','1720609281');
