INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1216','modcp_banning','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->modcp[\'ban_banned\']}</title>\r\n\r\n</head>\r\n<body>\r\n	\r\n		<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n				\r\n				<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->modcp[\'ban_banned\']} <span class=\"float-end\"><a href=\"modcp.php?action=banuser\">{$lang->modcp[\'ban_user\']}</a></span>\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">\r\n		<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				<div class=\"row pb-2 border-2 fw-bold\">\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'username\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'reason\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'ban_length\']}\r\n			</div>\r\n				<div class=\"col\">\r\n				{$lang->modcp[\'ban_bannedby\']}\r\n			</div>	\r\n			</div></div>\r\n		\r\n{$bannedusers}\r\n	</div>\r\n	</div>\r\n						\r\n\r\n{$multipage}\r\n			</div></div></div>\r\n	\r\n</body>\r\n</html>','2','1837','','1720609281');
