INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1221','modcp_banuser','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->modcp[\'ban_user\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n		<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$errors}\r\n				<form action=\"modcp.php\" method=\"post\">\r\n					<input type=\"hidden\" name=\"action\" value=\"do_banuser\" />\r\n					<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n					<input type=\"hidden\" name=\"uid\" value=\"{$uid}\" />\r\n						<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->modcp[\'ban_user\']} <span class=\"float-end\">{$lift_link}</span>\r\n	</div>\r\n	<div class=\"card-body\">\r\n				\r\n								\r\n							{$banuser_username}\r\n	<div class=\"pb-4 mb-3 border-bottom\">\r\n		<label for=\"banreason\">{$lang->modcp[\'ban_reason\']}</label>\r\n		<textarea name=\"banreason\" class=\"form-control border form-control-sm\" cols=\"60\" rows=\"4\" maxlength=\"255\">{$banreason}</textarea>\r\n		</div>\r\n							\r\n							{$bangroups}\r\n							\r\n		<label for=\"liftafter\">{$lang->modcp[\'ban_liftafter\']}</label>\r\n							<select name=\"liftafter\" class=\"form-select border form-select-sm w-auto pe-5\">{$liftlist}</select>\r\n							</div>\r\n					<div class=\"card-footer text-center\">\r\n						<button type=\"submit\" class=\"btn btn-primary\" name=\"updateban\" value=\"{$lang->modcp[\'ban\']}\"><i class=\"fa-solid fa-ban\"></i> &nbsp;{$lang->modcp[\'ban\']}</button>\r\n					</div>\r\n				</form>\r\n					</div>\r\n	</div></div></div>\r\n	{$footer}\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/scripts/select2/select2-2.css?ver=1807\">\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/select2/select2.min.js?ver=1806\"></script>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n\r\n	MyBB.select2();\r\n	$(\"#username\").select2({\r\n		placeholder: \"{$lang->modcp[\'search_user\']}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		},\r\n	});\r\n\r\n// -->\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
