INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1230','modcp_finduser','<html>\r\n<head>\r\n	<title>{$SITENAME} - {$lang->modcp[\'find_users\']}</title>\r\n\r\n</head>\r\n<body>\r\n	\r\n		<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n\r\n\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->modcp[\'users\']}\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">\r\n		\r\n		<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n		<div class=\"row pb-2 fw-bold\">\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'username\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'usergroup\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'regdate\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'lastvisit\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'postnum\']}\r\n			</div>\r\n		</div>\r\n		</div>\r\n{$users}\r\n	</div>\r\n				</div>\r\n				\r\n				\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->modcp[\'find_users\']}\r\n	</div>\r\n	<div class=\"card-body pt-0\">					\r\n	<form action=\"modcp.php?action=finduser\" method=\"post\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->modcp[\'username_contains\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->modcp[\'username_contains\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" name=\"username\" id=\"username\" value=\"{$username}\" class=\"form-control border form-control-sm\" />\r\n</div>\r\n</div>					\r\n			\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->modcp[\'sort_by\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->modcp[\'sort_by\']}\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"pb-3 mb-3 border-bottom\">\r\n	<select name=\"sortby\" class=\"form-select border form-select-sm w-auto pe-5\">\r\n									<option value=\"username\"{$sortbysel[\'username\']}>{$lang->modcp[\'username\']}</option>\r\n									<option value=\"added\"{$sortbysel[\'added\']}>{$lang->modcp[\'regdate\']}</option>\r\n									<option value=\"lastvisit\"{$sortbysel[\'lastvisit\']}>{$lang->modcp[\'lastvisit\']}</option>\r\n									<option value=\"postnum\"{$sortbysel[\'postnum\']}>{$lang->modcp[\'postnum\']}</option>\r\n								</select>\r\n	</div>\r\n	\r\n<select name=\"order\" class=\"form-select border form-select-sm pe-5 w-auto\">\r\n									<option value=\"asc\"{$ordersel[\'asc\']}>{$lang->modcp[\'asc\']}</option>\r\n									<option value=\"desc\"{$ordersel[\'desc\']}>{$lang->modcp[\'desc\']}</option>\r\n								</select>	\r\n	\r\n</div>\r\n</div>	\r\n		\r\n		</div>\r\n		\r\n		{$multipage}			\r\n							\r\n					<div class=\"card-footer text-center\">\r\n						<button type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->modcp[\'find_users\']}\"><i class=\"fa-solid fa-magnifying-glass\"></i> &nbsp;{$lang->modcp[\'find_users\']}</button>\r\n					</div>\r\n				</form>\r\n				</div>\r\n	\r\n</div></div>\r\n</div>\r\n\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/scripts/select2/select2-2.css?ver=1807\" />\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/select2/select2.min.js?ver=1806\"></script>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n\r\n	MyBB.select2();\r\n	$(\"#username\").select2({\r\n		placeholder: \"{$lang->modcp[\'find_users\']}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		}\r\n	});\r\n\r\n// -->\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
