INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1232','modcp_finduser_user','<div class=\"row py-2 border-top\">\r\n	<div class=\"col-lg align-self-center\">\r\n		<a href=\"modcp.php?action=editprofile&amp;id={$user[\'id\']}\">{$user[\'username\']}</a>\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		{$usergroup}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		{$regdate}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		{$lastdate}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		{$user[\'postnum\']}\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1233','modcp_ipsearch','<html>\r\n<head>\r\n	<title>{$mybb->settings[\'bbname\']} - {$lang->ipsearch}</title>\r\n	{$headerinclude}\r\n</head>\r\n<body>\r\n	{$header}\r\n		<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n								{$ipsearch_results}\r\n				<form action=\"modcp.php?action=ipsearch\" method=\"post\">\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->ipaddress_search}\r\n	</div>\r\n	<div class=\"card-body\">		\r\n		\r\n		<label for=\"ipaddress\">{$lang->ip_address}</label>\r\n	   <input type=\"text\" class=\"form-control border form-control-sm mb-1\" name=\"ipaddress\" value=\"{$ipaddressvalue}\" size=\"30\" />\r\n						\r\n	\r\n	<div class=\"form-check form-check-inline\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"search_users\" value=\"1\" {$usersearchselect} />\r\n  <label class=\"form-check-label\" for=\"inlineCheckbox1\">{$lang->search_users}</label>\r\n</div>\r\n<div class=\"form-check form-check-inline\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"search_posts\" value=\"1\" {$postsearchselect} />\r\n  <label class=\"form-check-label\" for=\"inlineCheckbox2\">{$lang->search_posts}</label>\r\n</div>\r\n	</div>			\r\n					<div class=\"card-footer text-center\">\r\n						<button type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->find}\"><i class=\"fa-solid fa-magnifying-glass\"></i> &nbsp;{$lang->find}</button>\r\n					</div>\r\n				</form>\r\n		</div>\r\n	</div></div>\r\n</div></div>\r\n\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
