INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1255','modcp_modqueue_empty','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->modcp[\'mod_queue\']}</title>\r\n\r\n</head>\r\n<body>\r\n	\r\n<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n	\r\n	\r\n	<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->modcp[\'mod_queue\']}\r\n	</div>\r\n	<div class=\"card-body\">	\r\n					\r\n	{$lang->modcp[\'mod_queue_empty\']}\r\n	</div>\r\n				</div></div>\r\n	</div></div>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1256','modcp_modqueue_masscontrols','<div class=\"py-2\">\r\n    <a href=\"#\" class=\"mass_ignore\">\r\n        <i class=\"fas fa-eye-slash me-1\" aria-hidden=\"true\"></i> Mark all ignored\r\n    </a>&nbsp;&nbsp;\r\n    <a href=\"#\" class=\"mass_delete\">\r\n        <i class=\"fas fa-trash-alt me-1\" aria-hidden=\"true\"></i> Mark all delete\r\n    </a>&nbsp;&nbsp;\r\n    <a href=\"#\" class=\"mass_approve\">\r\n        <i class=\"fas fa-check me-1\" aria-hidden=\"true\"></i> Mark all approve\r\n    </a>\r\n</div>\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', () => {\r\n    // Отметить все как игнорируемые\r\n    document.querySelectorAll(\'.mass_ignore\').forEach(link => {\r\n        link.addEventListener(\'click\', (e) => {\r\n            e.preventDefault();\r\n            document.querySelectorAll(\'input.radio_ignore\').forEach(cb => {\r\n                cb.checked = true;\r\n            });\r\n        });\r\n    });\r\n\r\n    // Отметить все на удаление\r\n    document.querySelectorAll(\'.mass_delete\').forEach(link => {\r\n        link.addEventListener(\'click\', (e) => {\r\n            e.preventDefault();\r\n            document.querySelectorAll(\'input.radio_delete\').forEach(cb => {\r\n                cb.checked = true;\r\n            });\r\n        });\r\n    });\r\n\r\n    // Отметить все как одобренные\r\n    document.querySelectorAll(\'.mass_approve\').forEach(link => {\r\n        link.addEventListener(\'click\', (e) => {\r\n            e.preventDefault();\r\n            document.querySelectorAll(\'input.radio_approve\').forEach(cb => {\r\n                cb.checked = true;\r\n            });\r\n        });\r\n    });\r\n});\r\n</script>','2','1837','','1720609281');
