INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1279','modcp_reports','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->report_center}</title>\r\n{$headerinclude}\r\n<script type=\"text/javascript\" src=\"{$mybb->asset_url}/jscripts/inline_reports.js?ver=1821\"></script>\r\n</head>\r\n<body>\r\n{$header}\r\n	\r\n	\r\n\r\n	<div class=\"container-md\">\r\n			<form action=\"modcp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"page\" value=\"{$page}\" />\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n				\r\n		\r\n				\r\n				<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->report_center} <span class=\"float-end\"><a href=\"modcp.php?action=allreports\">{$lang->view_all_reports}</a></span>\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">\r\n		\r\n	\r\n		\r\n		<div class=\"row pb-2 fw-bold\">\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_info}\r\n			</div>\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_type}\r\n			</div>\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_count}\r\n			</div>\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_lastpost}\r\n			</div>\r\n			<div class=\"col-auto\">\r\n				<input type=\"checkbox\" name=\"allbox\" class=\"form-check-input\" onclick=\"inlineReports.checkAll(this);\" />\r\n			</div>\r\n		</div>\r\n\r\n		{$reports}\r\n		\r\n	\r\n		\r\n					</div>\r\n					<div class=\"card-footer text-center\">\r\n	\r\n					<input type=\"hidden\" name=\"action\" value=\"do_reports\" />\r\n						<input type=\"submit\" id=\"inline_read\" class=\"button btn btn-primary btn-sm\" name=\"reportsubmit\" value=\"{$lang->mark_read} ({$inlinecount})\" />\r\n							\r\n				</div>\r\n	</div>\r\n\r\n\r\n		</div>\r\n	\r\n	{$reportspages}\r\n	</div></div>\r\n\r\n</form>\r\n{$footer}\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var mark_read_text = \"{$lang->mark_read}\";\r\n	var all_text = \"{$report_count}\";\r\n// -->\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
