INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1284','modcp_reports_report','<div class=\"row py-2 border-top inline_row\">\r\n	<div class=\"col-lg align-self-center\">\r\n		<span class=\"d-inline-block d-sm-inline-block d-md-inline-block d-lg-none d-xl-none d-xxl-none fw-bold\">{$lang->report_info}:&nbsp;</span>{$report_data[\'content\']}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		<span class=\"d-inline-block d-sm-inline-block d-md-inline-block d-lg-none d-xl-none d-xxl-none fw-bold\">{$lang->report_type}:&nbsp;</span>{$report_data[\'comment\']}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		<span class=\"d-inline-block d-sm-inline-block d-md-inline-block d-lg-none d-xl-none d-xxl-none fw-bold\">{$lang->report_count}:&nbsp;</span>{$report_data[\'reports\']}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		{$report_data[\'lastreporter\']} <span class=\"d-inline-block d-sm-inline-block d-md-inline-block d-lg-none d-xl-none d-xxl-none fw-bold\">&nbsp;<input type=\"checkbox\" class=\"form-check-input\" name=\"reports[]\" id=\"reports_{$report[\'rid\']}\" value=\"{$report[\'rid\']}\"{$inlinecheck} /></span>\r\n	</div>\r\n	<div class=\"col-auto align-self-center d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n		<input type=\"checkbox\" class=\"form-check-input\" name=\"reports[]\" id=\"reports_{$report[\'rid\']}\" value=\"{$report[\'rid\']}\"{$inlinecheck} />\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1285','modcp_warninglogs','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->warning_logs}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n	{$header}\r\n	<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n\r\n	\r\n	<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->warning_logs}\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">\r\n<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n	<div class=\"row pb-2 fw-bold\">\r\n    <div class=\"col align-self-center\">{$lang->warned_user}</div>\r\n    <div class=\"col align-self-center\">{$lang->warning}</div>\r\n    <div class=\"col align-self-center\">{$lang->date_issued}</div>\r\n    <div class=\"col align-self-center\">{$lang->expires}</div>\r\n    <div class=\"col align-self-center\">{$lang->issued_by}</div>\r\n    <div class=\"col align-self-center\">{$lang->details}</div>\r\n</div>\r\n	</div>\r\n				\r\n					{$warning_list}\r\n				\r\n		</div>\r\n	</div>\r\n			\r\n				\r\n					\r\n					<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->filter_warning_logs}\r\n	</div>\r\n	<div class=\"card-body\">	\r\n		<form action=\"modcp.php\" method=\"get\">\r\n			<input type=\"hidden\" name=\"action\" value=\"warninglogs\" />\r\n\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->filter_warned_user}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->filter_warned_user}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" name=\"filter[username]\" id=\"username\" value=\"{$filter_username}\" class=\"form-control border form-control-sm\" />\r\n</div>\r\n</div>\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->filter_issued_by}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->filter_issued_by}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" name=\"filter[mod_username]\" value=\"{$filter_modusername}\" class=\"form-control border form-control-sm\" />\r\n</div>\r\n</div>		\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->filter_reason}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->filter_reason}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" name=\"filter[reason]\" value=\"{$filter_reason}\" class=\"form-control border form-control-sm\" />\r\n</div>\r\n</div>	\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->sort_by}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->sort_by}\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"pb-3 mb-3 border-bottom\">\r\n	<select name=\"filter[sortby]\" class=\"form-select border form-select-sm w-auto pe-5\">\r\n									<option value=\"username\"{$sortbysel[\'username\']}>{$lang->username}</option>\r\n									<option value=\"issuedby\"{$sortbysel[\'issuedby\']}>{$lang->issued_by}</option>\r\n									<option value=\"dateline\"{$sortbysel[\'dateline\']}>{$lang->issued_date}</option>\r\n									<option value=\"expires\"{$sortbysel[\'expires\']}>{$lang->expiry_date}</option>\r\n								</select>\r\n	</div>\r\n	<select name=\"filter[order]\" class=\"form-select border form-select-sm w-auto pe-5\">\r\n									<option value=\"asc\"{$ordersel[\'asc\']}>{$lang->asc}</option>\r\n									<option value=\"desc\"{$ordersel[\'desc\']}>{$lang->desc}</option>\r\n								</select>\r\n	\r\n</div>\r\n</div>		\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->per_page}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->per_page}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" name=\"filter[per_page]\" value=\"{$per_page}\" class=\"form-control border form-control-sm w-25\" />\r\n</div>\r\n</div>				\r\n					\r\n</div>\r\n					\r\n<div class=\"card-footer text-center\">\r\n<button type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->filter_warning_logs}\"><i class=\"fa-solid fa-sort\"></i> &nbsp;{$lang->filter_warning_logs}</button>\r\n					</div>\r\n		</div>\r\n				</form>\r\n	\r\n	</div>\r\n	{$multipage}\r\n</div></div>\r\n</div>\r\n	{$footer}\r\n<link rel=\"stylesheet\" href=\"{$mybb->asset_url}/jscripts/select2/select2-2.css?ver=1807\">\r\n<script type=\"text/javascript\" src=\"{$mybb->asset_url}/jscripts/select2/select2.min.js?ver=1806\"></script>\r\n<script type=\"text/javascript\">\r\n<!--\r\nif(use_xmlhttprequest == \"1\")\r\n{\r\n	MyBB.select2();\r\n	$(\"#username\").select2({\r\n		placeholder: \"{$lang->search_user}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		},\r\n	});\r\n}\r\n// -->\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
