INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1287','modcp_warninglogs_warning','<div class=\"row py-2 border-top\">\r\n    <div class=\"col-lg align-self-center\">{$username_link}</div>\r\n    <div class=\"col-lg align-self-center\">{$title} ({$points})</div>\r\n    <div class=\"col-lg align-self-center\">{$issued_date}</div>\r\n    <div class=\"col-lg align-self-center\"><span class=\"text-danger\">{$expire_date}</span> {$revoked_text}</div>\r\n    <div class=\"col-lg align-self-center\">{$mod_username_link}</div>\r\n    <div class=\"col-lg align-self-center\"><a href=\"warnings.php?action=view&amp;wid={$row[\'wid\']}\">{$lang->view}</a></div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1288','moderation_confirmation','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->confirm_execute_tool}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"{$action}\" />\r\n<input type=\"hidden\" name=\"modtype\" value=\"{$modtype}\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"pid\" value=\"{$pid}\" />\r\n<input type=\"hidden\" name=\"fid\" value=\"{$fid}\" />\r\n<input type=\"hidden\" name=\"pmid\" value=\"{$pmid}\" />\r\n<input type=\"hidden\" name=\"confirm\" value=\"1\" />\r\n<input type=\"hidden\" name=\"inlinetype\" value=\"{$inlinetype}\" />\r\n<input type=\"hidden\" name=\"searchid\" value=\"{$searchid}\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{$url}\" />\r\n	<div class=\"container-md\">\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"legend mb-4\">{$thread[\'subject\']} - {$lang->confirm_execute_tool}</div>\r\n	<div class=\"ps-3 pe-3\">\r\n{$loginbox}\r\n	<div class=\"mt-3 text-muted\">\r\n		{$lang->confirm_execute_tool_desc}</div>\r\n\r\n<div class=\"text-end mt-3\"><input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->confirm_execute_tool}\" /></div>\r\n		</div>\r\n</div>\r\n</div>\r\n</div>\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1830','','1720609281');
