INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1328','multipage_jump_page','<!-- Alternative version with different labels -->\r\n<a class=\"btn btn-outline-primary btn-sm dropdown-toggle d-flex align-items-center gap-1\" \r\n   data-bs-toggle=\"dropdown\" \r\n   data-bs-offset=\"10,5\"\r\n   aria-expanded=\"false\">\r\n    <i class=\"fa-solid fa-file-lines\"></i>\r\n   \r\n    \r\n</a>\r\n\r\n<div class=\"dropdown-menu p-3 border-0 shadow-lg\" style=\"\r\n    background: linear-gradient(135deg, #ffffff 0%, #f8f9ff 100%);\r\n    border-radius: 12px;\r\n    min-width: 260px;\r\n    border: 1px solid rgba(0,0,0,0.1);\r\n\">\r\n    <form action=\"{$jump_url}\" method=\"post\">\r\n        <div class=\"d-flex align-items-center justify-content-between mb-2\">\r\n            <label for=\"page\" class=\"small fw-semibold text-primary mb-0\">\r\n                <i class=\"fa-solid fa-arrow-right-to-bracket me-1\"></i>\r\n                Jump to Page\r\n            </label>\r\n            <span class=\"badge bg-light text-dark small\">of {$pages} total</span>\r\n        </div>\r\n        \r\n        <div class=\"row g-2 align-items-center\">\r\n            <div class=\"col\">\r\n                <div class=\"input-group input-group-sm\">\r\n                    <span class=\"input-group-text bg-light border-end-0\">\r\n                        <i class=\"fa-solid fa-hashtag small\"></i>\r\n                    </span>\r\n                    <input type=\"number\" \r\n                           class=\"form-control form-control-sm border-start-0 focus-ring focus-ring-primary\" \r\n                           name=\"page\" \r\n                           value=\"{$page}\" \r\n                           min=\"1\" \r\n                           max=\"{$pages}\"\r\n                           placeholder=\"Page #\"\r\n                           style=\"border-radius: 0 6px 6px 0;\">\r\n                </div>\r\n            </div>\r\n            <div class=\"col-auto\">\r\n                <button type=\"submit\" class=\"btn btn-sm btn-primary px-3 rounded-pill\">\r\n                    <i class=\"fa-solid fa-arrow-right me-1\"></i>\r\n                    Go\r\n                </button>\r\n            </div>\r\n        </div>\r\n        \r\n        <div class=\"mt-2 text-center\">\r\n            <small class=\"text-muted\">\r\n                <i class=\"fa-solid fa-info-circle me-1\"></i>\r\n                Enter page number 1-{$pages}\r\n            </small>\r\n        </div>\r\n    </form>\r\n</div>','2','1837','','1720609281');
