INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1356','online','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->online[\'users_online\']}</title>\r\n\r\n{$refresh}\r\n</head>\r\n<body>\r\n\r\n	\r\n	<div class=\"container-md\">\r\n		\r\n<div class=\"card bg-nav border-0 mb-2\">\r\n<div class=\"card-body text-center\">\r\n	\r\n	<div class=\"row\">\r\n		<div class=\"col-4 text-lg-start\">\r\n            <a href=\"online.php?sortby=username\"><i class=\"fa-solid fa-user\"></i> &nbsp;{$lang->online[\'on_username\']}</a>\r\n		</div>\r\n		<div class=\"col-4 text-lg-center\">\r\n			<a href=\"online.php?sortby=time\"><i class=\"fa-solid fa-clock\"></i> &nbsp;{$lang->online[\'time\']}</a>\r\n		</div>\r\n		<div class=\"col-4 text-lg-end\">\r\n			</a><a href=\"online.php?sortby=location\"><i class=\"fa-solid fa-location-dot\"></i> &nbsp;{$lang->online[\'location\']}</a>	\r\n		</div></div>\r\n		</div></div>\r\n	\r\n	<div class=\"card border-0\">\r\n		\r\n	\r\n	\r\n	\r\n		<div class=\"row g-2\">\r\n		{$online_rows}\r\n	\r\n	\r\n			\r\n	\r\n		</div>\r\n		<div class=\"card-footer border-top-0 rounded text-center\">\r\n			<div class=\"row g-3\">\r\n				<div class=\"col-lg-6 text-lg-end\">\r\n		<a href=\"online.php?action=today\" class=\"links\"><i class=\"fa-solid fa-globe\"></i> &nbsp;{$lang->online[\'online_today\']}</a>\r\n				</div>\r\n				<div class=\"col-lg-6 text-lg-start\">\r\n					<a href=\"online.php\" class=\"links\"><i class=\"fa-solid fa-rotate-right\"></i> &nbsp;{$lang->online[\'refresh_page\']}</a>\r\n				</div>\r\n			</div>\r\n		</div>\r\n	</div>\r\n		\r\n	</div>\r\n	{$multipage}\r\n	\r\n	\r\n</body>\r\n</html>','2','1837','','1720609281');
