INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1360','online_today','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->online[\'online_today\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n	<div class=\"container-md\">\r\n		\r\n		<div class=\"card border-0 mb-4\">\r\n	\r\n		<div class=\"row g-2\">\r\n		{$todayrows}\r\n		</div>\r\n			\r\n		</div>\r\n		\r\n		{$multipage}\r\n		\r\n\r\n	</div>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1361','online_today_row','<div class=\"col-lg-6 mb-3\">\r\n    <div class=\"card card-user-online h-100\">\r\n        <div class=\"card-body d-flex align-items-center p-3\">\r\n            <div class=\"user-avatar me-3\">\r\n                <img src=\"{$online[\'avatar\']}\" alt=\"{$online[\'username\']}\" class=\"rounded-circle\" width=\"60\" height=\"60\">\r\n            </div>\r\n            <div class=\"user-info flex-grow-1\">\r\n                <h6 class=\"mb-1 fw-semibold\">{$online[\'profilelink\']}{$invisiblemark}</h6>\r\n                <p class=\"text-muted small mb-0\">\r\n                    <i class=\"bi bi-clock me-1\"></i>{$onlinetime}\r\n                </p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1362','polls_editpoll','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->polls[\'edit_poll\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<div class=\"container-md\">\r\n<form action=\"moderation.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	\r\n\r\n	\r\n	<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n		{$lang->polls[\'delete_poll\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		\r\n		<div class=\"row g-2 pb-3 border-bottom\">\r\n			<div class=\"col-lg-auto align-self-center border-end pe-3 me-3\">\r\n		\r\n		<input type=\"checkbox\" class=\"form-check-input\" name=\"delete\" value=\"1\" tabindex=\"9\" /> {$lang->polls[\'delete_q\']}\r\n				\r\n			</div>\r\n			<div class=\"col-lg\">\r\n		<i class=\"fa-solid fa-circle-exclamation text-danger\"></i> {$lang->polls[\'delete_note\']} <br /><span class=\"text-desc\">{$lang->polls[\'delete_note2\']}</span>\r\n			</div>\r\n			<div class=\"col-lg-auto text-end align-self-center\">\r\n		<input type=\"submit\" class=\"btn btn-danger\" name=\"submit\" value=\"{$lang->polls[\'delete_poll\']}\" tabindex=\"10\" />\r\n				<input type=\"hidden\" name=\"action\" value=\"do_deletepoll\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n			</div>\r\n		</div>\r\n		</div></div></form>\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	\r\n						\r\n	<form action=\"polls.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n					\r\n						\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-body\">\r\n       \r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'question\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'question\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"question\" maxlength=\"240\" value=\"{$question}\" />\r\n</div>\r\n</div>\r\n\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'num_options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'num_options\']}\r\n</div>\r\n<div class=\"col\">\r\n{$lang->polls[\'max_options\']} {$maxpolloptions}<br />\r\n<div class=\"row g-1\">\r\n<div class=\"col-auto\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"numoptions\" size=\"10\" style=\"width: 100px\" value=\"{$numoptions}\" />\r\n</div>\r\n<div class=\"col-auto text-end\">\r\n<input type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"updateoptions\" value=\"{$lang->polls[\'update_options\']}\" />\r\n</div>\r\n</div>	\r\n	\r\n</div>\r\n</div>\r\n\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'poll_options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'poll_options\']}\r\n</div>\r\n<div class=\"col\">\r\n<span class=\"text-desc small\">{$lang->polls[\'poll_options_note\']}</span>\r\n{$optionbits}\r\n</div>\r\n</div>		\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'options\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"postoptions[multiple]\" value=\"1\" {$postoptionschecked[\'multiple\']} /> {$lang->polls[\'option_multiple\']}\r\n<div class=\"mt-2\"></div>\r\n<span id=\"maxOptions\" style=\"display: none\"><strong>{$lang->polls[\'option_multiple_maxoptions\']}</strong> <input type=\"text\" style=\"width: 100px\" class=\"form-control border form-control-sm border\" name=\"maxoptions\" value=\"0\" /><br /></span>\r\n<script type=\"text/javascript\">\r\n//<!--\r\n	if($(\"input[name=\'postoptions[multiple]\']\").is(\":checked\")) {\r\n		$(\"#maxOptions\").css(\"display\", \"\");\r\n	}\r\n\r\n 	$(\"input[name=\'postoptions[multiple]\']\").on(\'click\', function() {\r\n 		if($(this).is(\":checked\")) {\r\n 	    	$(\"#maxOptions\").css(\"display\", \"\");\r\n		} else {\r\n 	    	$(\"#maxOptions\").css(\"display\", \"none\");\r\n 	   	}\r\n    });\r\n// -->\r\n</script>\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"postoptions[public]\" value=\"1\" {$postoptionschecked[\'public\']} /> {$lang->polls[\'option_public\']}\r\n<div class=\"mt-2\"></div>\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"postoptions[closed]\" value=\"1\" {$postoptionschecked[\'closed\']} /> {$lang->polls[\'option_closed\']}\r\n</span>\r\n</div>\r\n</div>			\r\n		\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'poll_timeout\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'poll_timeout\']}\r\n</div>\r\n<div class=\"col\">\r\n<span class=\"text-desc small\">{$lang->polls[\'timeout_note\']}</span>\r\n	<br /><br />\r\n<input type=\"text\" class=\"form-control form-control-sm border\" style=\"width: 150px\" name=\"timeout\" value=\"{$timeout}\" /> {$lang->polls[\'days_after\']} {$polldate}\r\n</div>\r\n</div>	\r\n\r\n		</div>	\r\n\r\n	<div class=\"card-footer text-center\">\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->polls[\'update_poll\']}\"><i class=\"fa-solid fa-square-poll-horizontal\"></i> &nbsp;{$lang->polls[\'update_poll\']}</button>\r\n		</div>\r\n		</div>\r\n	</div>\r\n\r\n<input type=\"hidden\" name=\"action\" value=\"do_editpoll\" />\r\n<input type=\"hidden\" name=\"pid\" value=\"{$pid}\" />\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
