INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1364','polls_newpoll','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->polls[\'post_new_poll\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	<div class=\"container-md\">\r\n<form action=\"polls.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-body\">\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'question\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'question\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"question\" maxlength=\"240\" value=\"{$question}\" />\r\n</div>\r\n</div>	\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'num_options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'num_options\']}\r\n</div>\r\n<div class=\"col\">\r\n{$lang->polls[\'max_options\']} {$maxpolloptions}<br />\r\n<div class=\"row g-1\">\r\n<div class=\"col-auto\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"polloptions\" size=\"10\" style=\"width: 100px\" value=\"{$polloptions}\" />\r\n</div>\r\n<div class=\"col-auto text-end\">\r\n<input type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"updateoptions\" value=\"{$lang->polls[\'update_options\']}\" />\r\n</div>\r\n</div>	\r\n	\r\n</div>\r\n</div>		\r\n				\r\n\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'poll_options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'poll_options\']}\r\n</div>\r\n<div class=\"col\">\r\n<span class=\"text-desc small\">{$lang->polls[\'poll_options_note\']}</span>\r\n{$optionbits}\r\n</div>\r\n</div>\r\n					\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'options\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"postoptions[multiple]\" value=\"1\" {$postoptionschecked[\'multiple\']} /> {$lang->polls[\'option_multiple\']}\r\n<div class=\"mt-2\"></div>\r\n<span id=\"maxOptions\" style=\"display: none\"><strong>{$lang->polls[\'option_multiple_maxoptions\']}</strong> <input type=\"text\" style=\"width: 100px\" class=\"form-control border form-control-sm border\" name=\"maxoptions\" value=\"0\" /><br /></span>\r\n<script type=\"text/javascript\">\r\n//<!--\r\n	if($(\"input[name=\'postoptions[multiple]\']\").is(\":checked\")) {\r\n		$(\"#maxOptions\").css(\"display\", \"\");\r\n	}\r\n\r\n 	$(\"input[name=\'postoptions[multiple]\']\").on(\'click\', function() {\r\n 		if($(this).is(\":checked\")) {\r\n 	    	$(\"#maxOptions\").css(\"display\", \"\");\r\n		} else {\r\n 	    	$(\"#maxOptions\").css(\"display\", \"none\");\r\n 	   	}\r\n    });\r\n// -->\r\n</script>\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"postoptions[public]\" value=\"1\" {$postoptionschecked[\'public\']} /> {$lang->polls[\'option_public\']}\r\n</span>\r\n</div>\r\n</div>\r\n									\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->polls[\'poll_timeout\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->polls[\'poll_timeout\']}\r\n</div>\r\n<div class=\"col\">\r\n<span class=\"text-desc small\">{$lang->polls[\'timeout_note\']}</span>\r\n	<br /><br />\r\n<input type=\"text\" class=\"form-control form-control-sm border\" style=\"width: 150px\" name=\"timeout\" value=\"{$timeout}\" /> {$lang->polls[\'days\']}\r\n</div>\r\n</div>	\r\n\r\n		</div>								\r\n					\r\n	<div class=\"card-footer text-center\">\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->polls[\'post_new_poll\']}\"><i class=\"fa-solid fa-square-poll-horizontal\"></i> &nbsp;{$lang->polls[\'post_new_poll\']}</button>\r\n		</div>\r\n		</div>\r\n	</div>\r\n\r\n					\r\n		\r\n<input type=\"hidden\" name=\"action\" value=\"do_newpoll\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n</form>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
