r\n\r\n<div class=\"col align-self-center small text-end\">\r\n{$post[\'button_edit\']}\r\n</div>\r\n\r\n{$modals}\r\n\r\n{$modaldelete}\r\n\r\n<div class=\"col-auto text-end align-self-center\">\r\n<div class=\"hidden-text\"><div class=\"dropdown d-flex justify-content-end align-self-center\"><a class=\"bg-transparent border-0 text-muted\" aria-expanded=\"true\" data-bs-toggle=\"dropdown\" role=\"button\">&nbsp;<i class=\"fa-solid fa-ellipsis-vertical\"></i>&nbsp;</a><div class=\"dropdown-menu border\">{$post[\'button_quote\']}{$post[\'button_quickdelete\']}{$post[\'button_quickrestore\']}{$post[\'button_report\']}{$post[\'button_warn\']}{$post[\'button_purgespammer\']}{$post[\'button_reply_pm\']}{$post[\'button_replyall_pm\']}{$post[\'button_forward_pm\']}{$post[\'button_delete_pm\']}\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- /hidden -->\r\n</div>		\r\n</div>\r\n</div>\r\n</div>\r\n</div>','2','1837','','1720609281');
