</div>	\r\n\r\n<div class=\"col align-self-center small text-end\">\r\n{$post[\'button_edit\']}\r\n</div>\r\n\r\n<div class=\"col-auto text-end align-self-center\">\r\n<div class=\"hidden-text\"><div class=\"dropdown d-flex justify-content-end align-self-center\"><a class=\"bg-transparent border-0 text-muted\" aria-expanded=\"true\" data-bs-toggle=\"dropdown\" role=\"button\">&nbsp;<i class=\"fa-solid fa-ellipsis-vertical\"></i>&nbsp;</a><div class=\"dropdown-menu border\">{$post[\'button_quote\']}{$post[\'button_quickdelete\']}{$post[\'button_quickrestore\']}{$post[\'button_report\']}{$post[\'button_warn\']}{$post[\'button_purgespammer\']}{$post[\'button_reply_pm\']}{$post[\'button_replyall_pm\']}{$post[\'button_forward_pm\']}{$post[\'button_delete_pm\']}\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- /hidden -->\r\n</div>		\r\n</div>\r\n</div>\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1394','postbit_deleted','<div class=\"row g-2\">\r\n	<div class=\"col-1 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n		&nbsp;\r\n	</div>\r\n	<div class=\"col algin-self-center\" style=\"margin-left: 3px;\">\r\n	\r\n\r\n<div class=\"deleted_post_collapsed py-2 border-top border-bottom\" id=\"deleted_post_{$post[\'pid\']}\">\r\n	<div class=\"deleted_post_author\"><strong><h6 class=\"mb-0\">{$post[\'profilelink\']}</h6></strong></div>\r\n	<div class=\"deleted_post_message\">{$deleted_message}\r\n		<div class=\"show_deleted_post float_right float-end\" style=\"vertical-align: top;\" id=\"show_deleted_link_{$post[\'pid\']}\"><a href=\"javascript:void(0)\" onclick=\"Thread.showDeletedPost({$post[\'pid\']}); return false;\" class=\"button small_button\"><span><i class=\"fa-solid fa-eye\"></i> &nbsp;{$lang->postbit_show_ignored_post}</span></a></div>\r\n<script type=\"text/javascript\">\r\n<!--\r\n	$(\'#show_deleted_link_{$post[\'pid\']}\').show();\r\n// -->\r\n</script>\r\n	</div>\r\n	\r\n			\r\n		</div>\r\n		\r\n	</div>\r\n</div>','2','1837','','1720609281');
