INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1439','post_prefixselect_multiple','<div class=\"col-auto align-self-center m-0 p-0 me-2\">\r\n	<select class=\"form-select form-select border mb-3 pe-5\" name=\"threadprefix[]\" multiple=\"multiple\" size=\"5\">\r\n<option value=\"any\"{$any_selected}>{$lang->any_prefix}</option>\r\n<option value=\"0\"{$default_selected}>{$lang->no_prefix}</option>\r\n{$prefixselect_prefix}\r\n</select>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1440','post_prefixselect_single','<div class=\"col-auto align-self-center m-0 p-0 me-2\"><select class=\"form-select form-select border mb-3 pe-5\" name=\"threadprefix\">\r\n<option value=\"0\"{$default_selected}>{$lang->no_prefix}</option>\r\n{$prefixselect_prefix}\r\n</select>\r\n		</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1441','post_savedraftbutton','<button type=\"submit\" class=\"btn-thread ms-2\" name=\"savedraft\" value=\"{$lang->save_draft}\"><i class=\"fa-regular fa-note-sticky\"></i> &nbsp;{$lang->save_draft}</button>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1442','post_subscription_method','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->global[\'thread_subscription_method\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->global[\'thread_subscription_method\']}\r\n</div>\r\n<div class=\"col\">\r\n	<div class=\"text-desc mb-3\">{$lang->global[\'thread_subscription_method_desc\']}</div>\r\n	<label class=\"form-check-label\"><input type=\"radio\" class=\"form-check-input\" name=\"postoptions[subscriptionmethod]\" {$subscribe}value=\"\" /> {$lang->global[\'no_subscribe\']}</label><br />\r\n	<label class=\"form-check-label\"><input type=\"radio\" class=\"form-check-input mt-1\"  name=\"postoptions[subscriptionmethod]\" {$nonesubscribe}value=\"none\" /> {$lang->global[\'no_subscribe_notification\']}</label><br />\r\n	<label class=\"form-check-label\"><input type=\"radio\" class=\"form-check-input mt-1\"  name=\"postoptions[subscriptionmethod]\" {$emailsubscribe}value=\"email\"/> {$lang->global[\'instant_email_subscribe\']}</label><br />\r\n	<label class=\"form-check-label\"><input type=\"radio\" class=\"form-check-input mt-1\"  name=\"postoptions[subscriptionmethod]\" {$pmsubscribe}value=\"pm\" /> {$lang->global[\'instant_pm_subscribe\']}</label>\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1443','previewpost','{$postbit}','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1444','printthread','<html>\r\n<head>\r\n<title>{$thread[\'threadprefix\']} {$thread[\'subject\']} - {$lang->printthread[\'printable_version\']}</title>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset={$charset}\" />\r\n<style type=\"text/css\">\r\nbody { font-family: Verdana, Arial, sans-serif; font-size: 13px; }\r\n.largetext { font-family: Verdana, Arial, sans-serif; font-size: medium; font-weight: bold; }\r\nimg { max-width: 100%; height: auto; }\r\n</style>\r\n</head>\r\n<body>\r\n<table width=\"98%\" align=\"center\">\r\n<tr>\r\n<td valign=\"top\"><a href=\"index.php\"><img src=\"{$theme[\'logo\']}\" alt=\"{$mybb->settings[\'bbname\']}\" title=\"{$SITENAME}\" border=\"0\" /></a></td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<span class=\"largetext\">{$thread[\'displaystyle\']} <a href=\"{$thread[\'threadlink\']}\">{$thread[\'subject\']}</a> - {$lang->printthread[\'printable_version\']}</span><br />\r\n<br />\r\n+- {$SITENAME} (<em>{$BASEURL}</em>)<br />\r\n{$breadcrumb}\r\n+{$tdepth} {$lang->printthread[\'thread\']} {$thread[\'displaystyle\']} {$thread[\'subject\']} (<em>/{$thread[\'threadlink\']}</em>)<br />\r\n<br />\r\n{$multipage}</td>\r\n</tr>\r\n<tr>\r\n<td><br /><hr size=\"1\" />{$postrows}</td>\r\n</tr>\r\n</table>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1445','private','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->private[\'private_messaging\']}</title>\r\n</head>\r\n<body>\r\n\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n				\r\n<div class=\"col\">\r\n\r\n	{$limitwarning} \r\n	<form action=\"private.php\" method=\"post\" name=\"pmForm\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"row g-2 mb-2\">\r\n	<div class=\"col-lg-5 align-self-center\">\r\n\r\n			<div class=\"input-group\">\r\n  <input type=\"text\" name=\"keywords\" value=\"{$lang->private[\'enter_keywords\']}\" onfocus=\"if(this.value == \'{$lang->private[\'enter_keywords\']}\') { this.value = \'\'; }\" onblur=\"if(this.value==\'\') { this.value=\'{$lang->private[\'enter_keywords\']}\'; }\" class=\"form-control form-control-sm border rounded\" size=\"25\" />&nbsp;&nbsp;\r\n				<button class=\"btn btn-primary btn-sm rounded\" type=\"submit\" name=\"quick_search\"><i class=\"fa-solid fa-magnifying-glass\"></i> &nbsp;{$lang->private[\'search_pms\']}</button>\r\n			</div>\r\n		</div>\r\n		<div class=\"col-lg text-lg-end align-self-center\">\r\n			<a href=\"private.php?action=advanced_search\" class=\"links\"><i class=\"fa-solid fa-gear\"></i> &nbsp;{$lang->private[\'advanced_search\']}</a>\r\n		</div>\r\n	</div>\r\n	\r\n<div class=\"card border-0 mb-3\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n		\r\n		<div class=\"row g-2 text-forum\">\r\n			<div class=\"col-1\">\r\n				&nbsp;\r\n			</div>\r\n			<div class=\"col align-self-center\">\r\n				<a href=\"private.php?fid={$fid}&amp;sortby=subject&amp;order=asc\">{$lang->private[\'message_title\']}</a> &mdash; <a href=\"private.php?fid={$fid}&amp;sortby=username&amp;order=asc\">{$sender}</a>\r\n			</div>\r\n			\r\n			<div class=\"col-3 align-self-center\">\r\n    <div class=\"d-flex align-items-center justify-content-end gap-2\">\r\n        <!-- Дата -->\r\n        <a href=\"private.php?fid={$fid}&amp;sortby=dateline&amp;order=desc\" \r\n           class=\"d-none d-sm-none d-md-none d-lg-inline-block d-xl-inline-block d-xxl-inline-block text-decoration-none\">\r\n            {$lang->private[\'date_sent\']}\r\n        </a>\r\n        \r\n        <!-- Свитч для выбора всех -->\r\n        <div class=\"form-check form-switch ms-auto\">\r\n            <input class=\"form-check-input select-all-switch\" \r\n                   type=\"checkbox\" \r\n                   role=\"switch\"\r\n                   id=\"selectAllSwitch\"\r\n                   title=\"{$lang->private[\'check_all\']}\">\r\n            <label class=\"form-check-label small ms-2\" for=\"selectAllSwitch\">\r\n                {$lang->private[\'check_all\']}\r\n            </label>\r\n        </div>\r\n    </div>\r\n</div>\r\n	</div>\r\n	\r\n	</div>\r\n	</div>\r\n	\r\n\r\n{$messagelist}\r\n{$multipage} \r\n	<div class=\"card border-0 mt-3\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n		\r\n		<div class=\"row g-1\">\r\n			<div class=\"col\">\r\n				&nbsp;\r\n			</div>\r\n						<div class=\"col-auto\">\r\n				<button type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"moveto\" value=\"{$lang->private[\'move_to\']}\">{$lang->private[\'move_to\']} &nbsp;<i class=\"fa-solid fa-arrow-right\"></i></button>  \r\n			</div>\r\n			<div class=\"col-auto\">\r\n	{$folderoplist} \r\n			</div>\r\n			<div class=\"col-auto\">\r\n				&nbsp;{$lang->private[\'or\']}&nbsp; <button type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"delete\" value=\"{$lang->private[\'delete\']}\"><i class=\"fa-solid fa-xmark\"></i> &nbsp;{$lang->private[\'delete\']}</button>\r\n			</div>\r\n			<div class=\"col\">\r\n				&nbsp;\r\n			</div>\r\n	</div>\r\n		</div>\r\n	</div>\r\n	\r\n<div class=\"row g-3 mt-2 text-start\">\r\n	<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n		&nbsp;\r\n	</div>\r\n	<div class=\"col-lg-auto\">\r\n<a  href=\"private.php?action=folders\" class=\"links\"><i class=\"fa-solid fa-folder-open\"></i> &nbsp;{$lang->private[\'manage_folders\']}</a>\r\n	</div>\r\n   {$emptyexportlink}\r\n	</div>\r\n	\r\n	\r\n	{$pmspacebar}\r\n\r\n			\r\n<input type=\"hidden\" name=\"action\" value=\"do_stuff\" />\r\n</form>\r\n	</div>\r\n	</div>\r\n	\r\n	</div>\r\n	\r\n</div>\r\n</div>\r\n\r\n\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1446','private_advanced_search','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->private[\'advanced_private_message_search\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"private.php\" method=\"post\" name=\"pmForm\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_search\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n				\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->private[\'keywords\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->private[\'keywords\']}\r\n</div>\r\n<div class=\"col\">\r\n<label for=\"keywords\">{$lang->private[\'keywords\']}</label>\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"keywords\" id=\"keywords\" maxlength=\"250\" />\r\n	<div class=\"form-check form-check-inline mt-1\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"subject\" checked=\"checked\" value=\"1\" />\r\n  <label class=\"form-check-label\" for=\"inlineCheckbox1\">{$lang->private[\'search_in_subject\']}</label>\r\n</div>\r\n	<div class=\"form-check form-check-inline mt-1\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"message\" checked=\"checked\" value=\"1\" />\r\n  <label class=\"form-check-label\" for=\"inlineCheckbox1\">{$lang->private[\'search_in_message\']}</label>\r\n</div>	\r\n</div>\r\n</div>\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->sender}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->private[\'sender\']}\r\n</div>\r\n<div class=\"col\">\r\n	<label for=\"keywords\">{$lang->private[\'sender\']}</label>\r\n			<input type=\"text\" class=\"form-control form-control-sm border border\" name=\"sender\" id=\"sender\" maxlength=\"250\" />	\r\n</div>\r\n</div>	\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->private[\'message_status\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->private[\'message_status\']}\r\n</div>\r\n<div class=\"col\">\r\n <input type=\"checkbox\" name=\"status[new]\" class=\"form-check-input\" checked=\"checked\" value=\"1\" /> {$lang->private[\'message_status_new\']}\r\n	<br />\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"status[replied]\" checked=\"checked\" value=\"1\" /> {$lang->private[\'message_status_replied_to\']}	\r\n	<br />\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"status[forwarded]\" checked=\"checked\" value=\"1\" /> {$lang->private[\'message_status_forwarded\']}\r\n	<br />\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"status[read]\" checked=\"checked\" value=\"1\" /> {$lang->private[\'message_status_read\']}\r\n	\r\n</div>\r\n</div>	\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->private[\'folder\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->private[\'folder\']}\r\n</div>\r\n<div class=\"col\">\r\n{$foldersearch}\r\n</div>\r\n</div>		\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->private[\'search_options\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->private[\'search_options\']}\r\n</div>\r\n<div class=\"col\">\r\n	<div class=\"pb-3 mb-3 border-bottom\">\r\n<label>{$lang->private[\'sort_by\']}</label>\r\n		<select name=\"sort\" id=\"sort\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n				<option value=\"subject\">{$lang->private[\'sort_by_subject\']}</option>\r\n				<option value=\"sender\">{$lang->private[\'sort_by_sender\']}</option>\r\n				<option value=\"dateline\" selected=\"selected\">{$lang->private[\'sort_by_date\']}</option>\r\n			</select>\r\n	</div>\r\n		<div class=\"radio-toolbar mt-2\">\r\n  <input type=\"radio\" name=\"sortordr\" id=\"order_asc\" value=\"asc\" />\r\n  <label for=\"order_asc\">{$lang->private[\'ascending_order\']}</label>\r\n\r\n  <input type=\"radio\" name=\"sortordr\" checked=\"checked\" id=\"order_desc\" value=\"desc\" />\r\n  <label for=\"order_desc\">{$lang->private[\'descending_order\']}</label>\r\n</div>\r\n	\r\n</div>\r\n</div>		\r\n\r\n	</div>\r\n				\r\n<div class=\"card-footer text-center\">\r\n<button type=\"submit\" value=\"{$lang->private[\'search_private_messages\']}\" class=\"btn btn-primary\"><i class=\"fa-solid fa-magnifying-glass\"></i> &nbsp;{$lang->private[\'search_private_messages\']}</button></div>\r\n</div>\r\n</form>\r\n</div></div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/scripts/select2/select2-2.css?ver=1807\" />\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/select2/select2.min.js?ver=1806\"></script>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n\r\n	MyBB.select2();\r\n	$(\"#sender\").select2({\r\n		placeholder: \"{Search for a user}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		}\r\n	});\r\n\r\n// -->\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1447','private_advanced_search_folders','<select name=\"folder[]\" id=\"folder\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n<option selected=\"selected\">{$lang->private[\'all_folders\']}</option>\r\n{$foldersearch_folder}\r\n</select>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1448','private_archive','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->private[\'archive_messages\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"private.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n				\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	<div class=\"mb-3 pb-3 border-bottom\">\r\n{$lang->private[\'archive_note\']}\r\n	</div>\r\n\r\n	\r\n<div class=\"mb-3 pb-3 border-bottom\">\r\n		<label>{$lang->folders}</label>\r\n         {$folderlist}\r\n	</div>\r\n	\r\n<div class=\"mb-3 pb-3 border-bottom\">\r\n	<div class=\"row g-1\">\r\n		<div class=\"col-auto\">\r\n			\r\n		<label>{$lang->private[\'date_limit\']}</label>\r\n<select name=\"dayway\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n	<option value=\"older\">{$lang->private[\'date_limit_older\']}</option>\r\n	<option value=\"newer\">{$lang->private[\'date_limit_newer\']}</option>\r\n	<option value=\"disregard\">{$lang->private[\'date_limit_disregard\']}</option>\r\n		</select> \r\n			</div>\r\n		<div class=\"col-auto align-self-center\">\r\n				<label>{$lang->private[\'date_limit_days\']}</label>\r\n			<input type=\"text\" class=\"form-control form-control-sm border\" name=\"daycut\" value=\"30\" size=\"3\" maxlength=\"4\" /> \r\n			</div>\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"mb-3 pb-3 border-bottom\">\r\n		\r\n		<div class=\"row g-2\">\r\n			<div class=\"col-auto\">\r\n	<input type=\"radio\" class=\"form-check-input\" name=\"exportunread\" value=\"1\" />\r\n			</div>\r\n			<div class=\"col\">\r\n			<label for=\"exportunread\">{$lang->private[\'export_unread\']}</label><br />\r\n				<span class=\"text-desc small\">{$lang->private[\'export_unread\']}</span>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"mb-3 pb-3 border-bottom\">\r\n	<div class=\"row g-2\">\r\n			<div class=\"col-auto\">\r\n	<input type=\"radio\" class=\"form-check-input\" name=\"deletepms\" value=\"1\" />\r\n				<input type=\"radio\" class=\"form-check-input d-none\" name=\"deletepms\" value=\"0\" checked=\"checked\" />\r\n			</div>\r\n			<div class=\"col\">\r\n			<label for=\"exportunread\">{$lang->private[\'delete_archived\']}</label><br />\r\n				<span class=\"text-desc small\">{$lang->private[\'delete_archived_note\']}</span>\r\n			</div>\r\n		</div>\r\n	</div>\r\n	\r\n	\r\n			<div class=\"mb-3\">\r\n				<label>{$lang->private[\'export_format\']}</label><br />\r\n			<span class=\"text-desc small\">{$lang->private[\'export_format_note\']}</span>\r\n			<br /><br />\r\n			\r\n			<div class=\"form-check mb-1\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"exporttype\" value=\"html\" checked=\"checked\" />\r\n  <label class=\"form-check-label\" for=\"exampleRadios1\">\r\n    {$lang->private[\'export_html\']}\r\n  </label>\r\n</div>\r\n			\r\n			<div class=\"form-check mb-1\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"exporttype\" value=\"txt\" />\r\n  <label class=\"form-check-label\" for=\"exampleRadios1\">\r\n    {$lang->private[\'export_txt\']}\r\n  </label>\r\n</div>\r\n			\r\n			<div class=\"form-check\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"exporttype\" value=\"csv\" />\r\n  <label class=\"form-check-label\" for=\"exampleRadios1\">\r\n    {$lang->private[\'export_csv\']}\r\n  </label>\r\n</div>\r\n			\r\n		</div>\r\n	</div>\r\n		\r\n<div class=\"card-footer text-center\">\r\n<input type=\"hidden\" name=\"action\" value=\"do_export\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->private[\'archive_messages\']}\"><i class=\"fa-solid fa-file-export\"></i> &nbsp;{$lang->private[\'archive_messages\']}</button>\r\n	</div></div>\r\n\r\n</form>\r\n	</div></div>\r\n</div>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
