INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1496','search_results_posts_inlinecheck','<span class=\"float-end\"><input type=\"checkbox\" class=\"form-check-input\" name=\"inlinemod_{$post[\'pid\']}\" id=\"inlinemod_{$post[\'pid\']}\" value=\"1\" style=\"vertical-align: middle;\" {$inlinecheck}  /></span>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1497','search_results_posts_inlinemoderation','<div class=\"card mt-4 border-0\">\r\n	<div class=\"card-body bg-nav\">\r\n\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/inline_moderation.js?ver=1821\"></script>\r\n<form action=\"moderation.php\" method=\"post\" style=\"margin-top: 0; margin-bottom: 0;\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"0\" />\r\n<input type=\"hidden\" name=\"searchid\" value=\"{$sid}\" />\r\n<input type=\"hidden\" name=\"modtype\" value=\"inlinepost\" />\r\n	<div class=\"row g-1\">\r\n				<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n					&nbsp;\r\n				</div>\r\n				<div class=\"col-auto align-self-center\">\r\n<select name=\"action\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<optgroup label=\"{$lang->search[\'standard_mod_tools\']}\">\r\n	<option value=\"multideleteposts\">{$lang->search[\'inline_delete_posts\']}</option>\r\n	<option value=\"multimergeposts\">{$lang->search[\'inline_merge_posts\']}</option>\r\n	<option value=\"multisplitposts\">{$lang->search[\'inline_split_posts\']}</option>\r\n	<option value=\"multimoveposts\">{$lang->search[\'inline_move_posts\']}</option>\r\n	<option value=\"multiapproveposts\">{$lang->search[\'inline_approve_posts\']}</option>\r\n	<option value=\"multiunapproveposts\">{$lang->search[\'inline_unapprove_posts\']}</option>\r\n</optgroup>\r\n{$customposttools}\r\n</select>\r\n		</div>\r\n		<div class=\"col-auto align-self-center\">\r\n<input type=\"submit\" class=\"btn btn-primary btn-sm\" name=\"go\" value=\"Go ({$inlinecount})\" id=\"inline_go\" />\r\n		</div>\r\n		<div class=\"col-auto align-self-center\">\r\n<input type=\"button\" class=\"btn btn-primary btn-sm\" onclick=\"inlineModeration.clearChecked();\" value=\"{$lang->search[\'clear\']}\" />\r\n		</div>\r\n		<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n					&nbsp;\r\n				</div>\r\n			</div>\r\n<input type=\"hidden\" name=\"url\" value=\"{$return_url}\" />\r\n<input type=\"hidden\" name=\"inlinetype\" value=\"search\" />\r\n</form>\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var go_text = \"Go\";\r\n	var all_text = \"{$postcount}\";\r\n	var inlineType = \"search\";\r\n	var inlineId = \"{$sid}\";\r\n// -->\r\n</script>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1498','search_results_posts_post','	\r\n		<div class=\"card border-bottom border-0 rounded-0\">\r\n	<div class=\"card-body py-0 px-1 inline_row\">\r\n<div class=\"row py-2\">\r\n		<div class=\"col align-self-center ms-2\">\r\n			\r\n			\r\n	<h6 class=\"mb-0 text-forum\"><a href=\"{$post_url}{$highlight}#pid{$post[\'pid\']}\">{$post[\'subject\']}</a>{$thread[\'multipage\']}</h6>\r\n			<div class=\"links small\"><span class=\"text-muted\">{$lang->search[\'by\']}</span> {$post[\'profilelink\']} <span class=\"text-muted\">{$lang->search[\'forum\']}</span> {$post[\'forumlink\']}</div>\r\n		</div>\r\n			\r\n		<div class=\"col-1 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block align-self-center text-center\">\r\n			\r\n			<h6 class=\"mb-0\">{$post[\'thread_replies\']}</h6><span class=\"text-muted small\">{$lang->search[\'replies\']}</span>\r\n			\r\n		</div>\r\n			\r\n		<div class=\"col-12 col-sm-12 col-md-12 col-lg-3 col-xl-3 col-xxl-3 mt-3 mt-sm-3 mt-md-3 mt-lg-0\">\r\n			<div class=\"row\">\r\n				<div class=\"col-auto align-self-center\">\r\n					<avatarep_uid_[{$post[\'uid\']}]>\r\n				</div>\r\n				<div class=\"col align-self-center me-2\">{$post[\'profilelink\']} <br /><span class=\"text-desc small\">{$posted}</span> {$inline_mod_checkbox}\r\n					</div>\r\n				</div>\r\n				\r\n				\r\n				\r\n				\r\n			</div>\r\n			</div>\r\n	</div>\r\n			</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1499','search_results_threads','<html>\r\n		<head>\r\n		<title>{$SITENAME} - {$lang->search[\'search_results\']}</title>\r\n		{$headerinclude}\r\n		</head>\r\n		<body>\r\n		{$header}\r\n			<div class=\"container-md\">\r\n		{$multipage}\r\n		<div class=\"card border-0\">\r\n<div class=\"card-header py-3 bg-nav rounded border-bottom-0\">\r\n	\r\n	<div class=\"row\">\r\n		<div class=\"col\">\r\n	<p class=\"mb-0\"><a href=\"{$sorturl}&amp;sortby=subject&amp;order=asc\">{$lang->search[\'thread\']}</a> &mdash; <a href=\"{$sorturl}&amp;sortby=starter&amp;order=asc\">{$lang->search[\'author\']}</a></p>\r\n		</div>\r\n		<div class=\"col-1 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block text-center\">\r\n			<p class=\"mb-0\">\r\n				&nbsp;<a href=\"{$sorturl}&amp;sortby=replies&amp;order=desc\">{$lang->search[\'replies\']}</a>\r\n			</p>\r\n		</div>\r\n		<div class=\"col-3\">\r\n			<span class=\"float-end\">{$inlinemodcol}</span>\r\n			&nbsp;<a href=\"{$sorturl}&amp;sortby=lastpost&amp;order=desc\" class=\"d-none d-sm-none d-md-none d-lg-inline-block d-xl-inline-block d-xxl-inline-block\">{$lang->search[\'lastpost\']}</a>\r\n			\r\n		</div>\r\n	</div>\r\n</div>\r\n</div>	\r\n			\r\n			\r\n			{$results}\r\n		\r\n		{$inline_edit_js}\r\n	\r\n	{$inlinemod}\r\n		\r\n				\r\n			</div>\r\n	{$multipage}\r\n	</div>\r\n		{$footer}\r\n		</body>\r\n		</html>','2','1837','','1720609281');
