INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1512','showthread','<html>\r\n<head>\r\n<title>{$thread[\'subject\']}</title>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var quickdelete_confirm = \"Are you sure you want to delete this post?\";\r\n	var quickrestore_confirm = \"Are you sure you want to restore this post?\";\r\n	var allowEditReason = \"1\";\r\n	var thread_deleted = \"{$thread_deleted}\";\r\n	var visible_replies = \"{$thread[\'replies\']}\";\r\n	\r\n	lang.save_changes = \"Save Changes\";\r\n	lang.cancel_edit = \"Cancel Edit\";\r\n	lang.quick_edit_update_error = \"There was an error editing your reply:\";\r\n	lang.quick_reply_post_error = \"There was an error posting your reply:\";\r\n	lang.quick_delete_error = \"There was an error deleting your reply:\";\r\n	lang.quick_delete_success = \"The post was deleted successfully.\";\r\n	lang.quick_delete_thread_success = \"The thread was deleted successfully.\";\r\n	lang.quick_restore_error = \"There was an error restoring your reply:\";\r\n	lang.quick_restore_success = \"The post was restored successfully.\";\r\n	lang.editreason = \"Edit Reason\";\r\n	lang.post_deleted_error = \"You can not perform this action to a deleted post.\";\r\n	lang.softdelete_thread = \"Soft Delete Thread\";\r\n	lang.restore_thread = \"Restore Thread\";\r\n	const forumBaseUrl = \"{$test}\";\r\n// -->\r\n</script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/thread.js?ver=1827\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/toast.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/edit_post.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/delete_post.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/report_post.js\"></script>\r\n\r\n\r\n</head>\r\n<body>\r\n\r\n\r\n	\r\n	\r\n<div class=\"container-md\">\r\n	\r\n\r\n	\r\n<div class=\"row mb-3 p-0 m-0\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl p-0 align-self-center text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start mt-3 mt-sm-3 mt-md-3 mt-lg-0 mt-xl-0 mt-xxl-0\">\r\n		{$multipage}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-auto col-xl-auto col-xxl-auto m-0 p-0 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center order-first order-sm-first order-md-first order-lg-last order-xl-last order-xxl-last\">\r\n		\r\n		{$addremovesubscription} {$newreply}\r\n			\r\n		\r\n	</div>\r\n	</div>\r\n\r\n{$pollbox}\r\n	<div id=\"posts\">{$posts}</div>\r\n	\r\n	\r\n	\r\n\r\n	\r\n	\r\n	<div class=\"row mt-3 mb-3 p-0 m-0\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl p-0 align-self-center text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start mb-3 mb-sm-3 mb-md-3 mb-lg-0 mb-xl-0 mb-xxl-0\">\r\n		{$multipage}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-auto col-xl-auto col-xxl-auto m-0 p-0 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center\">\r\n		\r\n		 {$newreply}\r\n			\r\n		\r\n	</div>\r\n	</div>\r\n	\r\n	\r\n{$quickreply}\r\n\r\n<div class=\"container-md\">	\r\n<div class=\"row mt-5 m-0 p-0 border-top border-bottom\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-5 col-xl-5 col-xxl-5 align-self-center py-3\">\r\n		{$search_thread}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center py-3\"><a href=\"{$next_oldest_link}\" class=\"links\"><i class=\"fa-solid fa-angles-left\"></i> {$lang->showthread[\'next_oldest\']}</a> &nbsp;&nbsp;&nbsp;&nbsp; <a href=\"{$next_newest_link}\" class=\"links\">{$lang->showthread[\'next_newest\']} <i class=\"fa-solid fa-angles-right\"></i></a>\r\n	</div>\r\n	\r\n	</div>\r\n	\r\n		<div class=\"row m-0 p-0 mt-2 text-end\">\r\n			<div class=\"col-12 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center\">\r\n					{$addpoll}{$printthread}&nbsp;&nbsp; {$sendthread}\r\n			</div></div>\r\n	\r\n	{$moderationoptions}\r\n	\r\n		{$usersbrowsing}\r\n	\r\n</div>\r\n	\r\n\r\n	</div>\r\n	<script type=\"text/javascript\">\r\n		var thread_deleted = \"{$thread_deleted}\";\r\n		if(thread_deleted == \"1\")\r\n		{\r\n			$(\"#quick_reply_form, .new_reply_button, .thread_tools, .inline_rating\").hide();\r\n			$(\"#moderator_options_selector option.option_mirage\").attr(\"disabled\",\"disabled\");\r\n		}\r\n	</script>\r\n	\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1513','showthread_add_poll','<a href=\"polls.php?action=newpoll&amp;tid={$tid}\" title=\"{$lang->showthread[\'add_poll_to_thread\']}\" class=\"links\"><i class=\"fa-solid fa-square-poll-vertical\"></i></a> &nbsp;&nbsp;','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1514','showthread_inlinemoderation','<div class=\"col-lg\">\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/inline_moderation.js?ver=1821\"></script>\r\n<form action=\"moderation.php\" method=\"post\" style=\"margin-top: 0; margin-bottom: 0;\" id=\"inlinemoderation_options\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"modtype\" value=\"inlinepost\" />\r\n	<div class=\"row g-1\">\r\n		<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n			&nbsp;\r\n		</div>\r\n		<div class=\"col-auto\">\r\n<select name=\"action\" id=\"inlinemoderation_options_selector\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n{$standardposttools}\r\n{$customposttools}\r\n</select>\r\n		</div>\r\n		<div class=\"col-auto\">\r\n		\r\n<input type=\"submit\" class=\"btn btn-sm btn-primary\" name=\"go\" value=\"{$lang->showthread[\'go\']} ({$inlinecount})\" id=\"inline_go\" /> <input type=\"button\" class=\"btn btn-sm btn-primary\" onclick=\"inlineModeration.clearChecked();\" value=\"{$lang->showthread[\'clear\']}\" />\r\n</form>\r\n	</div>\r\n	</div>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var go_text = \"{$lang->showthread[\'inline_go\']}\";\r\n	var all_text = \"{$threadcount}\";\r\n	var inlineType = \"thread\";\r\n	var inlineId = {$tid};\r\n\r\n	// ЗАМЕНА jQuery на чистый JavaScript\r\n	document.addEventListener(\'DOMContentLoaded\', function() {\r\n		var selector = document.getElementById(\"inlinemoderation_options_selector\");\r\n		var form = document.getElementById(\"inlinemoderation_options\");\r\n		\r\n		if(selector && form) {\r\n			selector.addEventListener(\'change\', function() {\r\n				form.dispatchEvent(new Event(\'submit\'));\r\n			});\r\n		}\r\n	});\r\n// -->\r\n</script>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1515','showthread_moderationoptions','<div class=\"row mt-5 g-1 m-0 py-3 border-top border-bottom\">\r\n	<div class=\"col-lg-6\">\r\n\r\n<form action=\"moderation.php\" method=\"post\" style=\"margin-top: 0; margin-bottom: 0;\" id=\"moderator_options\">\r\n	<input type=\"hidden\" name=\"modtype\" value=\"thread\" />\r\n	<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n	<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"row g-1 text-lg-start\">\r\n<div class=\"col-auto\">\r\n	<select name=\"action\" id=\"moderator_options_selector\" class=\"form-select form-select-sm w-auto pe-5\">\r\n		<option value=\"delayedmoderation\">{$lang->showthread[\'delayed_moderation\']}</option>\r\n		{$standardthreadtools}\r\n		{$customthreadtools}\r\n	</select>\r\n</div>\r\n<div class=\"col-auto\">\r\n{$gobutton}\r\n</div>\r\n</div>\r\n</form>\r\n<script type=\"text/javascript\">\r\n<!--\r\n	// ЗАМЕНА jQuery на чистый JavaScript\r\n	document.addEventListener(\'DOMContentLoaded\', function() {\r\n		var selector = document.getElementById(\"moderator_options_selector\");\r\n		var form = document.getElementById(\"moderator_options\");\r\n		\r\n		if(selector && form) {\r\n			selector.addEventListener(\'change\', function() {\r\n				form.dispatchEvent(new Event(\'submit\'));\r\n			});\r\n		}\r\n	});\r\n//-->\r\n</script>\r\n		\r\n	</div>\r\n{$inlinemod}\r\n	</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1516','showthread_newreply','<a href=\"newreply.php?tid={$tid}\" class=\"btn btn-primary\" type=\"button\"><i class=\"fa-solid fa-comment\"></i> &nbsp;{$lang->showthread[\'post_reply\']}</a>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1517','showthread_newreply_closed','<button class=\"btn btn-primary\" disabled>{$lang->thread_closed}</button>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1518','showthread_poll','<form action=\"polls.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"vote\" />\r\n<input type=\"hidden\" name=\"pid\" value=\"{$poll[\'pid\']}\" />\r\n	\r\n				<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded text-19 fw-bold\">\r\n		{$poll[\'question\']}<span class=\"badge bg-primary border border-white float-end text-uppercase small fw-normal\">{$lang->poll}</span>\r\n	</div>\r\n	<div class=\"card-body\">\r\n		<div class=\"row pb-3\">\r\n			<div class=\"col\">\r\n <span class=\"text-desc\">{$publicnote} {$closeon}</span>\r\n			</div>\r\n		</div>\r\n{$polloptions}\r\n		\r\n</div>\r\n					<div class=\"card-footer border-top-0 rounded\">\r\n						\r\n						<div class=\"row g-1\">\r\n							<div class=\"col-auto\">\r\n						 <button type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"{$lang->vote}\">{$lang->vote}</button>\r\n							</div>\r\n							<div class=\"col text-end align-self-center\">\r\n								{$edit_poll} <a href=\"polls.php?action=showresults&amp;pid={$poll[\'pid\']}\"><i class=\"fa-solid fa-square-poll-horizontal\"></i> {$lang->show_results}</a>\r\n							</div>\r\n						</div>\r\n					\r\n				\r\n					\r\n				\r\n\r\n					</div></div>\r\n</form>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1519','showthread_poll_editpoll','<a href=\"polls.php?action=editpoll&amp;pid={$poll[\'pid\']}\" title=\"{$lang->edit_poll}\"><i class=\"fa-solid fa-pencil\"></i> {$lang->edit_poll}</a>&nbsp;&nbsp;','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1520','showthread_poll_option','<div class=\"row py-3 border-top text-forum\">\r\n	<div class=\"col\" style=\"margin-bottom: 4px; width: 20px\">\r\n<label class=\"text-forum fw-normal\"><input type=\"radio\" class=\"form-check-input\" name=\"option\" id=\"option_{$number}\" value=\"{$number}\" /> &nbsp;&nbsp;{$option}</label>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1521','showthread_poll_option_multiple','<div class=\"row py-3 border-top text-forum\">\r\n	<div class=\"col\" style=\"margin-bottom: 4px; width: 20px\">\r\n<label class=\"text-forum fw-normal\"><input type=\"checkbox\" class=\"form-check-input\" name=\"option[{$number}]\" id=\"option_{$number}\" value=\"1\" />&nbsp;&nbsp;{$option}</label>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1522','showthread_poll_resultbit','<div class=\"row pt-3 border-top text-forum\">\r\n<div class=\"col-auto text-forum\">\r\n	{$option}{$votestar}\r\n</div>\r\n	<div class=\"col-lg text-end align-self-center\">\r\n	 {$votes} ({$percent}%)\r\n	</div>\r\n</div>\r\n<div class=\"row pb-3 text-forum\">\r\n	\r\n	\r\n	<div class=\"col-lg\">\r\n	<div class=\"progress mb-1\" style=\"height: 25px\">\r\n  <div class=\"progress-bar pg-primary\" role=\"progressbar\" style=\"width:{$percent}%\"  aria-valuenow=\"{$percent}\" aria-valuemin=\"0\" aria-valuemax=\"100\"></div>\r\n</div>\r\n</div>	\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1523','showthread_poll_results','<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded text-19 fw-bold\">\r\n		{$poll[\'question\']}<span class=\"badge bg-primary border border-white float-end text-uppercase small fw-normal\">{$lang->poll}</span>\r\n	</div>\r\n	<div class=\"card-body\">\r\n		<div class=\"row pb-3\">\r\n			<div class=\"col\">\r\n <span class=\"text-desc\">{$pollstatus} {$undovote} {$publicnote} {$closeon}</span>\r\n			</div>\r\n		</div>\r\n{$polloptions}\r\n		<div class=\"text-end\"><span class=\"text-forum\">{$lang->total} {$lang->total_votes} {$totpercent}</span></div>\r\n</div>\r\n					<div class=\"card-footer border-top-0 rounded\">\r\n						\r\n						<div class=\"row g-1\">\r\n							<div class=\"col-auto\">\r\n						 <button type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"{$lang->vote}\">{$lang->vote}</button>\r\n							</div>\r\n							<div class=\"col text-end align-self-center\">\r\n								{$edit_poll} &nbsp; <a href=\"polls.php?action=showresults&amp;pid={$poll[\'pid\']}\"><i class=\"fa-solid fa-square-poll-horizontal\"></i> {$lang->show_results}</a>\r\n							</div>\r\n						</div>\r\n				</div></div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1524','showthread_printthread','<a href=\"printthread.php?tid={$tid}\" class=\"links\"><i class=\"fa-solid fa-print\" title=\"{$lang->view_printable}\"></i></a>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1525','showthread_quickreply','<div id=\"quickreply_spinner\" class=\"showthread_spinner\" style=\"display: none\"><i class=\"fa-solid fa-circle-notch fa-spin\" style=\"color: #0b59e0;\"></i></div>\r\n\r\n{$moderation_notice}\r\n<form method=\"post\" action=\"newreply.php?tid={$tid}&amp;processed=1\" name=\"quick_reply_form\" id=\"quick_reply_form\">\r\n	<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<input type=\"hidden\" name=\"subject\" value=\"RE: {$reply_subject}\" />\r\n	<input type=\"hidden\" name=\"action\" value=\"do_newreply\" />\r\n	<input type=\"hidden\" name=\"posthash\" value=\"{$posthash}\" id=\"posthash\" />\r\n	<input type=\"hidden\" name=\"quoted_ids\" value=\"\" id=\"quoted_ids\" />\r\n	<input type=\"hidden\" name=\"lastpid\" id=\"lastpid\" value=\"{$last_pid}\" />\r\n	<input type=\"hidden\" name=\"from_page\" value=\"{$page}\" />\r\n	<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n	<input type=\"hidden\" name=\"method\" value=\"quickreply\" />\r\n	\r\n	\r\n	\r\n<div class=\"row d-flex g-2 mb-4 mt-5\">\r\n    <div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\"><img src=\"{$CURUSER[\'avatar\']}\" class=\"rounded d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block img-fluid\" style=\"width: 100px;\"></div>\r\n    <div class=\"col\">\r\n		<div class=\"editor_control_bar mb-3 border border-top-5 p-2\" id=\"quickreply_multiquote\" style=\"display: none;\">\r\n					{$lang->showthread[\'quickreply_multiquote_selected\']} <a href=\"./newreply.php?tid={$tid}&amp;load_all_quotes=1\" onclick=\"return Thread.loadMultiQuoted();\">{$lang->showthread[\'quickreply_multiquote_now\']}</a> {$lang->showthread[\'or\']} <a href=\"javascript:void(0)\" onclick=\"Thread.clearMultiQuoted(); return false;\">{$lang->showthread[\'quickreply_multiquote_deselect\']}</a>.\r\n		</div>\r\n        <div class=\"card\">\r\n            <div class=\"card-body\">\r\n				<h6 class=\"mb-2\">{$CURUSER[\'username\']}</h6>\r\n		<textarea class=\"form-control form-control-sm border-0 p-0\" style=\"resize: none; height: 150px;\"  name=\"message\" id=\"message\" tabindex=\"1\" placeholder=\"Write a reply to this message...\"></textarea>\r\n			\r\n				\r\n	<div id=\"collapse-reply\" class=\"collapse bg-nav p-2\">\r\n{$closeoption}\r\n </div>\r\n				</div>\r\n			\r\n				<div class=\"card-footer border-top-0\">\r\n					<button type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->showthread[\'post_reply\']}\" tabindex=\"2\" accesskey=\"s\" id=\"quick_reply_submit\"><i class=\"fa-solid fa-comment\"></i> &nbsp;{$lang->showthread[\'post_reply\']}</button> <a class=\"btn btn-thread ms-3 me-3\" data-bs-toggle=\"collapse\" aria-expanded=\"false\" aria-controls=\"collapse-1\" href=\"#collapse-reply\" role=\"button\"><i class=\"fa-solid fa-gear\"></i></a> <button type=\"submit\" class=\"btn btn-thread\" name=\"previewpost\" value=\"{$lang->showthread[\'preview_post\']}\" tabindex=\"3\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;{$lang->showthread[\'preview_post\']}</button>\r\n				</div>\r\n			</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n\r\n	\r\n</form>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1526','showthread_quickreply_options_close','<input type=\"checkbox\" class=\"form-check-input\" name=\"modoptions[closethread]\" value=\"1\"{$closelinkch} /> {$lang->close_thread} <br />','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1527','showthread_quickreply_options_signature','<input type=\"checkbox\" class=\"form-check-input\" name=\"postoptions[signature]\" value=\"1\" {$postoptionschecked[\'signature\']} /> {$lang->showthread[\'signature\']} <br />','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1528','showthread_quickreply_options_stick','<input type=\"checkbox\" class=\"form-check-input\" name=\"modoptions[stickthread]\" value=\"1\"{$stickch} /> {$lang->stick_thread}','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1529','showthread_ratethread','<div class=\"col-auto align-self-center p-0 pb-2 \">\r\n	\r\n	<div class=\"star_rating_container\">\r\n	<script type=\"text/javascript\">\r\n		<!--\r\n			lang.ratings_update_error = \"{$lang->ratings_update_error}\";\r\n		// -->\r\n		</script>\r\n		<script type=\"text/javascript\" src=\"{$mybb->asset_url}/jscripts/rating.js?ver=1821\"></script>\r\n		<div id=\"success_rating_{$thread[\'tid\']}\" style=\"float: left; padding-top: 2px; padding-right: 10px;\">&nbsp;</div>\r\n		<div class=\"inline_rating\">\r\n\r\n<ul class=\"star_rating{$not_rated}\" id=\"rating_thread_{$thread[\'tid\']}\">\r\n<li style=\"width: {$thread[\'width\']}%\" class=\"current_rating\" id=\"current_rating_{$thread[\'tid\']}\">{$ratingvotesav}</li>\r\n<li><a class=\"five_stars\" title=\"{$lang->five_stars}\" href=\"./ratethread.php?tid={$thread[\'tid\']}&amp;rating=5&amp;my_post_key={$mybb->post_code}\"></a></li>\r\n<li><a class=\"four_stars\" title=\"{$lang->four_stars}\" href=\"./ratethread.php?tid={$thread[\'tid\']}&amp;rating=4&amp;my_post_key={$mybb->post_code}\"></a></li>\r\n<li><a class=\"three_stars\" title=\"{$lang->three_stars}\" href=\"./ratethread.php?tid={$thread[\'tid\']}&amp;rating=3&amp;my_post_key={$mybb->post_code}\"></a></li>\r\n<li><a class=\"two_stars\" title=\"{$lang->two_stars}\" href=\"./ratethread.php?tid={$thread[\'tid\']}&amp;rating=2&amp;my_post_key={$mybb->post_code}\"></a></li>\r\n<li><a class=\"one_star\" title=\"{$lang->one_star}\" href=\"./ratethread.php?tid={$thread[\'tid\']}&amp;rating=1&amp;my_post_key={$mybb->post_code}\"></a></li>\r\n			</ul>\r\n		</div>\r\n</div>\r\n\r\n</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1530','showthread_search','<div class=\"row g-1\">\r\n	<div class=\"col align-self-center\">\r\n<form action=\"search.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"action\" value=\"thread\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$thread[\'tid\']}\" />\r\n  <input type=\"text\" name=\"keywords\" class=\"form-control border form-control-sm border rounded-end me-1\" size=\"25\" /></div>\r\n		<div class=\"col-auto align-self-center\">\r\n  <button type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"Go!\"><i class=\"fa-solid fa-magnifying-glass\"></i> &nbsp;{$lang->showthread[\'search_thread\']}</button>\r\n		</div>\r\n	</div>\r\n	</form>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1531','showthread_send_thread','<a href=\"sendthread.php?tid={$tid}\"  class=\"links\"><i class=\"fa-solid fa-reply\" title=\"{$lang->send_thread}\"></i></a>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1533','showthread_similarthreads_bit','<div class=\"row p-0\">\r\n	<div class=\"col text-muted\">\r\n		\r\n		<span style=\"font-size: 18px\"><a href=\"{$similar_thread[\'threadlink\']}\">{$similar_thread[\'threadprefix\']}{$similar_thread[\'subject\']}</a></span> <br />\r\n		{$lang->by} <avatarep_suid_[{$similar_thread[\'uid\']}]>{$similar_thread[\'profilelink\']}\r\n		\r\n	</div>\r\n	<div class=\"col-2 align-self-center\">\r\n		\r\n		<span class=\"text-muted\">{$lang->replies}</span> {$similar_thread[\'replies\']}<br />\r\n		<span class=\"text-muted\">{$lang->views}</span> {$similar_thread[\'views\']}\r\n		\r\n	</div>\r\n	\r\n	<div class=\"col-3 align-self-center\">\r\n		<span class=\"smalltext\">{$lastpostdate}<br />\r\n		<a href=\"{$similar_thread[\'lastpostlink\']}\">{$lang->lastpost} {$lang->by}</a> <avatarep_suid_[{$similar_thread[\'lastposteruid\']}]>{$lastposterlink}</span>\r\n	</div>\r\n</div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1534','showthread_subscription','<a class=\"btn btn-secondary\" href=\"usercp.php?action={$add_remove_subscription}subscription&amp;tid={$tid}&amp;my_post_key={$mybb->post_code}\">&nbsp;{$add_remove_subscription_text}&nbsp;</a>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1535','showthread_threadedbox','<br />\r\n<div class=\"alert alert-success\">\r\n	<span class=\"smalltext\"><strong>{$lang->messages_in_thread}</strong></span>\r\n	<hr />\r\n	{$threadedbits}\r\n</div>','2','1830','','1720609281');
