INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1543','stats','<html>\r\n<head>\r\n    <title>{$SITENAME} - {$lang->stats[\'board_stats\']}</title>\r\n   \r\n    <!-- Bootstrap Icons -->\r\n    <link rel=\"stylesheet\" href=\"{$BASEURL}/include/templates/default/style/bootstrap-icons.css\">\r\n    <style>\r\n        .card-hover:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: 0 0.5rem 1rem rgba(0,0,0,.1);\r\n            transition: all 0.3s ease;\r\n        }\r\n        .icon-blue {\r\n            color: #0d6efd; /* Bootstrap primary blue */\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n<div class=\"container my-5\">\r\n\r\n    <div class=\"row\">\r\n        <div class=\"col-lg-9\">\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-chat-left-text icon-blue me-1\"></i> {$lang->stats[\'most_replied_threads\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    {$mostreplies}\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-eye icon-blue me-1\"></i> {$lang->stats[\'most_viewed_threads\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    {$mostviews}\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n        <div class=\"col-lg-3\">\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-bar-chart icon-blue me-1\"></i> {$lang->stats[\'totals\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-pencil icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'posts\']}</span> <span class=\"fw-bold\">{$stats[\'numposts\']}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-card-text icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'threads\']}</span> <span class=\"fw-bold\">{$stats[\'numthreads\']}</span>\r\n                    </div>\r\n                    <div class=\"py-2\">\r\n                        <i class=\"bi bi-people icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'members\']}</span> <span class=\"fw-bold\">{$stats[\'numusers\']}</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-graph-up icon-blue me-1\"></i> {$lang->stats[\'averages\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-pencil icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'ppd\']}</span> <span class=\"fw-bold\">{$postsperday}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-card-text icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'tpd\']}</span> <span class=\"fw-bold\">{$threadsperday}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-person-plus icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'mpd\']}</span> <span class=\"fw-bold\">{$membersperday}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-chat-dots icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'ppm\']}</span> <span class=\"fw-bold\">{$postspermember}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-threads icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'tpm\']}</span> <span class=\"fw-bold\">{$threadspermember}</span>\r\n                    </div>\r\n                    <div class=\"py-2\">\r\n                        <i class=\"bi bi-arrow-return-right icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'rpt\']}</span> <span class=\"fw-bold\">{$repliesperthread}</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"card shadow-sm mb-4 border-0 card-hover\">\r\n                <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n                    <i class=\"bi bi-info-circle icon-blue me-1\"></i> {$lang->stats[\'averages\']}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-person-check icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'newest_member\']}</span> <span class=\"fw-bold\">{$stats[\'newest_user\']}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-percent icon-blue me-1\"></i> <span class=\"text-muted\">{$lang->stats[\'members_posted\']}</span> <span class=\"fw-bold\">{$havepostedpercent}</span>\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-star icon-blue me-1\"></i> {$todays_top_poster}\r\n                    </div>\r\n                    <div class=\"py-2 border-bottom\">\r\n                        <i class=\"bi bi-fire icon-blue me-1\"></i> {$popular_forum}\r\n                    </div>\r\n                    <div class=\"py-2\">\r\n                        <i class=\"bi bi-person-heart icon-blue me-1\"></i> {$top_referrer}\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n\r\n</div>\r\n</body>\r\n</html>\r\n','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1544','stats_thread','<div class=\"row py-2 border-bottom\">\r\n	<div class=\"col-lg-10\">\r\n		<h6 class=\"mb-0\"><a href=\"{$thread[\'threadlink\']}\">{$thread[\'subject\']}</a></h6>\r\n	</div>\r\n	<div class=\"col-lg-2 text-lg-end\">\r\n		{$numberbit} {$numbertype}\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1545','usercp','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{$SITENAME} - {$lang->usercp[\'user_cp\']}</title>\r\n   \r\n    <style>\r\n        .user-stats-card {\r\n            border-radius: 12px;\r\n            border: none;\r\n            background: linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%);\r\n            color: #2c3e50;\r\n        }\r\n        \r\n        .user-avatar {\r\n            width: 100px;\r\n            height: 100px;\r\n            border-radius: 50%;\r\n            object-fit: cover;\r\n            border: 3px solid #ffffff;\r\n        }\r\n        \r\n        .stat-item {\r\n            transition: all 0.3s ease;\r\n            padding: 12px 0;\r\n            display: flex;\r\n            align-items: center;\r\n        }\r\n        \r\n        .stat-item:hover {\r\n            background-color: rgba(0,0,0,0.03);\r\n            padding-left: 15px;\r\n            border-radius: 8px;\r\n        }\r\n        \r\n        .username-display {\r\n            font-size: 1.4rem;\r\n            font-weight: 600;\r\n            color: #2c3e50;\r\n        }\r\n        \r\n        .stat-label {\r\n            color: #6c757d;\r\n            font-weight: 500;\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 10px;\r\n            flex: 1;\r\n        }\r\n        \r\n        .stat-value {\r\n            color: #2c3e50;\r\n            font-weight: 600;\r\n        }\r\n        \r\n        .border-custom {\r\n            border-color: #e9ecef !important;\r\n        }\r\n        \r\n        .badge-status {\r\n            background: #28a745;\r\n            color: white;\r\n            padding: 4px 12px;\r\n            border-radius: 15px;\r\n            font-size: 0.8rem;\r\n        }\r\n        \r\n        .icon-wrapper {\r\n            width: 20px;\r\n            text-align: center;\r\n            color: #667eea;\r\n        }\r\n        \r\n        .icon-user {\r\n            color: #667eea;\r\n        }\r\n        \r\n        .icon-post {\r\n            color: #4CAF50;\r\n        }\r\n        \r\n        .icon-comment {\r\n            color: #2196F3;\r\n        }\r\n        \r\n        .icon-bonus {\r\n            color: #FF9800;\r\n        }\r\n        \r\n        .icon-email {\r\n            color: #9C27B0;\r\n        }\r\n        \r\n        .icon-date {\r\n            color: #607D8B;\r\n        }\r\n        \r\n        .icon-group {\r\n            color: #E91E63;\r\n        }\r\n    </style>\r\n</head>\r\n\r\n<div class=\"container-md py-4\">\r\n    <div class=\"row g-4\">\r\n        <!-- Навигационная панель -->\r\n        <div class=\"col-12 col-lg-3\">\r\n            <div class=\"sticky-top\" style=\"top: 20px;\">\r\n                {$usercpnav}\r\n            </div>\r\n        </div>\r\n        \r\n        <!-- Основной контент -->\r\n        <div class=\"col\">\r\n            <div class=\"card user-stats-card mb-4\">\r\n                <div class=\"card-body p-4\">\r\n                    <div class=\"row align-items-center\">\r\n                        <!-- Аватар -->\r\n                        <div class=\"col-auto text-center\">\r\n                            \r\n                                {$currentavatar}\r\n                                <div class=\"position-absolute bottom-0 end-0 bg-success rounded-circle border border-2 border-white\" \r\n                                     style=\"width: 20px; height: 20px;\"></div>\r\n                           \r\n                            <div class=\"mt-2\">\r\n                                <span class=\"badge-status\">Online</span>\r\n                            </div>\r\n                        </div>\r\n                        \r\n                        <!-- Статистика пользователя -->\r\n                        <div class=\"col\">\r\n                            <!-- Имя пользователя -->\r\n                            <div class=\"stat-item border-bottom border-custom mb-3\">\r\n                                <div class=\"d-flex align-items-center\">\r\n                                    <i class=\"fas fa-user icon-user me-3\"></i>\r\n                                    <div class=\"username-display\">{$username}</div>\r\n                                </div>\r\n                            </div>\r\n                            \r\n                            <!-- Статистика в две колонки -->\r\n                            <div class=\"row\">\r\n                                <div class=\"col-md-6\">\r\n                                    <!-- Количество сообщений -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-comment icon-post\"></i>\r\n                                            {$lang->usercp[\'postnum\']}\r\n                                        </span>\r\n                                        <a href=\"search.php?action=finduser&amp;uid={$CURUSER[\'id\']}\" class=\"stat-value text-decoration-none\">\r\n                                            {$mybb->user[\'posts\']} {$ss}\r\n                                        </a>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Комментарии -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-comments icon-comment\"></i>\r\n                                            {$lang->usercp[\'comentsss\']}\r\n                                        </span>\r\n                                        <a href=\"userhistory.php?action=viewcomments&id={$CURUSER[\'id\']}\" class=\"stat-value text-decoration-none\">\r\n                                            {$com}\r\n                                        </a>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Бонусные баллы -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-star icon-bonus\"></i>\r\n                                            {$lang->usercp[\'bpoints\']}\r\n                                        </span>\r\n                                        <a href=\"mybonus.php\" class=\"stat-value text-decoration-none\">\r\n                                            {$bonus}\r\n                                        </a>\r\n                                    </div>\r\n                                </div>\r\n                                \r\n                                <div class=\"col-md-6\">\r\n                                    <!-- Email -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-envelope icon-email\"></i>\r\n                                            {$lang->usercp[\'email\']}\r\n                                        </span>\r\n                                        <span class=\"stat-value\">{$CURUSER[\'email\']}</span>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Дата регистрации -->\r\n                                    <div class=\"stat-item border-bottom border-custom d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-calendar-alt icon-date\"></i>\r\n                                            {$lang->usercp[\'registration_date\']}\r\n                                        </span>\r\n                                        <span class=\"stat-value\">{$regdate}</span>\r\n                                    </div>\r\n                                    \r\n                                    <!-- Основная группа -->\r\n                                    <div class=\"stat-item d-flex justify-content-between align-items-center\">\r\n                                        <span class=\"stat-label\">\r\n                                            <i class=\"fas fa-users icon-group\"></i>\r\n                                            {$lang->usercp[\'primary_usergroup\']}\r\n                                        </span>\r\n                                        <span class=\"stat-value\">{$usergroup}</span>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1546','usercp_addsubscription_thread','<html>\r\n<head>\r\n<title>{$lang->usercp[\'subscribe_to_thread\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"usercp.php\" method=\"post\" name=\"input\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_addsubscription\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$thread[\'tid\']}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-3 d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">	\r\n	<!-- offcanvas -->\r\n				<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n				<button class=\"btn btn-primary mb-3\" type=\"button\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#offcanvasExample\" aria-controls=\"offcanvasExample\">\r\n  <i class=\"fa-solid fa-circle-arrow-left\"></i> &nbsp;{$lang->ucpmenu}\r\n</button>\r\n				\r\n				<div class=\"offcanvas offcanvas-start\" tabindex=\"-1\" id=\"offcanvasExample\" aria-labelledby=\"offcanvasExampleLabel\">\r\n  <div class=\"offcanvas-header\">\r\n    <h5 class=\"offcanvas-title\" id=\"offcanvasExampleLabel\">{$lang->usercp[\'ucp_nav_menu\']}</h5>\r\n    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"offcanvas\" aria-label=\"Close\"></button>\r\n  </div>\r\n  <div class=\"offcanvas-body\">\r\n    <div><ul class=\"list-group list-group-flush\">\r\n		{$usercpnav}</ul>\r\n    </div>\r\n  </div>\r\n</div>\r\n				</div>\r\n				<!-- /offcanvas -->\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	<div class=\"legend mb-4\">{$lang->usercp[\'subscribe_to_thread\']}</div>\r\n\r\n	<div class=\"ps-3 pe-3\"><strong>{$lang->usercp[\'notification_method\']}</strong></div>\r\n\r\n	<div class=\"row ps-3 pe-3 mt-4\">\r\n		<div class=\"col-auto align-self-top text-center\">\r\n			\r\n			<input type=\"radio\" name=\"notification\" id=\"notification_none\" class=\"form-check-input\" value=\"0\" {$notification_none_checked} />\r\n			\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n		<strong>{$lang->usercp[\'no_notification\']}</strong><br /><span class=\"text-muted\">{$lang->usercp[\'no_notification_desc\']}</span>\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"row ps-3 pe-3 mt-2\">\r\n		<div class=\"col-auto align-self-top text-center\">\r\n			\r\n			<input type=\"radio\" class=\"form-check-input\" name=\"notification\" id=\"notification_email\" value=\"1\" {$notification_email_checked} />\r\n			\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n		<strong>{$lang->usercp[\'email_notification\']}</strong><br /><span class=\"text-muted\">{$lang->usercp[\'email_notification_desc\']}</span>\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"row ps-3 pe-3 mt-2\">\r\n		<div class=\"col-auto align-self-top text-center\">\r\n			\r\n			<input type=\"radio\" class=\"form-check-input\" name=\"notification\" id=\"notification_pm\" value=\"2\" {$notification_pm_checked} />\r\n			\r\n		</div>\r\n		<div class=\"col align-self-center\">\r\n		<strong>{$lang->usercp[\'pm_notification\']}</strong><br /><span class=\"text-muted\">{$lang->usercp[\'pm_notification_desc\']}</span>\r\n		</div>\r\n	</div>\r\n\r\n<div class=\"mt-4 text-end ps-3 pe-3\">\r\n	<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n<input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->usercp[\'do_subscribe\']}\" tabindex=\"3\" accesskey=\"s\" />\r\n	</div>\r\n<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n	<input type=\"submit\" class=\"btn btn-primary\" style=\"width: 100%\" name=\"submit\" value=\"{$lang->usercp[\'do_subscribe\']}\" tabindex=\"3\" accesskey=\"s\" />\r\n</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n</form>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1547','usercp_attachments','<!DOCTYPE html>\r\n<html lang=\"{$LANGUAGE}\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{$SITENAME} - {$lang->usercp[\'attachments_manager\']}</title>\r\n    \r\n    <style>\r\n        /* Стили для переключателей */\r\n        .form-switch-custom {\r\n            position: relative;\r\n            display: inline-block;\r\n            width: 60px;\r\n            height: 34px;\r\n        }\r\n        \r\n        .form-switch-custom input {\r\n            opacity: 0;\r\n            width: 0;\r\n            height: 0;\r\n        }\r\n        \r\n        .switch-slider {\r\n            position: absolute;\r\n            cursor: pointer;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background-color: #ccc;\r\n            transition: .4s;\r\n            border-radius: 34px;\r\n        }\r\n        \r\n        .switch-slider:before {\r\n            position: absolute;\r\n            content: \"\";\r\n            height: 26px;\r\n            width: 26px;\r\n            left: 4px;\r\n            bottom: 4px;\r\n            background-color: white;\r\n            transition: .4s;\r\n            border-radius: 50%;\r\n        }\r\n        \r\n        .form-switch-custom input:checked + .switch-slider {\r\n            background-color: #0d6efd;\r\n        }\r\n        \r\n        .form-switch-custom input:checked + .switch-slider:before {\r\n            transform: translateX(26px);\r\n        }\r\n        \r\n        /* Стили для карточек с вложениями */\r\n        .attachment-item {\r\n            border: 1px solid #dee2e6;\r\n            border-radius: 8px;\r\n            padding: 15px;\r\n            margin-bottom: 10px;\r\n            background-color: #f8f9fa;\r\n        }\r\n        \r\n        .attachment-info {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 15px;\r\n        }\r\n        \r\n        .attachment-thumb {\r\n            width: 80px;\r\n            height: 80px;\r\n            object-fit: cover;\r\n            border-radius: 6px;\r\n        }\r\n        \r\n        .attachment-details {\r\n            flex: 1;\r\n        }\r\n        \r\n        /* Адаптивность */\r\n        @media (max-width: 768px) {\r\n            .attachment-info {\r\n                flex-direction: column;\r\n                align-items: flex-start;\r\n                gap: 10px;\r\n            }\r\n            \r\n            .attachment-thumb {\r\n                width: 100%;\r\n                height: auto;\r\n                max-height: 200px;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container-md py-4\">\r\n        <div class=\"row\">\r\n            <!-- Навигация -->\r\n            <div class=\"col-lg-3 mb-4 mb-lg-0\">\r\n                {$usercpnav}\r\n            </div>\r\n            \r\n            <!-- Основной контент -->\r\n            <div class=\"col-lg-9\">\r\n                <!-- Форма управления вложениями -->\r\n                <form action=\"usercp.php\" method=\"post\" name=\"attachmentsmanager\">\r\n                    <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n                    \r\n                    <!-- Карточка с вложениями -->\r\n                    <div class=\"card mb-4 shadow-sm\">\r\n                        <div class=\"card-header bg-white border-bottom py-3\">\r\n                            <div class=\"d-flex justify-content-between align-items-center\">\r\n                                <h5 class=\"card-title mb-0 fw-bold text-primary\">\r\n                                    <i class=\"fas fa-paperclip me-2\"></i>\r\n                                    {$lang->usercp[\'attachments_manager\']}\r\n                                </h5>\r\n                                <div class=\"d-flex align-items-center\">\r\n                                    <span class=\"me-2 text-muted small\">Select All</span>\r\n                                    <label class=\"form-switch-custom\">\r\n                                        <input type=\"checkbox\" name=\"allbox\" class=\"checkall\">\r\n                                        <span class=\"switch-slider\"></span>\r\n                                    </label>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        \r\n                        <div class=\"card-body\">\r\n                            <!-- Уведомление об использовании -->\r\n                            <div class=\"alert alert-info mb-4\">\r\n                                <i class=\"fas fa-info-circle me-2\"></i>\r\n                                {$usagenote}\r\n                            </div>\r\n                            \r\n                            <!-- Список вложений -->\r\n                            <div class=\"attachments-container\">\r\n                                {$attachments}\r\n                            </div>\r\n                        </div>\r\n                        \r\n                        <div class=\"card-footer text-center bg-light py-3\">\r\n                            <button type=\"submit\" class=\"btn btn-danger px-4 py-2\" name=\"delete\" onclick=\"return confirm(\'{$lang->usercp[\'confirm_deletion\']}\')\">\r\n                                <i class=\"fas fa-trash-alt me-2\"></i>\r\n                                {$delete_button}\r\n                            </button>\r\n                        </div>\r\n                    </div>\r\n                </form>\r\n                \r\n                <!-- Пагинация -->\r\n                <div class=\"mb-4 d-flex justify-content-center\">\r\n                    {$multipage}\r\n                </div>\r\n                \r\n                <!-- Статистика -->\r\n                <div class=\"card shadow-sm\">\r\n                    <div class=\"card-header bg-white border-bottom py-3\">\r\n                        <h5 class=\"card-title mb-0 fw-bold text-primary\">\r\n                            <i class=\"fas fa-chart-bar me-2\"></i>\r\n                            {$lang->usercp[\'attachments_stats\']}\r\n                        </h5>\r\n                    </div>\r\n                    \r\n                    <div class=\"card-body\">\r\n                        <div class=\"list-group list-group-flush\">\r\n                            <div class=\"list-group-item border-0 px-0 py-3 d-flex justify-content-between\">\r\n                                <div>\r\n                                    <i class=\"fas fa-file me-2 text-muted\"></i>\r\n                                    <span class=\"text-muted\">{$lang->usercp[\'attachstats_attachs\']}</span>\r\n                                </div>\r\n                                <span class=\"fw-bold text-primary\">{$totalattachments}</span>\r\n                            </div>\r\n                            \r\n                            <div class=\"list-group-item border-0 px-0 py-3 d-flex justify-content-between\">\r\n                                <div>\r\n                                    <i class=\"fas fa-hdd me-2 text-muted\"></i>\r\n                                    <span class=\"text-muted\">{$lang->usercp[\'attachstats_spaceused\']}</span>\r\n                                </div>\r\n                                <span class=\"fw-bold text-success\">{$friendlyusage}</span>\r\n                            </div>\r\n                            \r\n                            <div class=\"list-group-item border-0 px-0 py-3 d-flex justify-content-between\">\r\n                                <div>\r\n                                    <i class=\"fas fa-tachometer-alt me-2 text-muted\"></i>\r\n                                    <span class=\"text-muted\">{$lang->usercp[\'attachstats_quota\']}</span>\r\n                                </div>\r\n                                <span class=\"fw-bold text-info\">{$attachquota}</span>\r\n                            </div>\r\n                            \r\n                            <div class=\"list-group-item border-0 px-0 py-3 d-flex justify-content-between\">\r\n                                <div>\r\n                                    <i class=\"fas fa-download me-2 text-muted\"></i>\r\n                                    <span class=\"text-muted\">{$lang->usercp[\'attachstats_totaldl\']}</span>\r\n                                </div>\r\n                                <span class=\"fw-bold text-warning\">{$totaldownloads}</span>\r\n                            </div>\r\n                            \r\n                            <div class=\"list-group-item border-0 px-0 py-3 d-flex justify-content-between\">\r\n                                <div>\r\n                                    <i class=\"fas fa-network-wired me-2 text-muted\"></i>\r\n                                    <span class=\"text-muted\">{$lang->usercp[\'attachstats_bandwidth\']}</span>\r\n                                </div>\r\n                                <span class=\"fw-bold text-danger\">{$bandwidth}</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <script>\r\n    // JavaScript для переключателей\r\n    document.addEventListener(\'DOMContentLoaded\', function() {\r\n        // Переключатель \"Выбрать все\"\r\n        const checkAllSwitch = document.querySelector(\'.checkall\');\r\n        const allCheckboxes = document.querySelectorAll(\'.attachment-checkbox\');\r\n        \r\n        if (checkAllSwitch) {\r\n            checkAllSwitch.addEventListener(\'change\', function() {\r\n                allCheckboxes.forEach(checkbox => {\r\n                    checkbox.checked = this.checked;\r\n                });\r\n            });\r\n            \r\n            // Проверка, все ли чекбоксы выбраны\r\n            allCheckboxes.forEach(checkbox => {\r\n                checkbox.addEventListener(\'change\', function() {\r\n                    const allChecked = Array.from(allCheckboxes).every(cb => cb.checked);\r\n                    const someChecked = Array.from(allCheckboxes).some(cb => cb.checked);\r\n                    \r\n                    checkAllSwitch.checked = allChecked;\r\n                    checkAllSwitch.indeterminate = !allChecked && someChecked;\r\n                });\r\n            });\r\n        }\r\n        \r\n        // Анимация при наведении на карточки\r\n        const attachmentItems = document.querySelectorAll(\'.attachment-item\');\r\n        attachmentItems.forEach(item => {\r\n            item.addEventListener(\'mouseenter\', function() {\r\n                this.style.transform = \'translateY(-2px)\';\r\n                this.style.boxShadow = \'0 4px 12px rgba(0,0,0,0.1)\';\r\n                this.style.transition = \'all 0.3s ease\';\r\n            });\r\n            \r\n            item.addEventListener(\'mouseleave\', function() {\r\n                this.style.transform = \'translateY(0)\';\r\n                this.style.boxShadow = \'none\';\r\n            });\r\n        });\r\n    });\r\n    </script>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1548','usercp_attachments_attachment','<div class=\"attachment-item border rounded-3 mb-3 p-3 bg-white hover-shadow transition-all\">\r\n    <div class=\"row align-items-center g-3\">\r\n        <!-- Иконка и информация о файле -->\r\n        <div class=\"col-lg-4 col-md-6\">\r\n            <div class=\"d-flex align-items-center gap-3\">\r\n                <!-- Переключатель для выбора -->\r\n                <div class=\"form-check form-switch\">\r\n                    <input type=\"checkbox\" \r\n                           class=\"form-check-input attachment-checkbox\" \r\n                           name=\"attachments[{$attachment[\'aid\']}]\" \r\n                           value=\"{$attachment[\'aid\']}\" \r\n                           id=\"attachment_{$attachment[\'aid\']}\">\r\n                    <label class=\"form-check-label\" for=\"attachment_{$attachment[\'aid\']}\"></label>\r\n                </div>\r\n                \r\n                <!-- Информация о файле -->\r\n                <div class=\"d-flex align-items-center gap-2 flex-grow-1\">\r\n                    <div class=\"attachment-icon\">\r\n                        {$icon}\r\n                    </div>\r\n                    <div class=\"attachment-details\">\r\n                        <a href=\"attachment.php?aid={$attachment[\'aid\']}\" \r\n                           target=\"_blank\" \r\n                           class=\"fw-semibold text-decoration-none text-dark hover-primary\">\r\n                            {$attachment[\'filename\']}\r\n                        </a>\r\n                        <div class=\"text-muted small mt-1\">\r\n                            {$sizedownloads}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Информация о посте -->\r\n        <div class=\"col-lg-4 col-md-6\">\r\n            <div class=\"d-flex align-items-center gap-2\">\r\n                <span class=\"badge bg-light text-dark border\">\r\n                    <i class=\"fas fa-comment me-1\"></i>\r\n                    {$lang->usercp[\'attachments_post\']}\r\n                </span>\r\n                <a href=\"{$attachment[\'postlink\']}#pid{$attachment[\'pid\']}\" \r\n                   class=\"text-truncate text-decoration-none text-secondary hover-primary\">\r\n                    {$attachment[\'subject\']}\r\n                </a>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Дата и дополнительные действия -->\r\n        <div class=\"col-lg-4 col-md-12\">\r\n            <div class=\"d-flex justify-content-between justify-content-lg-end align-items-center gap-3\">\r\n                <!-- Дата загрузки -->\r\n                <div class=\"text-muted small\">\r\n                    <i class=\"far fa-calendar me-1\"></i>\r\n                    {$attachdate}\r\n                </div>\r\n                \r\n                <!-- Дополнительные кнопки действий -->\r\n                <div class=\"d-flex gap-2\">\r\n                    <!-- Кнопка предпросмотра -->\r\n                    <a href=\"attachment.php?aid={$attachment[\'aid\']}\" \r\n                       target=\"_blank\" \r\n                       class=\"btn btn-sm btn-outline-primary\" \r\n                       title=\"Предпросмотр\">\r\n                        <i class=\"fas fa-eye\"></i>\r\n                    </a>\r\n                    \r\n                    <!-- Кнопка скачивания -->\r\n                    <a href=\"attachment.php?aid={$attachment[\'aid\']}&action=download\" \r\n                       class=\"btn btn-sm btn-outline-success\" \r\n                       title=\"Скачать\">\r\n                        <i class=\"fas fa-download\"></i>\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    \r\n    <!-- Дополнительная информация (скрытая по умолчанию) -->\r\n    <div class=\"row mt-3 d-none additional-info\">\r\n        <div class=\"col-12\">\r\n            <div class=\"card bg-light border-0\">\r\n                <div class=\"card-body py-2\">\r\n                    <div class=\"row small text-muted\">\r\n                        <div class=\"col-md-3\">\r\n                            <i class=\"fas fa-file me-1\"></i>\r\n                            Тип: <span class=\"text-dark\">{$attachment[\'filetype\']}</span>\r\n                        </div>\r\n                        <div class=\"col-md-3\">\r\n                            <i class=\"fas fa-expand-alt me-1\"></i>\r\n                            Размер: <span class=\"text-dark\">{$attachment[\'filesize\']}</span>\r\n                        </div>\r\n                        <div class=\"col-md-3\">\r\n                            <i class=\"fas fa-chart-line me-1\"></i>\r\n                            Загрузок: <span class=\"text-dark\">{$attachment[\'downloads\']}</span>\r\n                        </div>\r\n                        <div class=\"col-md-3\">\r\n                            <i class=\"fas fa-user me-1\"></i>\r\n                            Загрузил: <span class=\"text-dark\">{$attachment[\'username\']}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<style>\r\n    .attachment-item {\r\n        transition: all 0.3s ease;\r\n        border: 1px solid #e9ecef;\r\n    }\r\n    \r\n    .attachment-item:hover {\r\n        border-color: #0d6efd;\r\n        box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.1);\r\n        transform: translateY(-2px);\r\n    }\r\n    \r\n    .hover-shadow:hover {\r\n        box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.1);\r\n    }\r\n    \r\n    .hover-primary:hover {\r\n        color: #0d6efd !important;\r\n    }\r\n    \r\n    .transition-all {\r\n        transition: all 0.3s ease;\r\n    }\r\n    \r\n    /* Кастомный стиль для переключателя */\r\n    .form-switch .form-check-input {\r\n        width: 3em;\r\n        height: 1.5em;\r\n        cursor: pointer;\r\n    }\r\n    \r\n    .form-switch .form-check-input:checked {\r\n        background-color: #0d6efd;\r\n        border-color: #0d6efd;\r\n    }\r\n    \r\n    .attachment-icon {\r\n        width: 40px;\r\n        height: 40px;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        background: #f8f9fa;\r\n        border-radius: 8px;\r\n        border: 1px solid #dee2e6;\r\n    }\r\n    \r\n    .additional-info {\r\n        animation: fadeIn 0.3s ease;\r\n    }\r\n    \r\n    @keyframes fadeIn {\r\n        from { opacity: 0; }\r\n        to { opacity: 1; }\r\n    }\r\n    \r\n    @media (max-width: 768px) {\r\n        .attachment-item .row > div {\r\n            margin-bottom: 10px;\r\n        }\r\n        \r\n        .d-flex.justify-content-end {\r\n            justify-content: flex-start !important;\r\n        }\r\n    }\r\n</style>\r\n\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n    // Анимация при клике на переключатель\r\n    document.querySelectorAll(\'.attachment-checkbox\').forEach(checkbox => {\r\n        checkbox.addEventListener(\'change\', function() {\r\n            const item = this.closest(\'.attachment-item\');\r\n            if (this.checked) {\r\n                item.classList.add(\'border-primary\');\r\n                item.style.backgroundColor = \'#f8f9ff\';\r\n            } else {\r\n                item.classList.remove(\'border-primary\');\r\n                item.style.backgroundColor = \'#fff\';\r\n            }\r\n        });\r\n    });\r\n    \r\n    // Показать/скрыть дополнительную информацию\r\n    document.querySelectorAll(\'.attachment-item\').forEach(item => {\r\n        item.addEventListener(\'click\', function(e) {\r\n            if (!e.target.closest(\'.btn\') && !e.target.closest(\'.form-check-input\')) {\r\n                const info = this.querySelector(\'.additional-info\');\r\n                if (info) {\r\n                    info.classList.toggle(\'d-none\');\r\n                }\r\n            }\r\n        });\r\n    });\r\n    \r\n    // Подсветка при наведении на строку\r\n    document.querySelectorAll(\'.attachment-item\').forEach(item => {\r\n        item.addEventListener(\'mouseenter\', function() {\r\n            this.style.cursor = \'pointer\';\r\n        });\r\n    });\r\n});\r\n</script>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1549','usercp_attachments_none','{$lang->no_attachments}','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1550','usercp_avatar','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'change_avatar\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form enctype=\"multipart/form-data\" action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n{$avatar_error}	\r\n	\r\n	\r\n	\r\n	\r\n	<div class=\"card mb-4\">\r\n	<div class=\"card-body\">\r\n	\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'change_avatar\']}</div>\r\n	<div class=\"row g-3 gx-5 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'change_avatar\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			{$avatar_note}\r\n		</div>\r\n		<div class=\"col-auto text-center\">\r\n			{$currentavatar}\r\n		</div>\r\n		</div>\r\n		\r\n		<hr />\r\n		\r\n		{$avatarupload}\r\n		\r\n		\r\n			{$avatar_remote}\r\n\r\n	\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n\r\n			<input type=\"hidden\" name=\"action\" value=\"do_avatar\" />\r\n			<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->usercp[\'change_avatar\']}\"><i class=\"fa-solid fa-image\"></i> &nbsp;{$lang->usercp[\'change_avatar\']}</button>\r\n			{$removeavatar}\r\n			</div>\r\n	</div>\r\n			\r\n			\r\n			\r\n		</div>\r\n</form>\r\n	</div>\r\n	</div>\r\n</div>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1551','usercp_avatar_auto_resize_auto','<div class=\"mt-1\"><i class=\"bi bi-info-circle\"></i> &nbsp;<span class=\"text-muted\" style=\"font-size: 14px\">{$lang->avatar_auto_resize_note}</span></div>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1552','usercp_avatar_auto_resize_user','<div class=\"form-check mt-1\">\r\n  <input class=\"form-check-input\" type=\"checkbox\" name=\"auto_resize\" value=\"1\" checked=\"checked\" id=\"auto_resize\" />\r\n  <label class=\"form-check-label\" for=\"flexCheckDefault\">\r\n    {$lang->avatar_auto_resize_option}\r\n  </label>\r\n</div>','2','1830','','1720609281');
