INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1556','usercp_avatar_upload','	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'custom_avatar\']}</div>\r\n	<div class=\"row gx-5 g-3\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'custom_avatar\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			<div class=\"alert bg-nav mb-0\">\r\n				{$lang->usercp[\'avatar_upload\']}\r\n  <input class=\"form-control form-control-sm border\" name=\"avatarupload\" type=\"file\" id=\"formFile\">\r\n</div>\r\n			{$auto_resize}\r\n		</div>\r\n		\r\n		</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1557','usercp_changename','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'change_username\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n				{$errors}\r\n	\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'change_username\']}</div>\r\n	<div class=\"row gx-5 g-3\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'change_username\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n<div class=\"pb-4 mb-3 border-bottom\">\r\n		<label>{$lang->usercp[\'password_confirmation\']}</label>\r\n		<input type=\"password\" class=\"form-control form-control-sm border\" name=\"password\" />\r\n			</div>\r\n			\r\n		\r\n	\r\n		<label>{$lang->usercp[\'new_username\']}</label>\r\n		<input type=\"text\" class=\"form-control form-control-sm border\" name=\"username\" maxlength=\"{$maxnamelength}\" value=\"{$username}\" />\r\n	\r\n		</div>\r\n		\r\n	</div>\r\n	</div>\r\n		<div class=\"card-footer text-center\">\r\n			<input type=\"hidden\" name=\"action\" value=\"do_changename\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->usercp[\'update_username\']}\"><i class=\"fa-solid fa-user-pen\"></i> &nbsp;{$lang->usercp[\'update_username\']}</button>\r\n		</div>\r\n	</div>\r\n	</form>\r\n	</div>\r\n	</div>\r\n	</div>\r\n		\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1558','usercp_currentavatar','<img class=\"rounded\" src=\"{$useravatar[\'image\']}\" style=\"width: 100px; height: 100px;\" />','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1559','usercp_drafts','<!DOCTYPE html>\r\n<html>\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<title>{$SITENAME} - {$lang->usercp[\'drafts\']}</title>\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n\r\n<style>\r\n.draft-switch {\r\n    position: relative;\r\n    display: inline-block;\r\n    width: 60px;\r\n    height: 30px;\r\n}\r\n.draft-switch input { display:none; }\r\n.draft-slider {\r\n    position:absolute;\r\n    inset:0;\r\n    background:#ccc;\r\n    border-radius:30px;\r\n    cursor:pointer;\r\n    transition:.3s;\r\n}\r\n.draft-slider:before {\r\n    content:\"\";\r\n    position:absolute;\r\n    width:22px;\r\n    height:22px;\r\n    left:4px;\r\n    bottom:4px;\r\n    background:#fff;\r\n    border-radius:50%;\r\n    transition:.3s;\r\n}\r\n.draft-switch input:checked + .draft-slider {\r\n    background:#dc3545;\r\n}\r\n.draft-switch input:checked + .draft-slider:before {\r\n    transform:translateX(28px);\r\n}\r\n\r\n.draft-card {\r\n    border:1px solid #e9ecef;\r\n    border-radius:10px;\r\n    padding:16px;\r\n    margin-bottom:12px;\r\n    transition:.3s;\r\n}\r\n.draft-card.selected {\r\n    border-color:#dc3545;\r\n    background:rgba(220,53,69,.05);\r\n}\r\n</style>\r\n</head>\r\n\r\n<body>\r\n{$header}\r\n\r\n<form action=\"usercp.php\" method=\"post\" id=\"draftsForm\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\">\r\n<input type=\"hidden\" name=\"action\" value=\"do_drafts\">\r\n\r\n<div class=\"container-md py-4\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">{$usercpnav}</div>\r\n\r\n<div class=\"col-lg-9\">\r\n<div class=\"card shadow-sm\">\r\n<div class=\"card-header d-flex justify-content-between align-items-center\">\r\n<h5 class=\"mb-0\">\r\n{$lang->usercp[\'drafts\']} <span class=\"badge bg-secondary\">{$drafts_count}</span>\r\n</h5>\r\n\r\n<div class=\"d-flex align-items-center gap-2\">\r\n<span class=\"small text-muted\">Выбрать все</span>\r\n<label class=\"draft-switch\">\r\n<input type=\"checkbox\" id=\"checkAll\">\r\n<span class=\"draft-slider\"></span>\r\n</label>\r\n</div>\r\n</div>\r\n\r\n<div class=\"card-body\" id=\"draftsList\">\r\n{$drafts}\r\n</div>\r\n\r\n<div class=\"card-footer d-flex justify-content-between align-items-center\">\r\n<div class=\"selected-count d-none\">\r\nВыбрано: <span id=\"selectedCount\">0</span>\r\n</div>\r\n\r\n<button type=\"submit\"\r\n        class=\"btn btn-danger\"\r\n        id=\"deleteButton\"\r\n        name=\"draftman\"\r\n        value=\"{$lang->usercp[\'delete_drafts\']}\"\r\n        disabled>\r\n{$lang->usercp[\'delete_drafts\']}\r\n</button>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</form>\r\n\r\n{$footer}\r\n\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', () => {\r\n\r\nconst checkAll = document.getElementById(\'checkAll\');\r\nconst selectedCountEl = document.getElementById(\'selectedCount\');\r\nconst selectedBox = document.querySelector(\'.selected-count\');\r\nconst deleteBtn = document.getElementById(\'deleteButton\');\r\n\r\nfunction getCheckboxes() {\r\n    return document.querySelectorAll(\'.draft-checkbox\');\r\n}\r\n\r\nfunction updateUI() {\r\n    const boxes = getCheckboxes();\r\n    let checked = 0;\r\n\r\n    boxes.forEach(cb => {\r\n        const card = cb.closest(\'.draft-card\');\r\n        if (cb.checked) {\r\n            checked++;\r\n            card.classList.add(\'selected\');\r\n        } else {\r\n            card.classList.remove(\'selected\');\r\n        }\r\n    });\r\n\r\n    selectedCountEl.textContent = checked;\r\n    selectedBox.classList.toggle(\'d-none\', checked === 0);\r\n    deleteBtn.disabled = checked === 0;\r\n\r\n    checkAll.checked = boxes.length && checked === boxes.length;\r\n    checkAll.indeterminate = checked > 0 && checked < boxes.length;\r\n}\r\n\r\n/* Выбрать все */\r\ncheckAll.addEventListener(\'change\', () => {\r\n    getCheckboxes().forEach(cb => {\r\n        cb.checked = checkAll.checked;\r\n    });\r\n    updateUI();\r\n});\r\n\r\n/* Одиночный выбор */\r\ndocument.addEventListener(\'change\', e => {\r\n    if (e.target.classList.contains(\'draft-checkbox\')) {\r\n        updateUI();\r\n    }\r\n});\r\n\r\n/* Подтверждение удаления */\r\ndocument.getElementById(\'draftsForm\').addEventListener(\'submit\', e => {\r\n    if (!document.querySelectorAll(\'.draft-checkbox:checked\').length) {\r\n        e.preventDefault();\r\n        alert(\'Выберите хотя бы один черновик\');\r\n    }\r\n});\r\n\r\n});\r\n</script>\r\n\r\n</body>\r\n</html>\r\n','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1560','usercp_drafts_draft',' <div class=\"draft-card border rounded-3 p-3 mb-3 bg-white hover-lift transition-all\">\r\n    <div class=\"row align-items-center g-3\">\r\n        <!-- Draft Information -->\r\n        <div class=\"col-lg-7 col-md-6\">\r\n            <div class=\"d-flex align-items-start gap-3\">\r\n                <!-- Delete Toggle -->\r\n                <div class=\"form-check form-switch mt-1\">\r\n                    <input type=\"checkbox\" \r\n                           class=\"form-check-input draft-checkbox\" \r\n                           name=\"deletedraft[{$id}]\" \r\n                           value=\"{$type}\" \r\n                           id=\"draft_{$id}\">\r\n                    <label class=\"form-check-label\" for=\"draft_{$id}\"></label>\r\n                </div>\r\n                \r\n                <!-- Draft Content -->\r\n                <div class=\"draft-content flex-grow-1\">\r\n                    <h6 class=\"mb-2\">\r\n                        <a href=\"{$editurl}\" class=\"text-decoration-none text-dark hover-primary fw-semibold\">\r\n                            <i class=\"fas fa-file-alt me-2 text-primary\"></i>\r\n                            {$draft[\'subject\']}\r\n                        </a>\r\n                    </h6>\r\n                    \r\n                    <div class=\"draft-preview mb-2 text-muted small\">\r\n                        <i class=\"fas fa-align-left me-1\"></i>\r\n                        {$detail}\r\n                    </div>\r\n                    \r\n                    <!-- Quick Labels -->\r\n                    <div class=\"d-flex flex-wrap gap-2\">\r\n                        <span class=\"badge bg-light text-dark border\">\r\n                            <i class=\"fas fa-comments me-1\"></i>\r\n                            Draft\r\n                        </span>\r\n                        <span class=\"badge bg-info bg-opacity-10 text-info border border-info\">\r\n                            <i class=\"fas fa-save me-1\"></i>\r\n                            Auto-save\r\n                        </span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Save Date -->\r\n        <div class=\"col-lg-3 col-md-3\">\r\n            <div class=\"draft-date text-center text-md-start\">\r\n                <div class=\"text-muted small mb-1\">\r\n                    <i class=\"far fa-calendar me-1\"></i>\r\n                    Save Date\r\n                </div>\r\n                <div class=\"fw-medium\">\r\n                    <i class=\"far fa-clock me-1 text-secondary\"></i>\r\n                    {$savedate}\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Draft Actions -->\r\n        <div class=\"col-lg-2 col-md-3\">\r\n            <div class=\"d-flex flex-column flex-md-row align-items-center justify-content-end gap-2\">\r\n                <!-- Edit Button -->\r\n                <a href=\"{$editurl}\" \r\n                   class=\"btn btn-sm btn-primary w-100 w-md-auto\" \r\n                   title=\"{$lang->usercp[\'edit_draft\']}\">\r\n                    <i class=\"fas fa-edit me-1\"></i>\r\n                    Edit\r\n                </a>\r\n                \r\n                <!-- Quick Delete Button -->\r\n                <button type=\"button\" \r\n                        class=\"btn btn-sm btn-outline-danger delete-single-draft\" \r\n                        data-draft-id=\"{$id}\"\r\n                        title=\"Delete Draft\">\r\n                    <i class=\"fas fa-trash-alt\"></i>\r\n                </button>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<style>\r\n    /* Draft Element Styles */\r\n    .draft-card {\r\n        border: 1px solid #e9ecef;\r\n        transition: all 0.3s ease;\r\n    }\r\n    \r\n    .draft-card:hover {\r\n        border-color: #dc3545;\r\n        box-shadow: 0 4px 12px rgba(220, 53, 69, 0.1);\r\n    }\r\n    \r\n    .draft-card.selected {\r\n        border-color: #dc3545;\r\n        background-color: rgba(220, 53, 69, 0.05);\r\n    }\r\n    \r\n    .hover-lift:hover {\r\n        transform: translateY(-2px);\r\n    }\r\n    \r\n    .transition-all {\r\n        transition: all 0.3s ease;\r\n    }\r\n    \r\n    .hover-primary:hover {\r\n        color: #0d6efd !important;\r\n    }\r\n    \r\n    /* Toggle Switch Styles */\r\n    .form-switch .form-check-input {\r\n        width: 3em;\r\n        height: 1.5em;\r\n        cursor: pointer;\r\n        border-color: #adb5bd;\r\n    }\r\n    \r\n    .form-switch .form-check-input:checked {\r\n        background-color: #dc3545;\r\n        border-color: #dc3545;\r\n    }\r\n    \r\n    .form-switch .form-check-input:focus {\r\n        box-shadow: 0 0 0 0.25rem rgba(220, 53, 69, 0.25);\r\n    }\r\n    \r\n    /* Text Preview Styles */\r\n    .draft-preview {\r\n        max-height: 48px;\r\n        overflow: hidden;\r\n        text-overflow: ellipsis;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 2;\r\n        -webkit-box-orient: vertical;\r\n        line-height: 1.4;\r\n    }\r\n    \r\n    /* Animations */\r\n    .additional-info {\r\n        animation: slideDown 0.3s ease;\r\n    }\r\n    \r\n    @keyframes slideDown {\r\n        from {\r\n            opacity: 0;\r\n            transform: translateY(-10px);\r\n        }\r\n        to {\r\n            opacity: 1;\r\n            transform: translateY(0);\r\n        }\r\n    }\r\n</style>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1561','usercp_drafts_none','{$lang->usercp[\'no_drafts\']}','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1562','usercp_editlists','<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <title>{$SITENAME} - {$lang->usercp[\'edit_lists\']}</title>\r\n    \r\n    <script type=\"text/javascript\" src=\"{$BASEURL}/scripts/usercp.js?ver=1827\"></script>\r\n    <script type=\"text/javascript\">\r\n        lang.remove_buddy = \'{$lang->usercp[\'confirm_remove_buddy\']}\';\r\n        lang.remove_ignored = \'{$lang->usercp[\'confirm_remove_ignored\']}\';\r\n        lang.adding_buddy = \'{$lang->usercp[\'adding_buddy\']}\';\r\n        lang.adding_ignored = \'{$lang->usercp[\'adding_ignored\']}\';\r\n        lang.buddylist_error = \'{$lang->usercp[\'buddylist_error\']}\';\r\n    </script>\r\n\r\n  \r\n \r\n    \r\n    <style>\r\n        :root {\r\n            --primary-color: #3498db;\r\n            --secondary-color: #2c3e50;\r\n            --success-color: #2ecc71;\r\n            --danger-color: #e74c3c;\r\n            --light-bg: #f8f9fa;\r\n            --border-color: #dee2e6;\r\n        }\r\n        \r\n        \r\n        \r\n        \r\n        \r\n        .section-title {\r\n            font-size: 1.1rem;\r\n            font-weight: 600;\r\n            color: var(--secondary-color);\r\n            margin-bottom: 15px;\r\n            padding-bottom: 10px;\r\n            border-bottom: 1px solid var(--border-color);\r\n        }\r\n        \r\n        .form-label {\r\n            font-weight: 500;\r\n            margin-bottom: 8px;\r\n            color: #444;\r\n        }\r\n        \r\n        .help-text {\r\n            font-size: 0.85rem;\r\n            color: #6c757d;\r\n            margin-top: 5px;\r\n        }\r\n        \r\n        .btn-primary {\r\n            background-color: var(--primary-color);\r\n            border: none;\r\n            padding: 8px 18px;\r\n            font-weight: 500;\r\n        }\r\n        \r\n        .btn-primary:hover {\r\n            background-color: #2980b9;\r\n        }\r\n        \r\n        .btn-success {\r\n            background-color: var(--success-color);\r\n            border: none;\r\n            padding: 8px 18px;\r\n            font-weight: 500;\r\n        }\r\n        \r\n        .btn-danger {\r\n            background-color: var(--danger-color);\r\n            border: none;\r\n            padding: 8px 18px;\r\n            font-weight: 500;\r\n        }\r\n        \r\n        .empty-state {\r\n            text-align: center;\r\n            padding: 30px;\r\n            color: #6c757d;\r\n        }\r\n        \r\n        .empty-state i {\r\n            font-size: 3rem;\r\n            margin-bottom: 15px;\r\n            color: #ced4da;\r\n        }\r\n        \r\n        .select2-user-result {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 8px;\r\n            padding: 6px 12px;\r\n        }\r\n        \r\n        .select2-user-selection {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 6px;\r\n        }\r\n        \r\n        .select2-user-avatar {\r\n            width: 24px;\r\n            height: 24px;\r\n            border-radius: 50%;\r\n            object-fit: cover;\r\n        }\r\n        \r\n        .select2-user-avatar-sm {\r\n            width: 18px;\r\n            height: 18px;\r\n            border-radius: 50%;\r\n            object-fit: cover;\r\n        }\r\n        \r\n        .select2-user-name {\r\n            font-weight: 500;\r\n        }\r\n        \r\n        .select2-container--default .select2-selection--multiple {\r\n            min-height: 42px;\r\n            border: 1px solid #dcdfe6;\r\n            border-radius: 6px;\r\n            transition: all 0.2s ease;\r\n        }\r\n        \r\n        .select2-container--default.select2-container--focus .select2-selection--multiple {\r\n            border-color: var(--primary-color);\r\n            box-shadow: 0 0 0 2px rgba(52, 152, 219, 0.2);\r\n        }\r\n        \r\n        .select2-container--default .select2-selection--multiple .select2-selection__choice {\r\n            background-color: #409eff;\r\n            border-color: #409eff;\r\n            color: white;\r\n            border-radius: 4px;\r\n            padding: 2px 8px;\r\n            font-size: 13px;\r\n        }\r\n        \r\n        .select2-container--default .select2-selection--multiple .select2-selection__choice__remove {\r\n            color: white;\r\n            margin-right: 4px;\r\n        }\r\n        \r\n        .user-list-container {\r\n            margin-top: 20px;\r\n        }\r\n        \r\n        .user-item {\r\n            display: flex;\r\n            justify-content: space-between;\r\n            align-items: center;\r\n            padding: 12px 15px;\r\n            border-bottom: 1px solid var(--border-color);\r\n            transition: background-color 0.2s;\r\n        }\r\n        \r\n        .user-item:hover {\r\n            background-color: #f8f9fa;\r\n        }\r\n        \r\n        .user-item:last-child {\r\n            border-bottom: none;\r\n        }\r\n        \r\n     \r\n        \r\n        /* Улучшения для мобильной версии */\r\n        .bg-nav {\r\n            background-color: var(--secondary-color);\r\n            color: white;\r\n        }\r\n        \r\n        .input-group {\r\n            display: flex;\r\n            flex-direction: column;\r\n            gap: 10px;\r\n        }\r\n        \r\n        @media (min-width: 992px) {\r\n            .input-group {\r\n                flex-direction: row;\r\n                align-items: end;\r\n            }\r\n            \r\n            .input-group .form-control {\r\n                flex: 1;\r\n            }\r\n        }\r\n        \r\n        /* Стили для ограниченного placeholder */\r\n        .select2-selection__placeholder {\r\n            max-width: 180px;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n            white-space: nowrap;\r\n            display: block;\r\n            color: #6c757d;\r\n            font-size: 0.875rem;\r\n        }\r\n\r\n        .select2-container--default .select2-selection--multiple .select2-selection__placeholder {\r\n            margin-left: 8px;\r\n            margin-top: 5px;\r\n        }\r\n\r\n        /* Для поля поиска внутри select2 */\r\n        .select2-search__field::placeholder {\r\n            font-size: 0.875rem;\r\n            color: #6c757d;\r\n            max-width: 120px;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    \r\n    <form action=\"usercp.php\" method=\"post\" id=\"buddy\" onsubmit=\"return UserCP.addBuddy(\'buddy\');\">\r\n        <input type=\"hidden\" name=\"action\" value=\"do_editlists\" />\r\n        <input type=\"hidden\" name=\"manage\" value=\"buddy\" />\r\n        <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n        \r\n        <div class=\"container-md\">\r\n            <div class=\"row\">\r\n                <div class=\"col-lg-3\">\r\n                    {$usercpnav}\r\n                </div>\r\n                <div class=\"col\">    \r\n                    \r\n                    <div class=\"card mb-4\">\r\n                        <div class=\"card-header\">\r\n                            <i class=\"fas fa-user-friends me-2\"></i> {$lang->usercp[\'edit_buddy_list\']}\r\n                        </div>\r\n                        <div class=\"card-body\">\r\n                            \r\n                            <div class=\"mb-4\">\r\n                                <div class=\"section-title\">{$lang->usercp[\'add_buddies\']}</div>\r\n                                <div class=\"mb-3\">\r\n                                    <label class=\"form-label\">{$lang->usercp[\'username_or_usernames\']}</label>\r\n                                    <div class=\"help-text\">{$lang->usercp[\'add_buddies_desc\']}</div>\r\n                                    <div class=\"user-select\" id=\"buddy_add_username\"></div>\r\n<input type=\"hidden\" name=\"add_username\" id=\"buddy_add_username_input\">\r\n\r\n                                </div>\r\n                                <div class=\"d-flex justify-content-between align-items-center\">\r\n                                    <button type=\"button\" class=\"btn btn-primary\" id=\"buddy_search_btn\">\r\n                                        <i class=\"fas fa-search me-1\"></i> {$lang->usercp[\'search_user\']}\r\n                                    </button>\r\n                                    <button type=\"submit\" id=\"buddy_submit\" class=\"btn btn-success\">\r\n                                        <i class=\"fas fa-user-plus me-1\"></i> {$lang->usercp[\'add_to_buddies\']}\r\n                                    </button>\r\n                                </div>\r\n                            </div>\r\n                            \r\n                            <div class=\"user-list-container\">\r\n                                <div class=\"section-title\">{$current_buddies}</div>\r\n                                {$buddy_list}\r\n                            </div>\r\n                            \r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </form>\r\n    \r\n    <form action=\"usercp.php\" method=\"post\" id=\"ignored\" onsubmit=\"return UserCP.addBuddy(\'ignored\');\">\r\n        <input type=\"hidden\" name=\"action\" value=\"do_editlists\" />\r\n        <input type=\"hidden\" name=\"manage\" value=\"ignored\" />\r\n        <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n        \r\n        \r\n		<div class=\"container mt-3\">\r\n		<div class=\"card mb-4\">\r\n            <div class=\"card-header\">\r\n                <i class=\"fas fa-user-slash me-2\"></i> {$lang->usercp[\'edit_ignore_list\']}\r\n            </div>\r\n            <div class=\"card-body\">\r\n                \r\n                <div class=\"mb-4\">\r\n                    <div class=\"section-title\">{$lang->usercp[\'add_ignored_users\']}</div>\r\n                    <div class=\"mb-3\">\r\n                        <label class=\"form-label\">{$lang->usercp[\'username_or_usernames\']}</label>\r\n                        <div class=\"help-text\">{$lang->usercp[\'add_ignored_users_desc\']}</div>\r\n                        <div class=\"user-select\" id=\"ignored_add_username\"></div>\r\n<input type=\"hidden\" name=\"add_username\" id=\"ignored_add_username_input\">\r\n\r\n                    </div>\r\n                    <div class=\"d-flex justify-content-between align-items-center\">\r\n                        <button type=\"button\" class=\"btn btn-primary\" id=\"ignored_search_btn\">\r\n                            <i class=\"fas fa-search me-1\"></i> {$lang->usercp[\'search_user\']}\r\n                        </button>\r\n                        <button type=\"submit\" id=\"ignored_submit\" class=\"btn btn-danger\">\r\n                            <i class=\"fas fa-ban me-1\"></i> {$lang->usercp[\'ignore_users\']}\r\n                        </button>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"user-list-container\">\r\n                    <div class=\"section-title\">{$current_ignored_users}</div>\r\n                    {$ignore_list}\r\n                </div>\r\n                \r\n            </div>\r\n        </div>\r\n		 </div>\r\n    </form>\r\n    \r\n    <div class=\"container mt-3\">\r\n	{$received_requests}\r\n    {$sent_requests}\r\n	</div>\r\n    \r\n	\r\n\r\n	\r\n    <style>\r\n.user-select {\r\n    border: 1px solid #dcdfe6;\r\n    border-radius: 6px;\r\n    padding: 6px;\r\n    min-height: 42px;\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    gap: 6px;\r\n    cursor: text;\r\n    position: relative;\r\n}\r\n\r\n.user-select input {\r\n    border: none;\r\n    outline: none;\r\n    flex: 1;\r\n    min-width: 120px;\r\n}\r\n\r\n.user-tag {\r\n    background: #409eff;\r\n    color: #fff;\r\n    padding: 3px 8px;\r\n    border-radius: 4px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 6px;\r\n    font-size: 13px;\r\n}\r\n\r\n.user-tag img {\r\n    width: 18px;\r\n    height: 18px;\r\n    border-radius: 50%;\r\n}\r\n\r\n.user-tag span {\r\n    cursor: pointer;\r\n    font-weight: bold;\r\n}\r\n\r\n.user-dropdown {\r\n    position: absolute;\r\n    top: 100%;\r\n    left: 0;\r\n    right: 0;\r\n    background: #fff;\r\n    border: 1px solid #dcdfe6;\r\n    max-height: 220px;\r\n    overflow-y: auto;\r\n    z-index: 10;\r\n}\r\n\r\n.user-option {\r\n    padding: 8px 10px;\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 8px;\r\n    cursor: pointer;\r\n}\r\n\r\n.user-option:hover {\r\n    background: #f5f7fa;\r\n}\r\n\r\n.user-option img {\r\n    width: 24px;\r\n    height: 24px;\r\n    border-radius: 50%;\r\n}\r\n</style>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
