INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1566','usercp_editlists_received_request','<div class=\"mb-2 pb-3 border-bottom\">\r\n<div class=\"row\">\r\n	<div class=\"col-auto\">\r\n		{$request[\'username\']}\r\n	</div>\r\n	<div class=\"col-auto text-desc\">\r\n		{$request[\'date\']}\r\n	</div>\r\n	<div class=\"col text-end\">\r\n		<a href=\"{$BASEURL}/usercp.php?action=acceptrequest&amp;id={$request[\'id\']}&amp;my_post_key={$mybb->post_code}\" class=\"links\"><i class=\"fa-solid fa-check\"></i> {$lang->usercp[\'accept\']}</a> &nbsp;&nbsp;&nbsp; <a href=\"{$BASEURL}/usercp.php?action=declinerequest&amp;id={$request[\'id\']}&amp;my_post_key={$mybb->post_code}\" class=\"links\"><i class=\"fa-solid fa-xmark\"></i> {$lang->usercp[\'decline\']}</a>\r\n	</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1567','usercp_editlists_received_requests','<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$lang->usercp[\'buddyrequests_received\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		\r\n		{$received_rows}\r\n		\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1568','usercp_editlists_sent_request','<div class=\"mb-2 pb-3 border-bottom\">\r\n<div class=\"row\">\r\n	<div class=\"col-auto\">\r\n		{$request[\'username\']}\r\n	</div>\r\n	<div class=\"col-auto text-desc\">\r\n		{$request[\'date\']}\r\n	</div>\r\n	<div class=\"col text-end\">\r\n		<a href=\"{$BASEURL}/usercp.php?action=cancelrequest&amp;id={$request[\'id\']}&amp;my_post_key={$mybb->post_code}\" class=\"links\"><i class=\"fa-solid fa-xmark\"></i> {$lang->usercp[\'cancel\']}</a>\r\n	</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1569','usercp_editlists_sent_requests','<div class=\"card\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n	    {$lang->usercp[\'buddyrequests_sent\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		\r\n		{$sent_rows}\r\n		\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1570','usercp_editlists_user','<div class=\"row border-bottom pb-2 mb-2\">\r\n	<div class=\"col\">\r\n		{$profile_link}\r\n	</div>\r\n	<div class=\"col text-end\">\r\n		<a href=\"usercp.php?action=do_editlists&amp;my_post_key={$mybb->post_code}&amp;manage={$type}&amp;delete={$user[\'id\']}\" onclick=\"return UserCP.removeBuddy(\'{$type}\', {$user[\'id\']});\" title=\"{$lang->usercp[\'remove_from_list\']}\"><i class=\"fa-solid fa-user-xmark text-danger\" title=\"{$lang->usercp[\'remove_from_list\']}\"></i></a>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1571','usercp_editsig','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'edit_sig\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n\r\n\r\n<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n\r\n{$error}\r\n	{$signature}\r\n	\r\n	\r\n<div class=\"card\">\r\n\r\n{$editor[\'toolbar\']}\r\n\r\n	<div class=\"card-body\">\r\n\r\n\r\n\r\n<textarea style=\"height: 300px; width: 100%\" class=\"form-control form-control-sm border\" id=\"signature\" name=\"signature\">{$sig}</textarea>\r\n\r\n	\r\n		<div class=\"mt-3\"></div>\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'edit_sig\']}</div>\r\n	<div class=\"row gx-5 g-3\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'edit_sig\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			\r\n<div class=\"form-check text-14\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"updateposts\" value=\"enable\" />\r\n  <label class=\"form-check-label\" for=\"flexRadioDefault1\">\r\n    {$lang->usercp[\'enable_sig_posts\']}\r\n  </label>\r\n</div>\r\n	<div class=\"form-check text-14\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"updateposts\" value=\"disable\" />\r\n  <label class=\"form-check-label\" for=\"flexRadioDefault1\">\r\n    {$lang->usercp[\'disable_sig_posts\']}\r\n  </label>\r\n</div>\r\n		<div class=\"form-check text-14\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"updateposts\" value=\"0\" checked=\"checked\" />\r\n  <label class=\"form-check-label\" for=\"flexRadioDefault1\">\r\n    {$lang->usercp[\'leave_sig_settings\']}\r\n  </label>\r\n</div>\r\n			\r\n			\r\n		</div>\r\n		\r\n		</div>\r\n	\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n\r\n<input type=\"hidden\" name=\"action\" value=\"do_editsig\" />\r\n		<button type=\"submit\" class=\"btn btn-primary\" name=\"preview\" value=\"{$lang->usercp[\'preview\']}\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;{$lang->usercp[\'preview\']}</button>&nbsp;\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->usercp[\'update_sig\']}\"><i class=\"fa-solid fa-signature\"></i> &nbsp;{$lang->usercp[\'update_sig\']}</button>\r\n</div>\r\n	</div></div>\r\n	</div></div>\r\n	</div>\r\n</form>\r\n\r\n{$editor[\'modal\']}\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1572','usercp_editsig_current','<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n		{$lang->usercp[\'current_sig\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		{$sigpreview}\r\n			</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1573','usercp_editsig_preview','		<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n		{$lang->usercp[\'sig_preview\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		{$sigpreview}\r\n			</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1574','usercp_editsig_suspended','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->userc[\'edit_sig\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<div class=\"container\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n{$signature}				\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n	{$lang->usercp[\'edit_sig_error_title\']}</div>\r\n	<ul>\r\n		<li>{$lang->usercp[\'edit_sig_no_permission\']}</li>\r\n	</ul>\r\n	</div>\r\n	</div></div>\r\n	</div></div>\r\n\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1575','usercp_email','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'change_email\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n\r\n{$errors}				\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n			<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'change_email\']}</div>\r\n	<div class=\"row gx-5 g-3\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'change_email\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n<div class=\"pb-4 mb-3 border-bottom\">\r\n				<label>{$lang->usercp[\'current_password\']}</label>\r\n				<input type=\"password\" class=\"form-control form-control-sm border\" name=\"password\" />\r\n			</div>\r\n		\r\n			<div class=\"pb-4 mb-3 border-bottom\">\r\n				<label>{$lang->usercp[\'new_email\']}</label>\r\n				<input type=\"text\" class=\"form-control form-control-sm border\" name=\"email\" maxlength=\"150\" value=\"{$email}\" />\r\n			</div>\r\n		\r\n			\r\n			\r\n				<label>{$lang->usercp[\'confirm_email\']}</label>\r\n				<input type=\"text\" class=\"form-control form-control-sm border\" name=\"email2\" maxlength=\"150\" value=\"{$email2}\" />\r\n			\r\n		</div>\r\n		\r\n		</div>\r\n\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n		<input type=\"hidden\" name=\"action\" value=\"do_email\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->usercp[\'update_email\']}\"><i class=\"fa-solid fa-at\"></i> &nbsp;{$lang->usercp[\'update_email\']}</button>\r\n	</div>\r\n	</div>\r\n	</form>\r\n	</div>\r\n	</div>\r\n	</div>\r\n\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1576','usercp_forumsubscriptions','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'forum_subscriptions\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n\r\n	<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n			\r\n\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		{$lang->usercp[\'forum_subscriptions\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		{$forums}\r\n	</div>\r\n	</div>\r\n	</div>\r\n		</div>\r\n	</div>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1577','usercp_forumsubscriptions_forum','<div class=\"row py-2 border-bottom\">\r\n	<div class=\"col-lg-7 align-self-center\">\r\n		<h6 class=\"mb-0\"><a href=\"{$forum_url}\">{$forum[\'name\']}</a></h6>\r\n	<a class=\"text-danger\" href=\"usercp.php?action=removesubscription&amp;type=forum&amp;fid={$forum[\'fid\']}&amp;my_post_key={$mybb->post_code}\">{$lang->usercp[\'unsubscribe\']}</a>\r\n	</div>\r\n	<div class=\"col-lg-2 align-self-center small\">\r\n		{$lang->usercp[\'threads\']} {$threads}<br />\r\n		{$lang->usercp[\'posts\']} {$posts}\r\n	</div>\r\n	<div class=\"col-lg-3\">\r\n		{$lastpost}\r\n	</div>\r\n</div>','2','1837','','1720609281');
