INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1605','usercp_password','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'change_password\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n	\r\n				{$errors}\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	\r\n			<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'change_password\']}</div>\r\n	<div class=\"row gx-5 g-3\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'change_password\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n				<div class=\"pb-4 mb-3 border-bottom\">\r\n				<label for=\"confirm\">{$lang->usercp[\'current_password\']}</label>\r\n				<input type=\"password\" class=\"form-control form-control-sm border\" name=\"oldpassword\" />\r\n			</div>\r\n\r\n			\r\n			<div class=\"pb-4 mb-3 border-bottom\">\r\n				<label for=\"confirm\">{$lang->usercp[\'new_password\']}</label>\r\n				<input type=\"password\" class=\"form-control form-control-sm border\" name=\"password\" />\r\n			</div>\r\n\r\n			\r\n			\r\n				<label for=\"confirm\">{$lang->usercp[\'confirm_password\']}</label>\r\n				<input type=\"password\" class=\"form-control form-control-sm border\" name=\"password2\" />\r\n			\r\n		</div>\r\n		\r\n		</div>\r\n	\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n		<input type=\"hidden\" name=\"action\" value=\"do_password\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->usercp[\'update_password\']}\"><i class=\"fa-solid fa-key\"></i> &nbsp;{$lang->usercp[\'update_password\']}</button>\r\n	</div>\r\n	</div>\r\n	</form>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1606','usercp_profile','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->usercp[\'edit_profile\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	\r\n	\r\n<form action=\"usercp.php\" method=\"post\" name=\"input\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n			</div>\r\n			<div class=\"col\">\r\n				{$errors}\r\n				\r\n				<div class=\"card\">\r\n<div class=\"card-body\">\r\n\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'birthday\']}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'birthday\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			<div class=\"alert bg-nav mb-0\">\r\n				<div class=\"row g-1\">\r\n					<div class=\"col-auto\">\r\n						<span class=\"small text-desc\">{$lang->usercp[\'day\']}</span>\r\n<select name=\"bday1\" class=\"form-select form-select-sm border pe-5\">\r\n<option value=\"\">&nbsp;</option>\r\n{$bdaydaysel}\r\n</select>\r\n					</div>\r\n					<div class=\"col-auto\">\r\n						<span class=\"small text-desc\">{$lang->usercp[\'month\']}</span>\r\n<select name=\"bday2\" class=\"form-select form-select-sm border pe-5\">\r\n<option value=\"\">&nbsp;</option>\r\n<option value=\"1\" {$bdaymonthsel[\'1\']}>{$lang->usercp[\'month_1\']}</option>\r\n<option value=\"2\" {$bdaymonthsel[\'2\']}>{$lang->usercp[\'month_2\']}</option>\r\n<option value=\"3\" {$bdaymonthsel[\'3\']}>{$lang->usercp[\'month_3\']}</option>\r\n<option value=\"4\" {$bdaymonthsel[\'4\']}>{$lang->usercp[\'month_4\']}</option>\r\n<option value=\"5\" {$bdaymonthsel[\'5\']}>{$lang->usercp[\'month_5\']}</option>\r\n<option value=\"6\" {$bdaymonthsel[\'6\']}>{$lang->usercp[\'month_6\']}</option>\r\n<option value=\"7\" {$bdaymonthsel[\'7\']}>{$lang->usercp[\'month_7\']}</option>\r\n<option value=\"8\" {$bdaymonthsel[\'8\']}>{$lang->usercp[\'month_8\']}</option>\r\n<option value=\"9\" {$bdaymonthsel[\'9\']}>{$lang->usercp[\'month_9\']}</option>\r\n<option value=\"10\" {$bdaymonthsel[\'10\']}>{$lang->usercp[\'month_10\']}</option>\r\n<option value=\"11\" {$bdaymonthsel[\'11\']}>{$lang->usercp[\'month_11\']}</option>\r\n<option value=\"12\" {$bdaymonthsel[\'12\']}>{$lang->usercp[\'month_12\']}</option>\r\n</select>\r\n					</div>\r\n					<div class=\"col-auto\">\r\n						<span class=\"small text-desc\">{$lang->usercp[\'year\']}</span>\r\n						<input type=\"text\" class=\"form-control form-control-sm border w-auto\" size=\"5\" maxlength=\"4\" name=\"bday3\" value=\"{$bday[\'2\']}\" />\r\n					</div>\r\n				</div>\r\n			\r\n			\r\n			\r\n			\r\n			\r\n			</div>\r\n	<hr />\r\n			\r\n				\r\n					<label for=\"birthyear\">{$lang->usercp[\'birthdayprivacy\']}</label>\r\n									<select name=\"birthdayprivacy\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n<option value=\"all\"{$allselected}>{$lang->usercp[\'birthdayprivacyall\']}</option>\r\n<option value=\"none\"{$noneselected}>{$lang->usercp[\'birthdayprivacynone\']}</option>\r\n<option value=\"age\"{$ageselected}>{$lang->usercp[\'birthdayprivacyage\']}</option>\r\n</select>\r\n		</div></div><!-- row -->\r\n\r\n<!-- Секретный вопрос для восстановления пароля -->\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n    <div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n        {$lang->usercp[\'e_pass8\']}\r\n    </div>\r\n    <div class=\"col\">\r\n        <p class=\"text-muted small mb-3\">{$lang->usercp[\'e_pass9\']}</p>\r\n        \r\n        <div class=\"mb-3\">\r\n            <label class=\"form-label small fw-bold\">{$lang->usercp[\'e_pass10\']}</label>\r\n            <select name=\"passhint\" class=\"form-select form-select-sm\">\r\n                {$secret_questions_options}\r\n            </select>\r\n        </div>\r\n        \r\n        <div class=\"mb-3\">\r\n            <label class=\"form-label small fw-bold\">{$lang->usercp[\'e_pass11\']}</label>\r\n            <input type=\"text\" class=\"form-control form-control-sm\" name=\"hintanswer\" \r\n       value=\"{$hintanswer_value}\" \r\n       placeholder=\"{$lang->usercp[\'e_pass11\']}\">\r\n        </div>\r\n    </div>\r\n</div>\r\n<!-- Конец секретного вопроса -->\r\n\r\n{$website}\r\n{$customfields}\r\n{$customtitle}\r\n{$contactfields}\r\n{$awaysection}\r\n\r\n					\r\n<div class=\"card-footer text-center\">\r\n<input type=\"hidden\" name=\"action\" value=\"do_profile\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"regsubmit\" value=\"{$lang->usercp[\'update_profile\']}\"><i class=\"fa-solid fa-user\"></i> &nbsp;{$lang->usercp[\'update_profile\']}</button>\r\n</div>\r\n					</div>\r\n</form>\r\n\r\n	</div>\r\n	</div>\r\n	</div>\r\n\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1607','usercp_profile_away','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->away_information}</div>\r\n	<div class=\"row g-3 m-auto pb-0 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->away_information}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n			<div class=\"mb-3 pb-4 border-bottom\">\r\n				<label>{$lang->away_status}</label><br />\r\n				\r\n            <div class=\"radio-toolbar\">\r\n  <input type=\"radio\" name=\"away\" id=\"away_1\" value=\"1\" {$awaycheck[\'1\']} />\r\n  <label for=\"away_1\">{$lang->im_away}</label>\r\n\r\n\r\n  <input type=\"radio\" name=\"away\" id=\"away_2\" value=\"0\" {$awaycheck[\'0\']} />\r\n  <label for=\"away_2\">{$lang->im_here}</label>\r\n			</div>\r\n			</div>\r\n			\r\n			<div class=\"mb-3 pb-4 border-bottom\">\r\n			<div class=\"form-group\">\r\n			<label for=\"reason\">{$lang->away_reason}</label>\r\n			<input type=\"text\" class=\"form-control form-control-sm border\" name=\"awayreason\" value=\"{$user[\'awayreason\']}\" maxlength=\"200\" />\r\n				</div></div>\r\n		\r\n			<label>{$lang->return_date}</label>\r\n	<div class=\"alert bg-nav mb-0\">\r\n		\r\n		<div class=\"row g-1\">\r\n			<div class=\"col-auto\">\r\n				<span class=\"small text-desc\">{$lang->day}</span>\r\n			<select name=\"awayday\" class=\"form-select form-select-sm border pe-5\">\r\n<option value=\"\">&nbsp;</option>\r\n{$returndatesel}\r\n</select>\r\n			</div>\r\n	\r\n		<div class=\"col-auto\">\r\n			<span class=\"small text-desc\">{$lang->month}</span>\r\n			<select name=\"awaymonth\" class=\"form-select form-select-sm border pe-5\">\r\n<option value=\"\">&nbsp;</option>\r\n<option value=\"1\" {$returndatemonthsel[\'1\']}>{$lang->month_1}</option>\r\n<option value=\"2\" {$returndatemonthsel[\'2\']}>{$lang->month_2}</option>\r\n<option value=\"3\" {$returndatemonthsel[\'3\']}>{$lang->month_3}</option>\r\n<option value=\"4\" {$returndatemonthsel[\'4\']}>{$lang->month_4}</option>\r\n<option value=\"5\" {$returndatemonthsel[\'5\']}>{$lang->month_5}</option>\r\n<option value=\"6\" {$returndatemonthsel[\'6\']}>{$lang->month_6}</option>\r\n<option value=\"7\" {$returndatemonthsel[\'7\']}>{$lang->month_7}</option>\r\n<option value=\"8\" {$returndatemonthsel[\'8\']}>{$lang->month_8}</option>\r\n<option value=\"9\" {$returndatemonthsel[\'9\']}>{$lang->month_9}</option>\r\n<option value=\"10\" {$returndatemonthsel[\'10\']}>{$lang->month_10}</option>\r\n<option value=\"11\" {$returndatemonthsel[\'11\']}>{$lang->month_11}</option>\r\n<option value=\"12\" {$returndatemonthsel[\'12\']}>{$lang->month_12}</option>\r\n</select>\r\n			</div>\r\n			\r\n	<div class=\"col-auto\">\r\n		<span class=\"small text-desc\">{$lang->year}</span>\r\n		<input type=\"text\" class=\"form-control form-control-sm border\" size=\"4\" maxlength=\"4\" name=\"awayyear\" value=\"{$returndate[\'2\']}\" />\r\n	</div>\r\n	</div>\r\n\r\n			</div>\r\n		</div>\r\n			\r\n\r\n		</div>\r\n		</div> <!-- end bit -->','2','1837','','1720609281');
