INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1614','usercp_profile_profilefields','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->modcp[\'additional_information\']}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->modcp[\'additional_information\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n		{$customfields}\r\n		\r\n		</div></div>','2','1837','','1720609281');
