INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1617','usercp_profile_profilefields_radio','<div class=\"form-check\">\r\n  <input type=\"radio\" class=\"form-check-input\" name=\"profile_fields[$field]\" value=\"{$val}\"{$checked} />\r\n  <label class=\"form-check-label\" for=\"exampleRadios1\">\r\n    {$val}\r\n  </label>\r\n</div>','2','1830','','1720609281');
