INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('3070','comment_edit','<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n<div class=\"dropdown\"><a class=\"postlinks\" aria-expanded=\"false\" data-bs-toggle=\"dropdown\" type=\"button\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;{$lang->global[\'postbit_button_edit\']}</a>\r\n    <div class=\"dropdown-menu border\">\r\n<a href=\"javascript:void(0)\" class=\"popup_item quick_edit_button dropdown-item\" id=\"quick_edit_post_{$pid}\"><i class=\"fa-solid fa-clock\"></i> &nbsp;{$lang->global[\'postbit_quick_edit\']}</a>\r\n	<a href=\"comment.php?action=edit&amp;pid={$pid}\" class=\"dropdown-item\"><i class=\"fa-solid fa-pen-to-square\"></i> &nbsp;{$lang->global[\'postbit_full_edit\']}</a>\r\n</div>\r\n</div>\r\n\r\n<script type=\"text/javascript\">\r\n// <!--\r\n	\r\n		$(\"#edit_post_{$pid}\").popupMenu();\r\n	\r\n// -->\r\n</script>\r\n</div>\r\n<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xx-none\">\r\n<a href=\"editpost.php?pid={$row[\'id\']}\" class=\"links\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;Edit</a>	\r\n</div>','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('3039','comment_posturl','<a name=\"pid{$row[\'id\']}\" id=\"pid{$row[\'id\']}\"></a>\r\n<a href=\"{$postlink}#pid{$pid}\" title=\"{$torrent_name}\">#{$post_number}</a>\r\n\r\n<div class=\"form-check form-check-inline ms-2\">\r\n    <input class=\"form-check-input comment-checkbox\" type=\"checkbox\" \r\n           name=\"comment_ids[]\" \r\n           value=\"{$row[\'id\']}\" \r\n           data-tid=\"{$row[\'torrentid\']}\" \r\n           onchange=\"toggleMassDeleteButton()\"\r\n           id=\"comment-checkbox-{$row[\'id\']}\">\r\n    <label class=\"form-check-label small\" for=\"comment-checkbox-{$row[\'id\']}\">\r\n       \r\n    </label>\r\n</div>','2','0','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('3099','comment_quickdelete','<a href=\"{$BASEURL}/{$edit}comment.php?action=delete&amp;pid={$row[\'id\']}&amp;tid={$row[\'torrentid\']}\" id=\"quick_delete_{$post[\'pid\']}\" title=\"{$postbit_qdelete}\" class=\"postbit_qdelete postbit_mirage dropdown-item\">\r\n		<i class=\"fa-solid fa-trash\"></i> &nbsp;Delete</a>','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('3064','comment_editreason','<div class=\"editreason\" id=\"editreason_{$pid}_original\" style=\"display: none;\">\r\n	        <input type=\"text\" class=\"form-control border mb-2\" style=\"margin: 6px 0;\" name=\"editreason\" size=\"40\" maxlength=\"150\" id=\"quickedit_{$pid}_editreason_original\" placeholder=\"{$lang->global[\'postbit_editreason\']}...\" value=\"{$post[\'editreason\']}\" />\r\n	        </div>','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('3071','commenttable','($postcounter == 1 ? \'\' : \'<br />\') . \'\r\n		\r\n			\' . ($postcounter == 1 ? \'\r\n				\r\n    </br>\r\n    \r\n	\r\n	<div class=\"container-md\">\r\n  <div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n		$toname}\r\n	</div>\r\n	 </div>\r\n		</div>\r\n	\r\n			\' : \'\') . \'\r\n\r\n\r\n	<div class=\"container mt-3\">\r\n	\r\n	\r\n<!-- begin new layout -->\r\n	\r\n\r\n<a name=\"pid{$pid}\" id=\"pid{$post[\'pid\']}\"></a>\r\n<div class=\"row g-2 mb-4\" style=\"{$post_visibility}\" id=\"post_{$pid}\">\r\n<div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">{$post[\'useravatar\']}</div>\r\n<div class=\"col\">\r\n<div class=\"card\">\r\n<div class=\"card-body inline_row {$unapproved_shade}\">\r\n				\r\n<div class=\"row m-0 p-0 mb-3 mb-sm-3 mb-md-3 mb-lg-0 mb-xl-0 mb-xxl-0\">\r\n<div class=\"col-auto d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none m-0 p-0 me-2 me-sm-2 me-md-2 me-lg-0 me-xl-0 me-xxl-0 align-self-center\">\r\n{$post[\'useravatar\']}\r\n</div>\r\n<div class=\"col m-0 p-0 align-self-center\">\r\n<h6 class=\"card-title mb-0 mb-sm-0 mb-md-0 mb-lg-3 mb-xl-3 mb-xxl-3\"><span style=\"font-weight: 700\">{$post[\'profilelink\']}</span> {$post[\'onlinestatus\']} &nbsp;&nbsp;<span class=\"text-uppercase text-desc small fw-normal\">{$post[\'postdate\']}</span></span></h6>\r\n</div>\r\n<div class=\"col-auto m-0 p-0 align-self-center text-end text-14\">\r\n{$post[\'posturl\']}\r\n</div>\r\n</div>\r\n		\r\n\r\n<div  class=\"post_body scaleimages\" id=\"pid_{$pid}\">\r\n{$post[\'message\']}\r\n\r\n</div>	\r\n\r\n\r\n\r\n\r\n\r\n<span class=\"post_edit\" id=\"edited_by_{$post[\'pid\']}\">{$post[\'editedmsg\']}</span>			\r\n{$post[\'signature\']}\r\n{$post[\'poststatus\']}	{$post[\'input_editreason\']}{$post[\'iplogged\']}			\r\n</div>\r\n<div class=\"card-footer border-top-0 py-2 my-0\">\r\n			\r\n			<!-- hidden -->\r\n<div class=\"row mt-0 pt-0 mb-0 pb-0\">\r\n<div class=\"col-auto align-self-center small text-start pe-0 me-0\">\r\n{$post[\'button_multiquote\']}</div>	\r\n\r\n<div class=\"col-auto align-self-center small text-start pe-0 me-0\">\r\n{$post[\'button_rep\']}</div>	\r\n\r\n<div class=\"col align-self-center small text-end\">\r\n{$post[\'button_edit\']}\r\n</div>\r\n\r\n<div class=\"col-auto text-end align-self-center\">\r\n<div class=\"hidden-text\"><div class=\"dropdown d-flex justify-content-end align-self-center\"><a class=\"bg-transparent border-0 text-muted\" aria-expanded=\"true\" data-bs-toggle=\"dropdown\" role=\"button\">&nbsp;<i class=\"fa-solid fa-ellipsis-vertical\"></i>&nbsp;</a>\r\n<div class=\"dropdown-menu border\">\r\n{$post[\'button_quote\']}\r\n{$post[\'button_quickdelete\']}\r\n{$post[\'button_quickrestore\']}\r\n{$post[\'button_report\']}\r\n{$post[\'button_warn\']}\r\n{$post[\'button_reply_pm\']}\r\n{$post[\'button_replyall_pm\']}\r\n{$post[\'button_forward_pm\']}\r\n{$post[\'button_delete_pm\']}\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- /hidden -->\r\n</div>		\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n</div>','2','1837','','1728810794');
